INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8ffe8bd-a239-4697-b3cc-9b2fde8f19a3', '看桑', '看桑', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["簇簇互相遮，閑看實可嗟。","藉多雖是葉，栽盛不如花。","春綠暗連麥，秋乾暮立鴉。","舊鄉曾種得，經亂屬誰家。"]', '["簇簇互相遮，闲看實可嗟。","藉多雖是葉，栽盛不如花。","春綠暗連麦，秋乾暮立鴉。","旧乡曾種得，經亂屬誰家。"]', '诗', 'shi', '', NULL, '看桑 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2e2620a-5678-48a6-a3d6-0a9f434ea948', '僊都山留題', '僊都山留題', '4948b49a-edd7-47ad-a807-0b3c50b2af26', '唐', '["林下事無非，塵中竟不知。","白雲深擁我，青石合眠誰。","山靜擣靈藥，夜閑論古詩。","此來親羽客，何日變枯髭。"]', '["林下事無非，塵中竟不知。","白云深擁我，青石合眠誰。","山静擣靈藥，夜闲論古诗。","此来親羽客，何日变枯髭。"]', '诗', 'shi', '', NULL, '僊都山留題 劉昭禹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0815a7af-9951-44db-8b8a-cdb33c8bb82e', '晚霽望嶽𪋤', '晚霽望嶽𪋤', '4948b49a-edd7-47ad-a807-0b3c50b2af26', '唐', '["湘西斜日邊，峭入幾尋天。","翠落重城內，屏開萬戶前。","崖崚危濺瀑，林罅靜通仙。","誰肯功成後，相攜掃石眠。"]', '["湘西斜日邊，峭入幾尋天。","翠落重城內，屏开万戶前。","崖崚危濺瀑，林罅静通仙。","誰肯功成後，相携掃石眠。"]', '诗', 'shi', '', NULL, '晚霽望嶽𪋤 劉昭禹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9d6cb4f-d686-4d2d-903e-44a3b7ac0464', '石筍', '石筍', '4948b49a-edd7-47ad-a807-0b3c50b2af26', '唐', '["千古海門石，移歸吟叟居。","竅腥蛟出後，形瘦浪衝餘。","工語寧無玉，僧知忽有書。","好期仙者叱，變化向庭隅。"]', '["千古海门石，移归吟叟居。","竅腥蛟出後，形瘦浪衝餘。","工語寧無玉，僧知忽有书。","好期仙者叱，变化向庭隅。"]', '诗', 'shi', '', NULL, '石筍 劉昭禹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34b5ba00-8cf1-4716-a4cf-930d79e8dd0f', '傷雨後牡丹', '傷雨後牡丹', '4948b49a-edd7-47ad-a807-0b3c50b2af26', '唐', '["廢功看不已，醉起又持杯。","數日簾常卷，中宵雨忽來。","淒涼無戲蝶，零落在蒼苔。","造化根難問，令人首可迴。"]', '["廢功看不已，醉起又持杯。","數日簾常卷，中宵雨忽来。","淒涼無戲蝶，零落在蒼苔。","造化根难问，令人首可迴。"]', '诗', 'shi', '', NULL, '傷雨後牡丹 劉昭禹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99b8ef9b-a83a-474b-8fdb-ae3a4e053f98', '送人紅花栽', '送人紅花栽', '4948b49a-edd7-47ad-a807-0b3c50b2af26', '唐', '["世上紅蕉異，因移萬里根。","艱難離瘴土，瀟灑入朱門。","葉戰青雲韻，花零宿露痕。","長安多未識，誰想動吟魂。"]', '["世上紅蕉異，因移万里根。","艱难離瘴土，瀟灑入朱门。","葉戰青云韻，花零宿露痕。","长安多未識，誰想动吟魂。"]', '诗', 'shi', '', NULL, '送人紅花栽 劉昭禹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15b82936-4e4d-4f17-b1cf-2ea9674b4b14', '曉望', '晓望', '9f6a2436-76fb-445f-9c32-d6c6c73404ca', '唐', '["地祇逃秀境，神化或殷雷。","裂漢媧補合，高峰劒躍開。","即今新定業，何世不遺才。","若是浮名道，須言有禍胎。"]', '["地祇逃秀境，神化或殷雷。","裂漢媧補合，高峰劒躍开。","即今新定業，何世不遺才。","若是浮名道，須言有禍胎。"]', '诗', 'shi', '', NULL, '曉望 劉乙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7ff7d4a-095a-4294-9fc5-b63d9943da50', '山中早起', '山中早起', '9f6a2436-76fb-445f-9c32-d6c6c73404ca', '唐', '["雞調扶桑枝，秋空隱少微。","闊雲霞並曜，高日月爭輝。","若厥開天道，同初發帝機。","以言當代事，閑闢紫宸扉。"]', '["雞調扶桑枝，秋空隐少微。","闊云霞並曜，高日月爭輝。","若厥开天道，同初發帝機。","以言當代事，闲闢紫宸扉。"]', '诗', 'shi', '', NULL, '山中早起 劉乙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d09de01e-46be-4519-95fd-84305497a0e7', '晚步', '晚步', '44f86e00-3555-40a7-a698-adcd2de7b751', '唐', '["陋巷貧疑本姓顏，晚來閑步出林間。","數聲長笛吹沈日，一片殘雲點破山。","島寺漸疎敲石磬，漁家方半掩柴關。","遲迴從此搜吟久，待得溪頭月上還。"]', '["陋巷貧疑本姓顏，晚来闲步出林间。","數声长笛吹沈日，一片殘云点破山。","島寺漸疎敲石磬，漁家方半掩柴关。","遲迴從此搜吟久，待得溪头月上還。"]', '诗', 'shi', '', NULL, '晚步 姚揆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5393e3e-bd78-4191-a8b9-3f72d83cc88f', '秋日江東晚行', '秋日江东晚行', '44f86e00-3555-40a7-a698-adcd2de7b751', '唐', '["迢迢驅馬過江東，此際令人恨莫窮。","一撮秋煙堤上白，半輪殘日嶺頭紅。","路岐滋味猶如舊，鄉曲聲音漸不同。","含思看看到梁苑，畫樓絲竹徹遙空。"]', '["迢迢驱马過江东，此際令人恨莫窮。","一撮秋煙堤上白，半輪殘日嶺头紅。","路岐滋味猶如旧，乡曲声音漸不同。","含思看看到梁苑，畫楼絲竹徹遙空。"]', '诗', 'shi', '', NULL, '秋日江東晚行 姚揆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2e4e36b-8a58-4fdd-b8bc-038eb90343e9', '題陶淵明醉石', '題陶淵明醉石', '2a22b467-4024-411f-a6b5-855957cd08f9', '唐', '["片石露寒色，先生遺素風。","醉眠芳草合，吟起白雲空。","道出乾坤外，聲齊日月中。","我知彭澤後，千載與誰同。"]', '["片石露寒色，先生遺素风。","醉眠芳草合，吟起白云空。","道出乾坤外，声齊日月中。","我知彭澤後，千載與誰同。"]', '诗', 'shi', '', NULL, '題陶淵明醉石 陳光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('373f9734-c5bc-41c2-94a0-390f3ba37cb2', '長安新柳', '长安新柳', '2a22b467-4024-411f-a6b5-855957cd08f9', '唐', '["九陌雲初霽，皇衢柳已新。","不同天苑景，先得日邊春。","色淺微含露，絲輕未惹塵。","一枝方欲折，歸去及茲晨。"]', '["九陌云初霽，皇衢柳已新。","不同天苑景，先得日邊春。","色淺微含露，絲轻未惹塵。","一枝方欲折，归去及茲晨。"]', '诗', 'shi', '', NULL, '長安新柳 陳光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a3ce3af-8c7f-453f-952a-49939e8abf67', '雪晴', '雪晴', '8077d785-889a-4445-9266-15e590cb382a', '唐', '["春來冰未泮，冬至雪初晴。","爲報方袍客，豐年瑞已成。"]', '["春来冰未泮，冬至雪初晴。","爲報方袍客，豐年瑞已成。"]', '诗', 'shi', '', NULL, '雪晴 楊凝式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dba889e3-1712-437e-9dca-bd9a3bda0c05', '上安祿山', '上安祿山', '68babf36-4f9e-439f-8f93-97c26f4b5f28', '唐', '["象曰雲雷屯，大君理經綸。","馬上取天下，雪中朝海神。"]', '["象曰云雷屯，大君理經綸。","马上取天下，雪中朝海神。"]', '诗', 'shi', '', NULL, '上安祿山 盧言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ebe714d-e88c-4b5b-8a3a-6646649749a9', '儲潭廟', '儲潭廟', 'b9df6e3d-9d15-4d38-8d8f-323541f3df7a', '唐', '["江水上源急如箭，潭北轉急令目眩。","中間十里澄漫漫，龍蛇若見若不見。","老農老圃望天語，儲潭之神可致雨。","質明齋服躬往奠，牢醴豐潔精誠舉。","女巫紛紛堂下儛，色似授兮意似與。","雲在山兮風在林，風雲忽起潭更深。","氣霾祠宇連江陰，朝日不復照翠岑。","迴溪口兮櫂清流，好風帶雨送到州。","吏人雨立喜再拜，神兮靈兮如獻酬。","城上樓兮危架空，登四望兮暗濛濛。","不知兮千萬里，惠澤願兮與之同。","我有言兮報匪徐，車騎復往禮如初。","高垣墉兮大其門，灑掃丹雘壯神居。","使過廟者之加敬，酒食貨財而有餘。","神兮靈，神兮靈，匪享慢，享克誠。"]', '["江水上源急如箭，潭北轉急令目眩。","中间十里澄漫漫，龙蛇若见若不见。","老農老圃望天語，儲潭之神可致雨。","質明斋服躬往奠，牢醴豐潔精誠舉。","女巫紛紛堂下儛，色似授兮意似與。","云在山兮风在林，风云忽起潭更深。","氣霾祠宇連江陰，朝日不复照翠岑。","迴溪口兮櫂清流，好风带雨送到州。","吏人雨立喜再拜，神兮靈兮如獻酬。","城上楼兮危架空，登四望兮暗濛濛。","不知兮千万里，惠澤願兮與之同。","我有言兮報匪徐，车騎复往禮如初。","高垣墉兮大其门，灑掃丹雘壯神居。","使過廟者之加敬，酒食貨財而有餘。","神兮靈，神兮靈，匪享慢，享克誠。"]', '诗', 'shi', '', NULL, '儲潭廟 裴諝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45ca4e35-8adb-47d5-b3f0-fe03dfbf3b7e', '臘月中與韋戶曹游發生洞裴回之際見雙白蝙蝠三飛洞門時多異之同爲口號', '臘月中與韋戶曹游發生洞裴回之際见雙白蝙蝠三飞洞门时多異之同爲口號', '92a9714c-d9d3-43e8-b4c6-4a41f4b6acd0', '唐', '["山翠羃靈洞，洞深玄想微。","一雙白蝙蝠，三度向明飛。","雖然有兩翅，了自無毛衣。","若非飽石髓，那得凌□□。","偶見歸堪說，殊勝不見歸。"]', '["山翠羃靈洞，洞深玄想微。","一雙白蝙蝠，三度向明飞。","雖然有兩翅，了自無毛衣。","若非飽石髓，那得凌□□。","偶见归堪说，殊勝不见归。"]', '诗', 'shi', '', NULL, '臘月中與韋戶曹游發生洞裴回之際見雙白蝙蝠三飛洞門時多異之同爲口號 任要 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b257a1b-97a8-4299-a51d-7ac311cf30e7', '臘月中遊發生洞裴回之際見雙白蝙蝠三飛洞門時多異之同爲口號', '臘月中游發生洞裴回之際见雙白蝙蝠三飞洞门时多異之同爲口號', 'ad3cf0e7-207d-439e-87fe-96293cd1cf3c', '唐', '["欲驗發生洞，先開冰雪行。","窺臨見二翼，色素飛無聲。","狀類白蝙蝠，幽感騰化精。","應知五馬來，啓蟄迎春榮。","露冕□之久，鳴騶還慰情。"]', '["欲驗發生洞，先开冰雪行。","窺臨见二翼，色素飞無声。","狀類白蝙蝠，幽感腾化精。","應知五马来，啓蟄迎春榮。","露冕□之久，鳴騶還慰情。"]', '诗', 'shi', '', NULL, '臘月中遊發生洞裴回之際見雙白蝙蝠三飛洞門時多異之同爲口號 韋洪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3191956-7b6e-4843-9ddf-7448eb40e1f2', '蜀中經蠻後寄陶雍', '蜀中經蠻後寄陶雍', 'be4910e6-95d7-459d-99d4-5a37deb3b6c8', '唐', '["酋馬渡瀘水，北來如鳥輕。","幾年期鳳闕，一日破龜城。","此地有征戰，誰家無死生。","人悲還舊里，鳥喜下空營。","弟姪意初定，交朋心尚驚。","自從經難後，吟苦似猨聲。"]', '["酋马渡瀘水，北来如鸟轻。","幾年期鳳闕，一日破龟城。","此地有征戰，誰家無死生。","人悲還旧里，鸟喜下空營。","弟姪意初定，交朋心尚驚。","自從經难後，吟苦似猨声。"]', '诗', 'shi', '', NULL, '蜀中經蠻後寄陶雍 馬乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f68a86b-19ff-4bbd-b476-4ff05dcc8fd3', '沖佑觀', '沖佑观', '22d4d15f-3046-4e5e-817e-d47b6de07189', '唐', '["大始未形，混沌無際。","上下開運，乾坤定位。","日月麗天，山川鎮地。","萬彙猶屯，三才始備。","肇有神化，初生蒸民。","上惟立德，下無疎親。","皇風蕩蕩，黔首淳淳。","天下有道，誰非聖人。","開源嗜慾，澆漓俗盛。","賢者避世，真人華命。","八極神鄉，十州異境。","翠阜丹丘，潛伏靈聖。","惟彼武夷，實曰洞天。","峰巒黛染，巖岫霞鮮。","金房玉室，羽蓋雲軿。","葬日風雨，會有神仙。","國步多艱，皇綱中絕。","四海九州，瓜分幅裂。","稔禍陬隅，阻兵甌越。","寂寞玄風，荒涼絳闕。","赫赫烈祖，再造丕基。","拱揖高讓，神人樂推。","明明我后，允協昌基。","功崇下武，德茂重熙。","睿哲英斷，雄畧神智。","拓土開疆，經天緯地。","五嶺來庭，三湘清徹。","四海震威，羣生懷惠。","猶勞宵旰，猶混馬車。","貪狼俟靜，害焉方除。","淹留駿馭，想像鶉居。","心懸真洞，夢到華胥。","乃眷名山，追惟聖跡。","內庫頒金，元侯奉職。","三境求規，五靈取則。","跨谷彌岡，張霄架極。","珠宮寶殿，璇臺玉堂。","鳳翔高甍，龍轉迴廊。","錯落金碧，玲瓏璧璫。","雲生林楚，雷繞藩牆。","七聖斯嚴，三君如在。","八景靈[輿]，九華神蓋。","清霄莫胥，明霜匪對。","彷彿壺中，依稀物外。","衆真之宇，擬之無倫。","會僊之類，名之惟新。","高峰爲壑，區谷成坰。","皇獻頌聲，永絕淄磷。"]', '["大始未形，混沌無際。","上下开運，乾坤定位。","日月丽天，山川鎮地。","万彙猶屯，三才始備。","肇有神化，初生蒸民。","上惟立德，下無疎親。","皇风蕩蕩，黔首淳淳。","天下有道，誰非聖人。","开源嗜慾，澆漓俗盛。","賢者避世，真人华命。","八極神乡，十州異境。","翠阜丹丘，潛伏靈聖。","惟彼武夷，實曰洞天。","峰巒黛染，巖岫霞鲜。","金房玉室，羽蓋云軿。","葬日风雨，會有神仙。","国步多艱，皇綱中絕。","四海九州，瓜分幅裂。","稔禍陬隅，阻兵甌越。","寂寞玄风，荒涼絳闕。","赫赫烈祖，再造丕基。","拱揖高讓，神人乐推。","明明我后，允協昌基。","功崇下武，德茂重熙。","睿哲英斷，雄畧神智。","拓土开疆，經天緯地。","五嶺来庭，三湘清徹。","四海震威，羣生懷惠。","猶勞宵旰，猶混马车。","貪狼俟静，害焉方除。","淹留駿馭，想像鶉居。","心懸真洞，梦到华胥。","乃眷名山，追惟聖跡。","內庫頒金，元侯奉職。","三境求規，五靈取則。","跨谷彌岡，張霄架極。","珠宮寶殿，璇台玉堂。","鳳翔高甍，龙轉迴廊。","錯落金碧，玲瓏璧璫。","云生林楚，雷繞藩牆。","七聖斯嚴，三君如在。","八景靈[輿]，九华神蓋。","清霄莫胥，明霜匪对。","彷彿壺中，依稀物外。","衆真之宇，擬之無倫。","會僊之類，名之惟新。","高峰爲壑，區谷成坰。","皇獻頌声，永絕淄磷。"]', '诗', 'shi', '', NULL, '沖佑觀 張紹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('442510f6-107a-4c0d-9976-bb785ad60758', '徹雲澗', '徹云澗', '22209c44-4c34-464e-ac24-b3a074f8fadf', '唐', '["延綿不可窮，寒光徹雲際。","落石早雷鳴，濺空春雨細。"]', '["延綿不可窮，寒光徹云際。","落石早雷鳴，濺空春雨細。"]', '诗', 'shi', '', NULL, '徹雲澗 鄭露 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6960106b-1534-4af8-986b-b72d3371d90f', '秋氣尚高涼', '秋氣尚高涼', '02357c77-9123-4351-b568-7c2fc42c97d6', '唐', '["秋氣尚高涼，寒笛吹萬木。","故人入我庭，相照不出屋。","[山]川雖遠觀，高懷不能掬。"]', '["秋氣尚高涼，寒笛吹万木。","故人入我庭，相照不出屋。","[山]川雖远观，高懷不能掬。"]', '诗', 'shi', '', NULL, '秋氣尚高涼 林披 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8277c384-707a-4003-877d-889ccc98cd9c', '五言贈諸法師', '五言贈諸法師', '1ebe31e1-a7ea-4b39-8fbc-154ac8946c58', '唐', '["駕鶴排朱霧，乘鸞入紫煙。","凌晨味潭菊，薄暮翫峰蓮。","玉葉低梁下，金飀引窗前。","嘯傲雲霞際，留情鱗羽年。"]', '["駕鹤排朱霧，乘鸾入紫煙。","凌晨味潭菊，薄暮翫峰蓮。","玉葉低梁下，金飀引窗前。","嘯傲云霞際，留情鱗羽年。"]', '诗', 'shi', '', NULL, '五言贈諸法師 公孫杲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d62498da-feb2-46cd-99bf-755b2d58fab4', '恆岳晨望有懷', '恆岳晨望有懷', 'b01f8413-b60b-43cd-a4dd-ffc277a693a2', '唐', '["二儀均四序，五嶽分九州。","靈造良難測，神功匪易酬。","恆山北臨岱，秀崿東跨幽。","澒洞鎮河朔，嵯峨冠嵩丘。","禋祠彰舊典，壇廟列平疇。","古樹侵雲密，飛泉界道流。","從官叨佐理，銜命奉珍羞。","薦玉申誠效，鏘金諒有由。","郊原照初日，林薄委徂秋。","塞近風聲厲，川長霧氣收。","他鄉饒感激，歸望切祈求。","景福如光願，私門當復侯。"]', '["二儀均四序，五嶽分九州。","靈造良难測，神功匪易酬。","恆山北臨岱，秀崿东跨幽。","澒洞鎮河朔，嵯峨冠嵩丘。","禋祠彰旧典，壇廟列平疇。","古樹侵云密，飞泉界道流。","從官叨佐理，銜命奉珍羞。","薦玉申誠效，鏘金諒有由。","郊原照初日，林薄委徂秋。","塞近风声厲，川长霧氣收。","他乡饒感激，归望切祈求。","景福如光願，私门當复侯。"]', '诗', 'shi', '', NULL, '恆岳晨望有懷 李敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0967c78c-71cb-4c41-8593-cd1e79f66010', '偶宴西蜀摩訶池', '偶宴西蜀摩訶池', 'f13d9625-348b-4fc3-bf28-a31306ffa073', '唐', '["珍木鬱清池，風荷左右披。","淺觴寧及醉，慢舸不知移。","蔭林簟光冷，照流簪影攲。","胡爲獨羈者，雪涕向漣漪。"]', '["珍木鬱清池，风荷左右披。","淺觴寧及醉，慢舸不知移。","蔭林簟光冷，照流簪影攲。","胡爲独羈者，雪涕向漣漪。"]', '诗', 'shi', '', NULL, '偶宴西蜀摩訶池 暢甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf6145e9-0387-4985-a218-f9c111ff2187', '飲後獻時相', '饮後獻时相', 'f03671fb-7d42-4941-aaf1-540ffa431a93', '唐', '["一夕心期一種歡，那知疎散負杯盤。","尊前數片朝雲在，不許馮公子細看。"]', '["一夕心期一種歡，那知疎散負杯盤。","尊前數片朝云在，不許馮公子細看。"]', '诗', 'shi', '', NULL, '飲後獻時相 吳士矩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38ebcfad-d617-45f5-9958-9b1e46416659', '失題', '失題', '1ae32553-ac1c-4008-97a3-1819b99da32c', '唐', '["故國海雲端，歸寧便整鞍。","里榮身上蒨，省罷手中蘭。","燒急平蕪廣，風悲古木寒。","謝公山色在，朝夕共誰觀。"]', '["故国海云端，归寧便整鞍。","里榮身上蒨，省罷手中蘭。","燒急平蕪廣，风悲古木寒。","謝公山色在，朝夕共誰观。"]', '诗', 'shi', '', NULL, '失題 吳黔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80a62b2d-a794-4dd5-8199-53cab6d5bdcd', '題惠聚寺', '題惠聚寺', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["人莫嫌山小，僧還愛寺靈。","殿高神氣力，龍活客丹青。"]', '["人莫嫌山小，僧還愛寺靈。","殿高神氣力，龙活客丹青。"]', '诗', 'shi', '', NULL, '題惠聚寺 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0beba8e6-fe30-40e6-a800-232fda0f31df', '平望贈蚊', '平望贈蚊', 'bbf48032-c237-4235-a437-8d6ccd864a0e', '唐', '["安得神仙術，試爲施康濟。","使此平望村，如吾江子匯。"]', '["安得神仙術，試爲施康濟。","使此平望村，如吾江子匯。"]', '诗', 'shi', '', NULL, '平望贈蚊 錢信 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a872373f-04df-41f1-a7d7-1e7446a13d3a', '武康碧落觀', '武康碧落观', '7b22ffeb-210b-43de-8d7b-588a069ac6e5', '唐', '["仙宮碧落太微書，遺蹟依然掩故居。","幢節不歸天杳邈，煙霞空鎖日幽虛。","不逢金簡扳雲洞，可惜瑤臺疊蘚除。","欲脫儒衣陪羽客，傷心齒髮已凋疎。"]', '["仙宮碧落太微书，遺蹟依然掩故居。","幢節不归天杳邈，煙霞空鎖日幽虛。","不逢金簡扳云洞，可惜瑤台叠蘚除。","欲脫儒衣陪羽客，傷心齒髮已凋疎。"]', '诗', 'shi', '', NULL, '武康碧落觀 胡傳美 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac67c640-ab86-4d87-8bf8-e59ec4be20e8', '白雲寺', '白云寺', 'b2d2ed17-4c76-4950-bfd7-a8b5601280c3', '唐', '["踏破苔痕一逕斑，白雲飛處見青山。","不知浮世塵中客，幾箇能知物外閑。"]', '["踏破苔痕一逕斑，白云飞处见青山。","不知浮世塵中客，幾箇能知物外闲。"]', '诗', 'shi', '', NULL, '白雲寺 許宏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a463edf8-c831-4242-8a82-312b608fa929', '羅浮山', '羅浮山', '7b96e164-cbfc-418e-8bcb-638fb839b60f', '唐', '["羅浮多勝境，夢到固無因。","知有長生藥，誰爲不死人。","根雖盤地脉，勢自倚天津。","未便甘休去，須棲老此身。"]', '["羅浮多勝境，梦到固無因。","知有长生藥，誰爲不死人。","根雖盤地脉，勢自倚天津。","未便甘休去，須棲老此身。"]', '诗', 'shi', '', NULL, '羅浮山 文丙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8550c82-6ace-43c8-85d7-aa36d0edc75e', '牡丹', '牡丹', '7b96e164-cbfc-418e-8bcb-638fb839b60f', '唐', '["萬物承春各鬬奇，百花分貴近亭池。","開時若也姮娥見，落日那堪公子知。","詩客筵中金琖滿，美人頭上玉釵垂。","不同寒菊舒重九，只擬清香泛酒巵。"]', '["万物承春各鬬奇，百花分貴近亭池。","开时若也姮娥见，落日那堪公子知。","诗客筵中金琖满，美人头上玉釵垂。","不同寒菊舒重九，只擬清香泛酒巵。"]', '诗', 'shi', '', NULL, '牡丹 文丙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6372a20-80dd-4271-8666-cfd4faef92f2', '蘚花', '蘚花', '7b96e164-cbfc-418e-8bcb-638fb839b60f', '唐', '["寂寞人偏重，無心媿牡丹。","秋風凋不得，流水泛應難。","怪石從教徧，幽庭一任盤。","若逢公子顧，重疊是朱欄。"]', '["寂寞人偏重，無心媿牡丹。","秋风凋不得，流水泛應难。","怪石從教徧，幽庭一任盤。","若逢公子顧，重叠是朱欄。"]', '诗', 'shi', '', NULL, '蘚花 文丙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0fc1dda-2f52-4d90-9a5d-b01ee817445e', '新栽松', '新栽松', '7b96e164-cbfc-418e-8bcb-638fb839b60f', '唐', '["可憐同百草，況負雪霜姿。","歌舞地不尚，歲寒人自移。","堦除添冷淡，毫末入思惟。","盡道生雲洞，誰知露嶮巇。"]', '["可怜同百草，況負雪霜姿。","歌舞地不尚，歲寒人自移。","堦除添冷淡，毫末入思惟。","尽道生云洞，誰知露嶮巇。"]', '诗', 'shi', '', NULL, '新栽松 文丙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c410ada-1bc1-49b9-a9f1-02bb71ad66cc', '柳', '柳', '7b96e164-cbfc-418e-8bcb-638fb839b60f', '唐', '["何事動吟哦，長□翠色和。","垂陰千樹少，送別一枝多。","帶霧籠彭澤，搖風舞汴河。","只因隋帝植，民力幾銷磨。"]', '["何事动吟哦，长□翠色和。","垂陰千樹少，送別一枝多。","带霧籠彭澤，搖风舞汴河。","只因隋帝植，民力幾銷磨。"]', '诗', 'shi', '', NULL, '柳 文丙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03571e92-3df9-457b-ad8f-59810522e49c', '仙巖四瀑布即事寄上祕書包監侍郎七兄吏部李侍郎十七兄婺州趙中丞處州齊諫議明州李九郎十四韻', '仙巖四瀑布即事寄上祕书包監侍郎七兄吏部李侍郎十七兄婺州趙中丞处州齊諫議明州李九郎十四韻', '8b2ea6c1-3953-4879-8aa7-75a36edbd429', '唐', '["絕境久蒙蔽，芟蘿方迨茲。","樵蘇尚未及，冠冕誰能知。","緣崖開逕小，架木度空危。","水激千雷發，珠聯萬貫垂。","陰晴狀非一，昏旦勢多奇。","井識軒轅跡，壇餘漢武基。","猨聲響深洞，巖影倒澄池。","想像虬龍去，依稀羽客隨。","翫奇目豈倦，尋異神忘疲。","干雲松作蓋，積翠薜成帷。","含意攀丹桂，凝情顧紫芝。","芸香藹芳氣，冰鏡徹圓規。","胥念滄波遠，徒懷魏闕期。","徵黃應計日，莫鄙北山移。"]', '["絕境久蒙蔽，芟蘿方迨茲。","樵蘇尚未及，冠冕誰能知。","緣崖开逕小，架木度空危。","水激千雷發，珠聯万貫垂。","陰晴狀非一，昏旦勢多奇。","井識軒轅跡，壇餘漢武基。","猨声响深洞，巖影倒澄池。","想像虬龙去，依稀羽客隨。","翫奇目豈倦，尋異神忘疲。","干云松作蓋，積翠薜成帷。","含意攀丹桂，凝情顧紫芝。","芸香藹芳氣，冰镜徹圓規。","胥念滄波远，徒懷魏闕期。","徵黄應計日，莫鄙北山移。"]', '诗', 'shi', '', NULL, '仙巖四瀑布即事寄上祕書包監侍郎七兄吏部李侍郎十七兄婺州趙中丞處州齊諫議明州李九郎十四韻 路應 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6543b844-5b3c-47c5-81fa-19e5d66a297d', '奉和郎中遊仙巖四瀑布寄包祕監李吏部趙婺州中丞齊處州諫議十四韻', '奉和郎中游仙巖四瀑布寄包祕監李吏部趙婺州中丞齊处州諫議十四韻', '4f3803c9-b5da-4fa0-b265-2ff890aae73d', '唐', '["符守分珪組，放情在丘巒。","悠然造雲族，忽爾登天壇。","求古理方賾，翫奇物不殫。","晴光散崖壁，瑞氣生芝蘭。","中有四瀑水，奔流狀千般。","風雲隱巖底，雨雪霏林端。","晶晶含古色，颼颼引晨寒。","澄潭見猨飲，潛穴知龍盤。","坐憩苔石遍，仰窺杉桂攢。","幽蹊創高躅，靈藥餘仙飱。","攜賞喜康樂，示文驚建安。","縑緗炳珠寶，中外貽同官。","末調亦何爲，輒陪高唱難。","慙非御徒者，還得依門欄。"]', '["符守分珪組，放情在丘巒。","悠然造云族，忽爾登天壇。","求古理方賾，翫奇物不殫。","晴光散崖壁，瑞氣生芝蘭。","中有四瀑水，奔流狀千般。","风云隐巖底，雨雪霏林端。","晶晶含古色，颼颼引晨寒。","澄潭见猨饮，潛穴知龙盤。","坐憩苔石遍，仰窺杉桂攢。","幽蹊創高躅，靈藥餘仙飱。","携賞喜康乐，示文驚建安。","縑緗炳珠寶，中外貽同官。","末調亦何爲，輒陪高唱难。","慙非御徒者，還得依门欄。"]', '诗', 'shi', '', NULL, '奉和郎中遊仙巖四瀑布寄包祕監李吏部趙婺州中丞齊處州諫議十四韻 李縝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5a000ba-4d74-413c-9312-8855b9ace078', '奉和郎中遊仙山四瀑泉兼寄李吏部包祕監趙婺州齊處州', '奉和郎中游仙山四瀑泉兼寄李吏部包祕監趙婺州齊处州', 'cebb4889-d0c7-48a5-8732-3ddad3008b44', '唐', '["今日永嘉守，復追山水遊。","因尋莽蒼野，遂得軒轅丘。","訪古事難究，覽新情屢周。","溪垂綠篠暗，巖度白雲幽。","過石奇不盡，出林香更浮。","憑高擁虎節，搏險窺龍湫。","淙潨瀉三四，奔騰千萬秋。","寒驚殷雷動，暑駭繁霜流。","沫濺羣鳥外，光搖數峰頭。","叢崖散滴瀝，近谷藏颼飀。","況此特形勝，自餘非等儔。","靈光掩五嶽，仙氣均十洲。","書以謝羣彥，永將敘徽猷。","當思共攀陟，東南看斗牛。"]', '["今日永嘉守，复追山水游。","因尋莽蒼野，遂得軒轅丘。","訪古事难究，覽新情屢周。","溪垂綠篠暗，巖度白云幽。","過石奇不尽，出林香更浮。","憑高擁虎節，搏險窺龙湫。","淙潨瀉三四，奔腾千万秋。","寒驚殷雷动，暑駭繁霜流。","沫濺羣鸟外，光搖數峰头。","叢崖散滴瀝，近谷藏颼飀。","況此特形勝，自餘非等儔。","靈光掩五嶽，仙氣均十洲。","书以謝羣彥，永將敘徽猷。","當思共攀陟，东南看斗牛。"]', '诗', 'shi', '', NULL, '奉和郎中遊仙山四瀑泉兼寄李吏部包祕監趙婺州齊處州 戴公懷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feac3b9d-1e0e-4165-bf45-c8e73d8a51b9', '奉和郎中遊仙山四瀑布兼寄李吏部包祕監判官', '奉和郎中游仙山四瀑布兼寄李吏部包祕監判官', 'f250ba68-60ae-45e6-a23f-af138899225a', '唐', '["昔人恣探討，飛流稱石門。","安知郡城側，別有神泉源。","疏鑿意大禹，勤求聞軒轅。","悠悠幾千歲，翳薈羣木繁。","奇狀出蔽蔓，勝概畢討論。","沿崖百丈落，奔注當空翻。","下如散雨足，上擬屯雲根。","變態凡幾處，靜神竟朝昏。","渴賢寄珠玉，受馥尋蘭蓀。","蘿蔦罥紫綬，巖隈駐朱轓。","方思謝康樂，好事名空存。"]', '["昔人恣探討，飞流稱石门。","安知郡城側，別有神泉源。","疏鑿意大禹，勤求闻軒轅。","悠悠幾千歲，翳薈羣木繁。","奇狀出蔽蔓，勝概畢討論。","沿崖百丈落，奔注當空翻。","下如散雨足，上擬屯云根。","变態凡幾处，静神竟朝昏。","渴賢寄珠玉，受馥尋蘭蓀。","蘿蔦罥紫綬，巖隈駐朱轓。","方思謝康乐，好事名空存。"]', '诗', 'shi', '', NULL, '奉和郎中遊仙山四瀑布兼寄李吏部包祕監判官 孟翔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8e44e64-1025-461e-bb50-b67b675cc4e3', '晚眺', '晚眺', 'b2bc88a2-8883-4241-8fd6-8b935b73e88c', '唐', '["江溶流落景，山色凝暮煙。","衰髮照秋日，壯心減昔年。","愁吟長抱膝，孰訴高高天。"]', '["江溶流落景，山色凝暮煙。","衰髮照秋日，壯心減昔年。","愁吟长抱膝，孰訴高高天。"]', '诗', 'shi', '', NULL, '晚眺 崔耿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42a843ee-5595-4cca-8304-653cb2f9cdd1', '山下泉', '山下泉', '17e221a5-3350-4a05-8c6d-44d628060203', '唐', '["可致清川廣，難量利物功。","涓流此山下，誰識去無窮。"]', '["可致清川廣，难量利物功。","涓流此山下，誰識去無窮。"]', '诗', 'shi', '', NULL, '山下泉 宇文鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e10a174b-95ed-44bc-826a-27722263e9fd', '永嘉經謝公石門山作', '永嘉經謝公石门山作', '91f16551-a8e2-4297-bca2-00dbfc6fe8b3', '唐', '["綿境經耳目，未嘗曠躋登。","一窺石門險，再滌心神懵。","洞壑閟金澗，欹崖盤石楞。","陰潭下羃羃，秀嶺上層層。","千丈瀑流蹇，半溪風雨絚。","興餘志每愜，心遠道自弘。","乘軺廣儲峙，祇命媿才能。","輟櫂周氣象，捫條歷騫崩。","忽如生羽翼，怳若將起騰。","謝客今已矣，我來誰與朋。"]', '["綿境經耳目，未嘗曠躋登。","一窺石门險，再滌心神懵。","洞壑閟金澗，欹崖盤石楞。","陰潭下羃羃，秀嶺上層層。","千丈瀑流蹇，半溪风雨絚。","兴餘志每愜，心远道自弘。","乘軺廣儲峙，祇命媿才能。","輟櫂周氣象，捫條歷騫崩。","忽如生羽翼，怳若將起腾。","謝客今已矣，我来誰與朋。"]', '诗', 'shi', '', NULL, '永嘉經謝公石門山作 郭密之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b4337c3-dce4-4f2f-8ccf-0d0423cbc096', '芳草', '芳草', '982a8311-725b-45b3-a655-9a0923e6a6ea', '唐', '["幽芳無處無，幽處恨何如。","倦客傷歸思，春風滿舊居。","晚煙迷杳靄，朝露健扶疎。","省傍靈光看，殘陽少皡區。"]', '["幽芳無处無，幽处恨何如。","倦客傷归思，春风满旧居。","晚煙迷杳靄，朝露健扶疎。","省傍靈光看，殘陽少皡區。"]', '诗', 'shi', '', NULL, '芳草 扈載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('175e031d-b606-4e6d-8e38-885d91b98377', '任閬中下鄉檢田登艾蕭山北望', '任閬中下乡檢田登艾蕭山北望', 'c50bcd65-ae88-4eb3-80cf-dbdde0165fe3', '唐', '["觀農巡井邑，長望歷山川。","擁澗開新耨，緣崖指火田。","荒村無徑陌，古戍有風煙。","瓠葉縈籬長，藤花繞架懸。","岸高攢樹石，水淨寫雲天。","迴首鄉關路，行歌猶喟然。"]', '["观農巡井邑，长望歷山川。","擁澗开新耨，緣崖指火田。","荒村無徑陌，古戍有风煙。","瓠葉縈籬长，藤花繞架懸。","岸高攢樹石，水淨寫云天。","迴首乡关路，行歌猶喟然。"]', '诗', 'shi', '', NULL, '任閬中下鄉檢田登艾蕭山北望 薛光謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bda7c151-ddf2-4a8f-b541-4b4b5ebec1a5', '府尹王侍郎准制拜嶽因狀嵩高靈勝寄呈三十韻', '府尹王侍郎准制拜嶽因狀嵩高靈勝寄呈三十韻', '7f069bb6-83a3-4c37-8600-1da429ca44dd', '唐', '["雄雄天之中，峻極聞維嵩。","作鎮盛標格，出雲爲雨風。","瑞時物不癘，順澤年多豐。","加高冠四方，視秩居三公。","明朝虔昭報，頒祀歲嚴恭。","署祝紆御札，詔賢導宸衷。","皇皇三川守，馨德清明躬。","肅徒奉蘭沐，竟夕玉華東。","星漢耿齋戶，松泉寒壽宮。","具修諒蠲吉，曙色猶葱曚。","端儀大圭立，興俛聲玲瓏。","挹瓚椒桂馥，奏金巖壑空。","靈歆若有荅，彷彿傳祝工。","卒事不遑偃，勝奇紛四叢。","朝霞破靈嶂，錯落間蒼紅。","動息形似蟻，玄黃氣如籠。","奔傾千萬狀，羣嶽安比崇。","日月襟袖捧，人天道路通。","冥搜必殫竭，躋覽忘崎穹。","踏翠徧諸剎，趣綿步難終。","浮丘仙袂接，謝公屐齒窮。","龍潭應下瞰，九曲當駭容。","龍門計東豁，三臺有何蹤。","金象語奚應，玉人光想融。","瑤漿與石髓，清骨宜遭逢。","況是降神處，跡惟申甫同。","周翰已洽論，伊衡亦期功。","誠富東山興，須陟中台庸。","勉促旋騑軨，未可戀雲松。","散材事即異，期爲卜一峰。"]', '["雄雄天之中，峻極闻維嵩。","作鎮盛標格，出云爲雨风。","瑞时物不癘，順澤年多豐。","加高冠四方，視秩居三公。","明朝虔昭報，頒祀歲嚴恭。","署祝紆御札，詔賢導宸衷。","皇皇三川守，馨德清明躬。","肅徒奉蘭沐，竟夕玉华东。","星漢耿斋戶，松泉寒壽宮。","具修諒蠲吉，曙色猶葱曚。","端儀大圭立，兴俛声玲瓏。","挹瓚椒桂馥，奏金巖壑空。","靈歆若有荅，彷彿傳祝工。","卒事不遑偃，勝奇紛四叢。","朝霞破靈嶂，錯落间蒼紅。","动息形似蟻，玄黄氣如籠。","奔傾千万狀，羣嶽安比崇。","日月襟袖捧，人天道路通。","冥搜必殫竭，躋覽忘崎穹。","踏翠徧諸剎，趣綿步难終。","浮丘仙袂接，謝公屐齒窮。","龙潭應下瞰，九曲當駭容。","龙门計东豁，三台有何蹤。","金象語奚應，玉人光想融。","瑤漿與石髓，清骨宜遭逢。","況是降神处，跡惟申甫同。","周翰已洽論，伊衡亦期功。","誠富东山兴，須陟中台庸。","勉促旋騑軨，未可戀云松。","散材事即異，期爲卜一峰。"]', '诗', 'shi', '', NULL, '府尹王侍郎准制拜嶽因狀嵩高靈勝寄呈三十韻 尉遲汾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('016d6087-76ec-46fd-969d-f721daaad52a', '早春陪敕使麻先生祭岳', '早春陪敕使麻先生祭岳', 'd618e03a-e445-4d64-b0b0-0f6e044fe9d9', '唐', '["我皇盛文物，道化天地先。","鞭撻走神鬼，玉帛禮山川。","忽下袁州使，來遊紫洞前。","青羊得處所，白鶴□時年。","虔懇飛龍記，昭彰化鳥篇。","□風半山水，□氣總雲煙。","光抱昇中日，霞明五色天。","山橫翠微外，室在綠潭邊。","緹幕灰初庪，焚林火欲然。","年光著草樹，春色換山泉。","伊水來何日，嵩巖去幾千。","山疑小天下，人是會神仙。","葉令乘鳧入，浮丘駕鶴旋。","麻姑幾年歲，三見海成田。"]', '["我皇盛文物，道化天地先。","鞭撻走神鬼，玉帛禮山川。","忽下袁州使，来游紫洞前。","青羊得处所，白鹤□时年。","虔懇飞龙記，昭彰化鸟篇。","□风半山水，□氣總云煙。","光抱昇中日，霞明五色天。","山橫翠微外，室在綠潭邊。","緹幕灰初庪，焚林火欲然。","年光著草樹，春色換山泉。","伊水来何日，嵩巖去幾千。","山疑小天下，人是會神仙。","葉令乘鳧入，浮丘駕鹤旋。","麻姑幾年歲，三见海成田。"]', '诗', 'shi', '', NULL, '早春陪敕使麻先生祭岳 馬令 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('523263a1-39fc-4d0e-a57f-a1cea1a64f5d', '奉和郎中題仙巖瀑布十四韻', '奉和郎中題仙巖瀑布十四韻', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["致閑在一郡，民安已三年。","每懷貞士心，孫許猶差肩。","採異百代後，得之古人前。","捫險路坱圠，臨深聞潺湲。","上有千歲樹，下飛百丈泉。","清谷長雷雨，丹青凝霜煙。","遙將大壑近，闇與方壺連。","白石顏色寒，老藤花葉鮮。","軒皇自茲去，喬木空依然。","碧山東極海，明月高昇天。","平野生竹柏，雖遠地不偏。","永願酬國恩，自將布金田。","穆穆早朝人，英英丹陛賢。","誰思滄洲意，方欲涉臣川。"]', '["致闲在一郡，民安已三年。","每懷貞士心，孫許猶差肩。","採異百代後，得之古人前。","捫險路坱圠，臨深闻潺湲。","上有千歲樹，下飞百丈泉。","清谷长雷雨，丹青凝霜煙。","遙將大壑近，闇與方壺連。","白石顏色寒，老藤花葉鲜。","軒皇自茲去，喬木空依然。","碧山东極海，明月高昇天。","平野生竹柏，雖远地不偏。","永願酬国恩，自將布金田。","穆穆早朝人，英英丹陛賢。","誰思滄洲意，方欲涉臣川。"]', '诗', 'shi', '', NULL, '奉和郎中題仙巖瀑布十四韻 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4a8b8bc-f766-4aa4-90ca-cc2c21188538', '過商山', '過商山', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["吟緣橫翠憶天台，嘯狖啼猨見盡猜。","四箇老人何處去，一聲仙鶴過溪來。","皇城宮闕迴頭盡，紫閣煙霞爲我開。","天際峰峰盡堪住，紅塵中去大悠哉。"]', '["吟緣橫翠憶天台，嘯狖啼猨见尽猜。","四箇老人何处去，一声仙鹤過溪来。","皇城宮闕迴头尽，紫閣煙霞爲我开。","天際峰峰尽堪住，紅塵中去大悠哉。"]', '诗', 'shi', '', NULL, '過商山 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b4ce6a3-84a2-4fbe-a30a-694ae0e47103', '過西塞山', '過西塞山', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["空江平野流，風島葦颼颼。","殘日銜西塞，孤帆向北洲。","邊鴻渡漢口，楚樹出吳頭。","終日高雲裏，身依片石休。"]', '["空江平野流，风島葦颼颼。","殘日銜西塞，孤帆向北洲。","邊鴻渡漢口，楚樹出吳头。","終日高云裏，身依片石休。"]', '诗', 'shi', '', NULL, '過西塞山 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78be039b-1960-406e-8f10-099c3d3f6ad7', '中秋月', '中秋月', '22d20dee-bba6-4790-9ea6-b9bad895e928', '唐', '["登樓仍喜此宵晴，圓魄纔觀思便清。","海面乍浮猶隱映，天心高挂最分明。","片雲想有神仙出，迴野應無鬼魅形。","曾向洞庭湖上看，君山半霧水初平。"]', '["登楼仍喜此宵晴，圓魄纔观思便清。","海面乍浮猶隐映，天心高挂最分明。","片云想有神仙出，迴野應無鬼魅形。","曾向洞庭湖上看，君山半霧水初平。"]', '诗', 'shi', '', NULL, '中秋月 可朋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d0e1883-2457-4cbf-b71c-99c08c23e09e', '僧院泉', '僧院泉', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["澄澈照人膽，深山只一般。","來難窮處所，心去助波瀾。","砌曲夜聲苦，窗虛客夢闌。","無心誰肯愛，時有老僧看。"]', '["澄澈照人膽，深山只一般。","来难窮处所，心去助波瀾。","砌曲夜声苦，窗虛客梦闌。","無心誰肯愛，时有老僧看。"]', '诗', 'shi', '', NULL, '僧院泉 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59685a89-eae4-4bcc-9309-49d356a21dc5', '題僧院泉', '題僧院泉', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["何處雲根新布得，歸仍半日在煙蘿。","莫輕竹引經窗小，須信更深入耳多。","繞砌雖然清自別，出門長恐濁相和。","從此無心戀滄海，滄海無風亦起波。"]', '["何处云根新布得，归仍半日在煙蘿。","莫轻竹引經窗小，須信更深入耳多。","繞砌雖然清自別，出门长恐濁相和。","從此無心戀滄海，滄海無风亦起波。"]', '诗', 'shi', '', NULL, '題僧院泉 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('788a0b97-77e2-4303-bc76-e110893b9385', '岳上作', '岳上作', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["始好步青苔，蟬聲且莫催。","辛勤來到此，容易便言迴。","遠水月未上，四方雲正開。","更堪逢道侶，特地話天台。"]', '["始好步青苔，蟬声且莫催。","辛勤来到此，容易便言迴。","远水月未上，四方云正开。","更堪逢道侶，特地話天台。"]', '诗', 'shi', '', NULL, '岳上作 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59655cc0-4c93-4f05-a410-5b7aa2df1750', '望西山', '望西山', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["積翠異諸嶽，令人看莫休。","有時經暮雨，獨得倚高樓。","雲外僧應老，林間水正秋。","到頭歸隱處，豈在問嵩丘。"]', '["積翠異諸嶽，令人看莫休。","有时經暮雨，独得倚高楼。","云外僧應老，林间水正秋。","到头归隐处，豈在问嵩丘。"]', '诗', 'shi', '', NULL, '望西山 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31908e17-25e9-4c46-ab2f-dd36b4560dfb', '題虎掊泉', '題虎掊泉', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["一自虎掊得，清聲四遠流。","眾人憐爾處，長夜洗心頭。","出谷花隨去，背巖猨下偷。","林邊落江徼，風起雨翛翛。"]', '["一自虎掊得，清声四远流。","眾人怜爾处，长夜洗心头。","出谷花隨去，背巖猨下偷。","林邊落江徼，风起雨翛翛。"]', '诗', 'shi', '', NULL, '題虎掊泉 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e63342e-15a0-4546-b783-41de2efa6b51', '松', '松', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["細韻颼颼入骨涼，影兼巢鶴過高牆。","盤根一種依平地，自是梧桐不久長。"]', '["細韻颼颼入骨涼，影兼巢鹤過高牆。","盤根一種依平地，自是梧桐不久长。"]', '诗', 'shi', '', NULL, '松 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9251c989-02ee-49b2-94f6-f6c8f67cac3a', '岳陽對柳', '岳陽对柳', '209c68f5-d257-47d0-991a-1611e7d255e2', '唐', '["誰此種秋色，令人看莫窮。","正垂雲夢雨，不奈洞庭風。","昔出長安道，獨遊隋苑東。","當時今日思，須信苦相同。"]', '["誰此種秋色，令人看莫窮。","正垂云梦雨，不奈洞庭风。","昔出长安道，独游隋苑东。","當时今日思，須信苦相同。"]', '诗', 'shi', '', NULL, '岳陽對柳 修睦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64f5f037-6dab-432b-8275-28d0907bfd8f', '歸山吟', '归山吟', '8c07c2ad-c545-4770-a1d5-5589dd8df8d2', '唐', '["聚如浮沫散如雲，聚不相將散不分。","入郭當時君是我，歸山今日我非君。"]', '["聚如浮沫散如云，聚不相將散不分。","入郭當时君是我，归山今日我非君。"]', '诗', 'shi', '', NULL, '歸山吟 清豁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0634a8c3-a658-40a2-b28a-89912d6e82d9', '遊倚帝山二首 一', '游倚帝山二首 一', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["山間非吾心，物表翼所託。","振衣超煩滓，策杖追岑壑。","絕地窮㟏岈，造天究磐礴。","邇臨煙霞積，逖睇宇宙廓。","俯驚白雲涌，仰駭飛泉落。","苔濃鮮翠屏，松古麗丹崿。","目冀覩喬羨，心希馭龍鶴。","乃知巢由情，豈伊猨鳥樂。"]', '["山间非吾心，物表翼所託。","振衣超煩滓，策杖追岑壑。","絕地窮㟏岈，造天究磐礴。","邇臨煙霞積，逖睇宇宙廓。","俯驚白云涌，仰駭飞泉落。","苔濃鲜翠屏，松古丽丹崿。","目冀覩喬羨，心希馭龙鹤。","乃知巢由情，豈伊猨鸟乐。"]', '诗', 'shi', '', NULL, '遊倚帝山二首 一 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a79ab3d-9245-492b-8052-4545254bbf1c', '遊倚帝山二首 二', '游倚帝山二首 二', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["茲山何獨秀，萬仞倚昊蒼。","晨躋煙霞趾，夕憩靈仙場。","俯觀海上月，坐弄浮雲翔。","松風振雅音，桂露含晴光。","不出六合外，超然萬累忘。","信彼古來士，巖棲道彌彰。"]', '["茲山何独秀，万仞倚昊蒼。","晨躋煙霞趾，夕憩靈仙場。","俯观海上月，坐弄浮云翔。","松风振雅音，桂露含晴光。","不出六合外，超然万累忘。","信彼古来士，巖棲道彌彰。"]', '诗', 'shi', '', NULL, '遊倚帝山二首 二 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7f6143b-0e49-45a5-ae3f-c7203cad3f68', '翰林院望終南山 一', '翰林院望終南山 一', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["竊慕隱淪道，所歡巖穴居。","誰言忝休命，遂入承明廬。","物情不可易，幽中未嘗攄。","幸見終南山，岧嶢凌太虛。"]', '["竊慕隐淪道，所歡巖穴居。","誰言忝休命，遂入承明廬。","物情不可易，幽中未嘗攄。","幸见終南山，岧嶢凌太虛。"]', '诗', 'shi', '', NULL, '翰林院望終南山 一 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b58e1fb5-2c93-41e0-b131-5158933e3b03', '翰林院望終南山 二', '翰林院望終南山 二', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["青靄長不滅，白雲閑卷舒。","悠然相探討，延望空躊躕。","迹繫心無極，神超興有餘。","何當解維縶，永託逍遙墟。"]', '["青靄长不滅，白云闲卷舒。","悠然相探討，延望空躊躕。","迹繫心無極，神超兴有餘。","何當解維縶，永託逍遙墟。"]', '诗', 'shi', '', NULL, '翰林院望終南山 二 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afe7cf90-1b3f-418b-a6ac-71c7bdefdcb3', '秋日彭蠡湖中觀廬山', '秋日彭蠡湖中观廬山', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["泛舟太湖上，迴瞰茲山隈。","萬頃滄波中，千峰鬱崔嵬。","涼煙發爐嶠，秋日明帝臺。","絕巔凌大漠，懸流瀉昭回。","穹崇石梁引，岈豁天門開。","飛鳥屢隱見，白雲時往來。","超然契清賞，目醉心悠哉。","董氏出六合，王君升九垓。","誰言曠遐祀，庶可相追陪。","從此永棲託，拂衣謝浮埃。"]', '["泛舟太湖上，迴瞰茲山隈。","万頃滄波中，千峰鬱崔嵬。","涼煙發爐嶠，秋日明帝台。","絕巔凌大漠，懸流瀉昭回。","穹崇石梁引，岈豁天门开。","飞鸟屢隐见，白云时往来。","超然契清賞，目醉心悠哉。","董氏出六合，王君升九垓。","誰言曠遐祀，庶可相追陪。","從此永棲託，拂衣謝浮埃。"]', '诗', 'shi', '', NULL, '秋日彭蠡湖中觀廬山 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f904d8e2-1cf4-4e4e-bbaa-1111e07063c2', '秋日望倚帝山', '秋日望倚帝山', '1b497221-2200-45ba-bde4-8d9e98ab6a52', '唐', '["楚服多奇山，靈表先倚帝。","孤秀白雲裏，青冥何崇麗。","秋天已晴朗，晚日更澄霽。","遠峰列在目，杳與神襟契。","倏忽遺世間，宛如再登詣。","伊予抱斯志，代處人煙閉。","何事牽俗網，悠然負芝桂。","朅來從隱淪，式保羨門計。"]', '["楚服多奇山，靈表先倚帝。","孤秀白云裏，青冥何崇丽。","秋天已晴朗，晚日更澄霽。","远峰列在目，杳與神襟契。","倏忽遺世间，宛如再登詣。","伊予抱斯志，代处人煙閉。","何事牽俗網，悠然負芝桂。","朅来從隐淪，式保羨门計。"]', '诗', 'shi', '', NULL, '秋日望倚帝山 吳筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6719377f-8be8-4c5e-b5f7-2bb9be74d1ba', '薔薇花', '薔薇花', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["翠融紅綻渾無力，斜倚欄干似詫人。","深處最宜香惹蝶，摘時兼恐焰燒春。","當空巧結玲瓏帳，著地能鋪錦繡裀。","最好凌晨和露看，碧紗窗外一枝新。"]', '["翠融紅綻渾無力，斜倚欄干似詫人。","深处最宜香惹蝶，摘时兼恐焰燒春。","當空巧結玲瓏帳，著地能鋪錦繡裀。","最好凌晨和露看，碧紗窗外一枝新。"]', '诗', 'shi', '', NULL, '薔薇花 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5cb1c78-9034-4076-85c4-529968ac34a5', '柳', '柳', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["最愛纖纖曲水濱，夕陽移影過青蘋。","東風又染一年綠，楚客更傷千里春。","低葉已藏依岸櫂，高枝應閉上樓人。","舞腰漸重煙光老，散作飛綿惹翠裀。"]', '["最愛纖纖曲水濱，夕陽移影過青蘋。","东风又染一年綠，楚客更傷千里春。","低葉已藏依岸櫂，高枝應閉上楼人。","舞腰漸重煙光老，散作飞綿惹翠裀。"]', '诗', 'shi', '', NULL, '柳 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df549d8e-42c9-480e-870e-e850117366e5', '好時光', '好时光', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["寶髻偏宜宮樣，蓮臉嫩，體紅香。","眉黛不須張敞畫，天教入鬢長。","莫倚傾國貌，嫁取箇，有情郎。","彼此當年少，莫負好時光。"]', '["寶髻偏宜宮樣，蓮臉嫩，體紅香。","眉黛不須張敞畫，天教入鬢长。","莫倚傾国貌，嫁取箇，有情郎。","彼此當年少，莫負好时光。"]', '诗', 'shi', '', NULL, '好時光 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83d3c6fd-88ac-4ca0-9562-d04667679278', '巫山一段雲 一', '巫山一段云 一', '35062aa9-2daf-40af-ac23-7dc63ea1a1ec', '唐', '["縹緲雲間質，盈盈波上身。","袖羅斜舉動埃塵，明豔不勝春。","翠鬢晚妝煙重，寂寂陽臺一夢。","冰眸蓮臉見長新，巫峽更何人。"]', '["縹緲云间質，盈盈波上身。","袖羅斜舉动埃塵，明豔不勝春。","翠鬢晚妝煙重，寂寂陽台一梦。","冰眸蓮臉见长新，巫峽更何人。"]', '诗', 'shi', '', NULL, '巫山一段雲 一 昭宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3532bea-0327-47f6-945c-87158ad3b99d', '巫山一段雲 二', '巫山一段云 二', '35062aa9-2daf-40af-ac23-7dc63ea1a1ec', '唐', '["蝶舞棃園雪，鶯啼柳帶煙。","小池殘日豔陽天，苧蘿山又山。","青鳥不來愁絕，忍看鴛鴦雙結。","春風一等少年心，閑情恨不禁。"]', '["蝶舞棃园雪，鶯啼柳带煙。","小池殘日豔陽天，苧蘿山又山。","青鸟不来愁絕，忍看鴛鴦雙結。","春风一等少年心，闲情恨不禁。"]', '诗', 'shi', '', NULL, '巫山一段雲 二 昭宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('130b361d-eb7c-4795-a133-182b70d16fe0', '菩薩蠻 一', '菩薩蠻 一', '35062aa9-2daf-40af-ac23-7dc63ea1a1ec', '唐', '["登樓遙望秦宮殿，茫茫只見雙飛燕。","渭水一條流，千山與萬丘。","遠煙籠碧樹，陌上行人去。","安得有英雄，迎歸大內中。"]', '["登楼遙望秦宮殿，茫茫只见雙飞燕。","渭水一條流，千山與万丘。","远煙籠碧樹，陌上行人去。","安得有英雄，迎归大內中。"]', '诗', 'shi', '', NULL, '菩薩蠻 一 昭宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbc32a17-7b68-4c01-babe-d1a794540564', '菩薩蠻 二', '菩薩蠻 二', '35062aa9-2daf-40af-ac23-7dc63ea1a1ec', '唐', '["飄飄且在三峰下，秋風往往堪霑灑。","腸斷憶仙宮，朦朧煙霧中。","思夢時時睡，不語長如醉。","早晚是歸期，蒼穹知不知。"]', '["飄飄且在三峰下，秋风往往堪霑灑。","腸斷憶仙宮，朦朧煙霧中。","思梦时时睡，不語长如醉。","早晚是归期，蒼穹知不知。"]', '诗', 'shi', '', NULL, '菩薩蠻 二 昭宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c9a932b-bd56-4e72-9ab0-fc8b319616a4', '一葉落', '一葉落', '668db888-fedb-4867-84eb-78f736a83169', '唐', '["一葉落，搴朱箔，此時景物正蕭索。","畫樓月影寒，西風吹羅幕。","吹羅幕，往事思量著。"]', '["一葉落，搴朱箔，此时景物正蕭索。","畫楼月影寒，西风吹羅幕。","吹羅幕，往事思量著。"]', '诗', 'shi', '', NULL, '一葉落 後唐莊宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ab387cd-6e1b-4cb9-aa88-5e0113b45a21', '如夢令', '如梦令', '668db888-fedb-4867-84eb-78f736a83169', '唐', '["曾宴桃源深洞，一曲清歌舞鳳。","長記別伊時，和淚出門相送。","如夢，如夢，殘月落花煙重。"]', '["曾宴桃源深洞，一曲清歌舞鳳。","长記別伊时，和泪出门相送。","如梦，如梦，殘月落花煙重。"]', '诗', 'shi', '', NULL, '如夢令 後唐莊宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f903077a-e55d-4f38-82b9-5ac800650a2e', '陽臺夢', '陽台梦', '668db888-fedb-4867-84eb-78f736a83169', '唐', '["薄羅衫子金泥縫，困纖腰怯銖衣重。","笑迎移步小蘭叢，嚲金翹玉鳳。","嬌多情脈脈，羞把同心撚弄。","楚天雲雨却相和，又入陽臺夢。"]', '["薄羅衫子金泥縫，困纖腰怯銖衣重。","笑迎移步小蘭叢，嚲金翹玉鳳。","嬌多情脈脈，羞把同心撚弄。","楚天云雨却相和，又入陽台梦。"]', '诗', 'shi', '', NULL, '陽臺夢 後唐莊宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0c41411-2fdb-49c1-97ce-1f7e298fb6b6', '歌頭', '歌头', '668db888-fedb-4867-84eb-78f736a83169', '唐', '["賞芳春，暖風飄箔。","鶯啼綠樹，輕煙籠晚閣。","杏桃紅，開繁萼。","靈和殿，禁柳千行斜，金絲絡。","夏雲多，奇峰如削，紈扇動微涼，輕綃薄。","梅雨霽，火雲爍。","臨水檻，永日逃繁暑，泛觥酌。","露華濃，冷高梧。","彫萬葉，一霎晚風。","蟬聲新雨歇，惜惜此光陰，如流水，東籬菊殘時，歎蕭索。","繁陰積，歲時暮。","景難留，不覺朱顏失却。","好容光，且且須呼賓友。","西園長宵，讌雲謠。","歌皓齒，且行樂。"]', '["賞芳春，暖风飄箔。","鶯啼綠樹，轻煙籠晚閣。","杏桃紅，开繁萼。","靈和殿，禁柳千行斜，金絲絡。","夏云多，奇峰如削，紈扇动微涼，轻綃薄。","梅雨霽，火云爍。","臨水檻，永日逃繁暑，泛觥酌。","露华濃，冷高梧。","彫万葉，一霎晚风。","蟬声新雨歇，惜惜此光陰，如流水，东籬菊殘时，歎蕭索。","繁陰積，歲时暮。","景难留，不覺朱顏失却。","好容光，且且須呼賓友。","西园长宵，讌云謠。","歌皓齒，且行乐。"]', '诗', 'shi', '', NULL, '歌頭 後唐莊宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15ec3147-5815-4d39-8b56-5de943732033', '浣溪沙', '浣溪沙', '242ed9dd-d79c-4f20-89c7-ad428383b935', '唐', '["風壓輕雲貼水飛，乍晴池館燕爭泥，沈郎多病不勝衣。","沙上未聞鴻雁信，竹間時聽鷓鴣啼，此情惟有落花知。"]', '["风壓轻云貼水飞，乍晴池館燕爭泥，沈郎多病不勝衣。","沙上未闻鴻雁信，竹间时听鷓鴣啼，此情惟有落花知。"]', '诗', 'shi', '', NULL, '浣溪沙 南唐嗣主李璟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85ae4de5-86e8-4289-b094-a54a38026f38', '攤破浣溪沙 一', '攤破浣溪沙 一', '242ed9dd-d79c-4f20-89c7-ad428383b935', '唐', '["菡萏香銷翠葉殘，西風愁起綠波間。","還與韶光共顦顇，不堪看。","細雨夢回雞塞遠，小樓吹徹玉笙寒。","多少淚珠何限恨，倚闌干。"]', '["菡萏香銷翠葉殘，西风愁起綠波间。","還與韶光共顦顇，不堪看。","細雨梦回雞塞远，小楼吹徹玉笙寒。","多少泪珠何限恨，倚闌干。"]', '诗', 'shi', '', NULL, '攤破浣溪沙 一 南唐嗣主李璟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0df0cf6-8562-4040-9bcb-b4b98de81d78', '攤破浣溪沙 二', '攤破浣溪沙 二', '242ed9dd-d79c-4f20-89c7-ad428383b935', '唐', '["手卷真珠上玉鉤，依前春恨鎖重樓。","風裏落花誰是主，思悠悠。","青鳥不傳雲外信，丁香空結雨中愁。","回首淥波三峽暮，接天流。"]', '["手卷真珠上玉鉤，依前春恨鎖重楼。","风裏落花誰是主，思悠悠。","青鸟不傳云外信，丁香空結雨中愁。","回首淥波三峽暮，接天流。"]', '诗', 'shi', '', NULL, '攤破浣溪沙 二 南唐嗣主李璟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b2dbf7b-accc-43ff-9417-01b63042eefd', '漁父 一', '漁父 一', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["浪花有意千里雪，桃花無言一隊春。","一壺酒，一竿身，快活如儂有幾人。"]', '["浪花有意千里雪，桃花無言一隊春。","一壺酒，一竿身，快活如儂有幾人。"]', '诗', 'shi', '', NULL, '漁父 一 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b181549-9b0b-4b8a-acbd-850117557c39', '漁父 二', '漁父 二', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["一櫂春風一葉舟，一綸繭縷一輕鉤。","花滿渚，酒滿甌，萬頃波中得自由。"]', '["一櫂春风一葉舟，一綸繭縷一轻鉤。","花满渚，酒满甌，万頃波中得自由。"]', '诗', 'shi', '', NULL, '漁父 二 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6436c19b-b93a-41f9-96ba-8f6cc02e9012', '憶江南 一', '憶江南 一', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["多少恨，昨夜夢魂中。","還似舊時遊上苑，車如流水馬如龍，花月正春風。"]', '["多少恨，昨夜梦魂中。","還似旧时游上苑，车如流水马如龙，花月正春风。"]', '诗', 'shi', '', NULL, '憶江南 一 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc5d6d53-e6aa-4e1a-8ce5-98069da65a40', '憶江南 二', '憶江南 二', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["多少淚，霑袖復橫頤。","心事莫將和淚滴，鳳笙休向月明吹，腸斷更無疑。"]', '["多少泪，霑袖复橫頤。","心事莫將和泪滴，鳳笙休向月明吹，腸斷更無疑。"]', '诗', 'shi', '', NULL, '憶江南 二 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ebe04ef-6213-4f12-b696-958a955c088e', '憶江南 三', '憶江南 三', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["閑夢遠，南國正芳春。","船上管弦江面綠，滿城飛絮混輕塵，愁殺看花人。"]', '["闲梦远，南国正芳春。","船上管弦江面綠，满城飞絮混轻塵，愁殺看花人。"]', '诗', 'shi', '', NULL, '憶江南 三 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d887dc7a-137b-4b39-9943-a012cb397f56', '憶江南 四', '憶江南 四', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["閑夢遠，南國正清秋。","千里江山寒色暮，蘆花深處泊孤舟，笛在月明樓。"]', '["闲梦远，南国正清秋。","千里江山寒色暮，蘆花深处泊孤舟，笛在月明楼。"]', '诗', 'shi', '', NULL, '憶江南 四 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('087babd8-0706-4fa7-a114-1b60a189d1de', '擣練子 一', '擣練子 一', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["深院靜，小庭空，斷續寒砧斷續風。","無奈夜長人不寐，數聲和月到簾櫳。"]', '["深院静，小庭空，斷續寒砧斷續风。","無奈夜长人不寐，數声和月到簾櫳。"]', '诗', 'shi', '', NULL, '擣練子 一 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('324936b5-b8c7-4445-aec2-0ced76d124fe', '擣練子 二', '擣練子 二', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["雲鬟亂，晚妝殘，帶恨眉兒遠岫攢。","斜托香顋春筍嬾，爲誰和淚倚闌干。"]', '["云鬟亂，晚妝殘，带恨眉兒远岫攢。","斜托香顋春筍嬾，爲誰和泪倚闌干。"]', '诗', 'shi', '', NULL, '擣練子 二 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cf494bc-da88-441b-8190-f51a1cd33239', '相見歡 一', '相见歡 一', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["林花謝了春紅，太悤悤。","無奈朝來寒雨，晚來風。","胭脂淚，相留醉，幾時重。","自是人生長恨，水長東。"]', '["林花謝了春紅，太悤悤。","無奈朝来寒雨，晚来风。","胭脂泪，相留醉，幾时重。","自是人生长恨，水长东。"]', '诗', 'shi', '', NULL, '相見歡 一 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fed4281e-1e15-41dd-a156-b4d97553b5be', '相見歡 二', '相见歡 二', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["無言獨上西樓，月如鉤。","寂寞梧桐深院，鎖清秋。","翦不斷，理還亂，是離愁。","別是一般滋味，在心頭。"]', '["無言独上西楼，月如鉤。","寂寞梧桐深院，鎖清秋。","翦不斷，理還亂，是離愁。","別是一般滋味，在心头。"]', '诗', 'shi', '', NULL, '相見歡 二 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25bc24c7-fde4-4be6-8d0e-a16b1525ea4e', '長相思 一', '长相思 一', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["一重山，兩重山。","山遠天高煙水寒，相思楓葉丹。","菊花開，菊花殘。","塞雁高飛人未還，一簾風月閑。"]', '["一重山，兩重山。","山远天高煙水寒，相思楓葉丹。","菊花开，菊花殘。","塞雁高飞人未還，一簾风月闲。"]', '诗', 'shi', '', NULL, '長相思 一 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('191e4990-2397-4208-b5e8-39813345f6af', '長相思 二', '长相思 二', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["雲一緺，玉一梭。","澹澹衫兒薄薄羅，輕顰雙黛螺。","秋風多，雨如和。","簾外芭蕉三兩窠，夜長人奈何。"]', '["云一緺，玉一梭。","澹澹衫兒薄薄羅，轻顰雙黛螺。","秋风多，雨如和。","簾外芭蕉三兩窠，夜长人奈何。"]', '诗', 'shi', '', NULL, '長相思 二 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d9fc470-fa99-4139-8b5a-321d331c01f3', '浣溪沙 一', '浣溪沙 一', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["紅日已高三丈透，金鑪次第添香獸，紅錦地衣隨步皺。","佳人舞點金釵溜，酒惡時拈花蘂齅，別殿遙聞簫鼓奏。"]', '["紅日已高三丈透，金鑪次第添香獸，紅錦地衣隨步皺。","佳人舞点金釵溜，酒惡时拈花蘂齅，別殿遙闻簫鼓奏。"]', '诗', 'shi', '', NULL, '浣溪沙 一 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11d72852-47c9-4659-971a-9b8b95277122', '浣溪沙 二', '浣溪沙 二', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["轉燭飄蓬一夢歸，欲尋陳迹悵人非，天教心願與身違。","待月池臺空逝水，蔭花樓閣漫斜暉，登臨不惜更霑衣。"]', '["轉燭飄蓬一梦归，欲尋陳迹悵人非，天教心願與身違。","待月池台空逝水，蔭花楼閣漫斜暉，登臨不惜更霑衣。"]', '诗', 'shi', '', NULL, '浣溪沙 二 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d5f5235-966d-42c1-9d59-68d280a7386d', '采桑子 一', '采桑子 一', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["轆轤金井梧桐晚，幾樹驚秋，晝雨如愁，百尺蝦鬚上玉鉤。","瓊窗春斷雙蛾皺，回首邊頭，欲寄鱗游，九曲寒波不泝流。"]', '["轆轤金井梧桐晚，幾樹驚秋，晝雨如愁，百尺蝦鬚上玉鉤。","瓊窗春斷雙蛾皺，回首邊头，欲寄鱗游，九曲寒波不泝流。"]', '诗', 'shi', '', NULL, '采桑子 一 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c893ac3e-c25e-49e9-afd0-a8bcc3d34f73', '采桑子 二', '采桑子 二', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["亭前春逐紅英盡，舞態徘徊，細雨霏微，不放雙眉時暫開。","綠窗冷靜芳音斷，香印成灰，可奈情懷，欲睡朦朧入夢來。"]', '["亭前春逐紅英尽，舞態徘徊，細雨霏微，不放雙眉时暫开。","綠窗冷静芳音斷，香印成灰，可奈情懷，欲睡朦朧入梦来。"]', '诗', 'shi', '', NULL, '采桑子 二 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eabb0b49-b82e-4047-a130-fa5b687f4948', '菩薩蠻 一', '菩薩蠻 一', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["花明月暗籠輕霧，今宵好向郎邊去。","剗韤步香階，手提金縷鞋。","畫堂南畔見，一晌偎人顫。","好爲出來難，教君恣意憐。"]', '["花明月暗籠轻霧，今宵好向郎邊去。","剗韤步香階，手提金縷鞋。","畫堂南畔见，一晌偎人顫。","好爲出来难，教君恣意怜。"]', '诗', 'shi', '', NULL, '菩薩蠻 一 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a6be65e-27bf-4728-b8a7-95197ab48d07', '菩薩蠻 二', '菩薩蠻 二', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["蓬萊院閉天台女，畫堂晝寢無人語。","拋枕翠雲光，繡衣聞異香。","潛來珠鎖動，驚覺鴛鴦夢。","慢臉笑盈盈，相看無限情。"]', '["蓬萊院閉天台女，畫堂晝寢無人語。","拋枕翠云光，繡衣闻異香。","潛来珠鎖动，驚覺鴛鴦梦。","慢臉笑盈盈，相看無限情。"]', '诗', 'shi', '', NULL, '菩薩蠻 二 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2f641d9-18c6-4a1c-89d0-5ddf84704730', '菩薩蠻 三', '菩薩蠻 三', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["銅簧韻脆鏘寒竹，新聲慢奏移纖玉。","眼色暗相鉤，秋波橫欲流。","雨雲深繡戶，來便諧衷素。","宴罷又成空，夢迷春睡中。"]', '["銅簧韻脆鏘寒竹，新声慢奏移纖玉。","眼色暗相鉤，秋波橫欲流。","雨云深繡戶，来便諧衷素。","宴罷又成空，梦迷春睡中。"]', '诗', 'shi', '', NULL, '菩薩蠻 三 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72ffbb94-d801-4c39-bf26-75150f2ce7a0', '菩薩蠻 四', '菩薩蠻 四', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["人生愁恨何能免，消魂獨我情何限。","故國夢重歸，覺來雙淚垂。","高樓誰與上，長記秋晴望。","往事已成空，還如一夢中。"]', '["人生愁恨何能免，消魂独我情何限。","故国梦重归，覺来雙泪垂。","高楼誰與上，长記秋晴望。","往事已成空，還如一梦中。"]', '诗', 'shi', '', NULL, '菩薩蠻 四 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e79bf420-dc28-48da-97f9-d3e07b3cb5f6', '清平樂', '清平乐', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["別來春半，觸目愁腸斷。","砌下落梅如雪亂，拂了一身還滿。","雁來音信無憑，路遙歸夢難成。","離恨却如春草，更行更遠還生。"]', '["別来春半，觸目愁腸斷。","砌下落梅如雪亂，拂了一身還满。","雁来音信無憑，路遙归梦难成。","離恨却如春草，更行更远還生。"]', '诗', 'shi', '', NULL, '清平樂 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cf30f0e-9821-4fe2-b899-bc2703f5159d', '喜遷鶯', '喜遷鶯', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["曉月墜，宿雲微，無語枕頻欹。","夢回芳草思依依，天遠雁聲稀。","啼鶯散，餘花亂，寂寞畫堂深院。","片紅休埽儘從伊，留待舞人歸。"]', '["晓月墜，宿云微，無語枕頻欹。","梦回芳草思依依，天远雁声稀。","啼鶯散，餘花亂，寂寞畫堂深院。","片紅休埽儘從伊，留待舞人归。"]', '诗', 'shi', '', NULL, '喜遷鶯 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c02731a-b355-4a8d-bbb6-1acb8284bf67', '阮郎歸', '阮郎归', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["東風吹水日銜山，春來長是閑。","落花狼藉酒闌珊，笙歌醉夢間。","春睡覺，晚妝殘，無人整翠鬟。","留連光景惜朱顏，黃昏獨倚闌。"]', '["东风吹水日銜山，春来长是闲。","落花狼藉酒闌珊，笙歌醉梦间。","春睡覺，晚妝殘，無人整翠鬟。","留連光景惜朱顏，黄昏独倚闌。"]', '诗', 'shi', '', NULL, '阮郎歸 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('692040b8-0c49-4532-b34c-0046af74232a', '錦堂春', '錦堂春', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["昨夜風兼雨，簾幃颯颯秋聲。","燭殘漏滴頻欹枕，起坐不能平。","世事漫隨流水，算來一夢浮生。","醉鄉路穩宜頻到，此外不堪行。"]', '["昨夜风兼雨，簾幃颯颯秋声。","燭殘漏滴頻欹枕，起坐不能平。","世事漫隨流水，算来一梦浮生。","醉乡路穩宜頻到，此外不堪行。"]', '诗', 'shi', '', NULL, '錦堂春 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70c60aed-dd54-448a-a2da-207469cf71e5', '應天長', '應天长', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["一鉤初月臨妝鏡，蟬鬢鳳釵慵不整。","重簾靜，層樓迥，惆悵落花風不定。","柳堤芳草徑，夢斷轆轤金井。","昨夜更闌酒醒，春愁過却病。"]', '["一鉤初月臨妝镜，蟬鬢鳳釵慵不整。","重簾静，層楼迥，惆悵落花风不定。","柳堤芳草徑，梦斷轆轤金井。","昨夜更闌酒醒，春愁過却病。"]', '诗', 'shi', '', NULL, '應天長 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('079eab76-b38a-4a82-8a13-ac00e92b67c0', '望遠行', '望远行', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["碧砌花光照眼明，朱扉長日鎮長扃。","餘寒欲去夢難成，爐香煙冷自亭亭。","遼陽月，秣陵砧，不傳消息但傳情。","黃金臺下忽然驚，征人歸日二毛生。"]', '["碧砌花光照眼明，朱扉长日鎮长扃。","餘寒欲去梦难成，爐香煙冷自亭亭。","遼陽月，秣陵砧，不傳消息但傳情。","黄金台下忽然驚，征人归日二毛生。"]', '诗', 'shi', '', NULL, '望遠行 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('377b9884-059e-4076-8104-25857ae7d84e', '浪淘沙 一', '浪淘沙 一', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["簾外雨潺潺，春意闌珊。","羅衾不耐五更寒，夢裏不知身是客，一晌貪歡。","獨自暮凭闌，無限江山。","別時容易見時難，流水落花春去也，天上人間。"]', '["簾外雨潺潺，春意闌珊。","羅衾不耐五更寒，梦裏不知身是客，一晌貪歡。","独自暮凭闌，無限江山。","別时容易见时难，流水落花春去也，天上人间。"]', '诗', 'shi', '', NULL, '浪淘沙 一 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9317285-0e91-4c01-8202-d97b2cd5abf4', '浪淘沙 二', '浪淘沙 二', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["往事只堪哀，對景難排。","秋風庭院蘚侵階，一桁珠簾閑不卷，終日誰來。","金劒已沈埋，壯氣蒿萊。","晚涼天淨月華開，想得玉樓瑤殿影，空照秦淮。"]', '["往事只堪哀，对景难排。","秋风庭院蘚侵階，一桁珠簾闲不卷，終日誰来。","金劒已沈埋，壯氣蒿萊。","晚涼天淨月华开，想得玉楼瑤殿影，空照秦淮。"]', '诗', 'shi', '', NULL, '浪淘沙 二 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f32e4bf5-94ee-476e-871f-c547e24d1fc1', '木蘭花', '木蘭花', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["曉妝初了明肌雪，春殿嬪娥魚貫列。","鳳簫聲斷水雲閑，重按霓裳歌徧徹。","臨風誰更飄香屑，醉拍闌干情未切。","歸時休放燭花紅，待蹋馬蹄清夜月。"]', '["晓妝初了明肌雪，春殿嬪娥鱼貫列。","鳳簫声斷水云闲，重按霓裳歌徧徹。","臨风誰更飄香屑，醉拍闌干情未切。","归时休放燭花紅，待蹋马蹄清夜月。"]', '诗', 'shi', '', NULL, '木蘭花 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b30f0ee-7708-4caa-b878-17b2fa3dbf65', '虞美人 一', '虞美人 一', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["風回小院庭蕪綠，柳眼春相續。","凭闌半日獨無言，依舊竹聲新月，似當年。","笙歌未散尊罍在，池面冰初解。","燭明香暗畫樓深，滿鬢清霜殘雪，思難禁。"]', '["风回小院庭蕪綠，柳眼春相續。","凭闌半日独無言，依旧竹声新月，似當年。","笙歌未散尊罍在，池面冰初解。","燭明香暗畫楼深，满鬢清霜殘雪，思难禁。"]', '诗', 'shi', '', NULL, '虞美人 一 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b769cd89-478e-40af-9cdc-80cdc7423473', '虞美人 二', '虞美人 二', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["春花秋月何時了，往事知多少。","小樓昨夜又東風，故國不堪回首，月明中。","雕闌玉砌應猶在，只是朱顏改。","問君能有幾多愁，恰似一江春水，向東流。"]', '["春花秋月何时了，往事知多少。","小楼昨夜又东风，故国不堪回首，月明中。","雕闌玉砌應猶在，只是朱顏改。","问君能有幾多愁，恰似一江春水，向东流。"]', '诗', 'shi', '', NULL, '虞美人 二 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcd2fbf3-006b-455f-b1c3-e35c2270331a', '一斛珠', '一斛珠', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["晚妝初過，沈檀輕注些兒箇，向人微露丁香顆。","一曲清歌，暫引櫻桃破。","羅袖裛殘殷色可，杯深旋被香醪涴，繡牀斜凭嬌無那。","爛嚼紅茸，笑向檀郎唾。"]', '["晚妝初過，沈檀轻注些兒箇，向人微露丁香顆。","一曲清歌，暫引櫻桃破。","羅袖裛殘殷色可，杯深旋被香醪涴，繡牀斜凭嬌無那。","爛嚼紅茸，笑向檀郎唾。"]', '诗', 'shi', '', NULL, '一斛珠 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('572f4c5e-0cb4-4643-98f9-cfbed581b50e', '臨江仙', '臨江仙', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["櫻桃落盡春歸去，蝶飜輕粉雙飛。","子規啼月小樓西，玉鉤羅幕，惆悵暮煙垂。","別巷寂寥人散後，望殘煙草低迷。","爐香閑嫋鳳皇兒，空持羅帶，回首恨依依。"]', '["櫻桃落尽春归去，蝶飜轻粉雙飞。","子規啼月小楼西，玉鉤羅幕，惆悵暮煙垂。","別巷寂寥人散後，望殘煙草低迷。","爐香闲嫋鳳皇兒，空持羅带，回首恨依依。"]', '诗', 'shi', '', NULL, '臨江仙 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cee2c436-21bb-419b-a1c5-dedfa2b9df6b', '蝶戀花', '蝶戀花', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["遙夜亭臯閑信步，纔過清明，漸覺傷春暮。","數點雨聲風約住，朦朧澹月雲來去。","桃李依依香暗度，誰在鞦韆，笑裏輕輕語。","一片芳心千萬緒，人間沒箇安排處。"]', '["遙夜亭臯闲信步，纔過清明，漸覺傷春暮。","數点雨声风約住，朦朧澹月云来去。","桃李依依香暗度，誰在鞦韆，笑裏轻轻語。","一片芳心千万緒，人间沒箇安排处。"]', '诗', 'shi', '', NULL, '蝶戀花 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efee393d-cdbb-4780-8220-d4c29d69b15e', '破陳子', '破陳子', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["四十年來家國，三千里地山河。","鳳闕龍樓連霄漢，玉樹瓊枝作煙蘿，幾曾識干戈？","一旦歸爲臣虜，沈腰潘鬢銷磨。","最是蒼黃辭廟日，教坊獨奏別離歌，垂淚對宮娥。"]', '["四十年来家国，三千里地山河。","鳳闕龙楼連霄漢，玉樹瓊枝作煙蘿，幾曾識干戈？","一旦归爲臣虜，沈腰潘鬢銷磨。","最是蒼黄辞廟日，教坊独奏別離歌，垂泪对宮娥。"]', '诗', 'shi', '', NULL, '破陳子 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf6d988a-d303-448b-a273-3b5c931a8fea', '醉妝詞', '醉妝词', 'ad3e8f06-e273-40bc-800a-330c45b8ed8f', '唐', '["者邊走，那邊走，只是尋花柳。","那邊走，者邊走，莫厭金杯酒。"]', '["者邊走，那邊走，只是尋花柳。","那邊走，者邊走，莫厭金杯酒。"]', '诗', 'shi', '', NULL, '醉妝詞 蜀主王衍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b53c33bc-5951-4623-b974-7da3cea14c00', '甘州曲', '甘州曲', 'ad3e8f06-e273-40bc-800a-330c45b8ed8f', '唐', '["畫羅裙，能解束。","稱腰身，柳眉桃臉不勝春。","薄媚足精神，可惜淪落在風塵。"]', '["畫羅裙，能解束。","稱腰身，柳眉桃臉不勝春。","薄媚足精神，可惜淪落在风塵。"]', '诗', 'shi', '', NULL, '甘州曲 蜀主王衍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94abda6b-1345-4fe2-9817-85ca2796bc39', '木蘭花', '木蘭花', '2fdbb185-b76f-48c3-ae32-3af7f7729c81', '唐', '["冰肌玉骨清無汗，水殿風來暗香滿。","繡簾一點月窺人，欹枕釵橫雲鬢亂。","起來瓊戶啓無聲，時見疎星渡河漢。","屈指西風幾時來，只恐流年暗中換。"]', '["冰肌玉骨清無汗，水殿风来暗香满。","繡簾一点月窺人，欹枕釵橫云鬢亂。","起来瓊戶啓無声，时见疎星渡河漢。","屈指西风幾时来，只恐流年暗中換。"]', '诗', 'shi', '', NULL, '木蘭花 後蜀主孟昶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7980a53-95de-40a8-9a87-95dd9c93208d', '回波樂', '回波乐', '11b77852-49dc-4a2b-9c82-39cc01c2b85b', '唐', '["回波爾時酒巵，微臣職在箴規。","侍宴既過三爵，諠譁竊恐非儀。"]', '["回波爾时酒巵，微臣職在箴規。","侍宴既過三爵，諠譁竊恐非儀。"]', '诗', 'shi', '', NULL, '回波樂 李景伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3c17135-5240-4731-b63e-f2b8f38a4174', '回波樂', '回波乐', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["回波爾時佺期，流向嶺外生歸。","身名已蒙齒錄，袍笏未復牙緋。"]', '["回波爾时佺期，流向嶺外生归。","身名已蒙齒錄，袍笏未复牙緋。"]', '诗', 'shi', '', NULL, '回波樂 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3a3e537-35fb-4b2c-946c-b534996f5027', '回波樂', '回波乐', '17a75cd5-c9fe-46e7-8fdb-a8c352e9e969', '唐', '["回波爾時栲栳，怕婦也是大好。","外邊祗有裴談，內裏無過李老。"]', '["回波爾时栲栳，怕婦也是大好。","外邊祗有裴談，內裏無過李老。"]', '诗', 'shi', '', NULL, '回波樂 裴談 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('411f845b-3a45-4c82-b91a-363d77f4c36f', '舞馬詞 一', '舞马词 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["萬玉朝宗鳳扆，千金率領龍媒。","眄鼓凝驕蹀躞，聽歌弄影徘徊。"]', '["万玉朝宗鳳扆，千金率領龙媒。","眄鼓凝驕蹀躞，听歌弄影徘徊。"]', '诗', 'shi', '', NULL, '舞馬詞 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4e4c3a0-ad43-4032-9399-9269529d1445', '舞馬詞 二', '舞马词 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["天鹿遙徵衛叔，日龍上借羲和。","將共兩驂爭舞，來隨八駿齊歌。"]', '["天鹿遙徵衛叔，日龙上借羲和。","將共兩驂爭舞，来隨八駿齊歌。"]', '诗', 'shi', '', NULL, '舞馬詞 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c4d085a-6d18-4a8e-b8a3-9bd113b64202', '舞馬詞 三', '舞马词 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["綵旄八佾成行，時龍五色因方。","屈膝銜杯赴節，傾心獻壽無疆。"]', '["綵旄八佾成行，时龙五色因方。","屈膝銜杯赴節，傾心獻壽無疆。"]', '诗', 'shi', '', NULL, '舞馬詞 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da38e39b-fa6d-47f0-a4a6-66254560c765', '舞馬詞 四', '舞马词 四', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["帝皁龍駒沛艾，星闌驥子權奇。","騰倚驤洋應節，繁驕接迹不移。"]', '["帝皁龙駒沛艾，星闌驥子權奇。","腾倚驤洋應節，繁驕接迹不移。"]', '诗', 'shi', '', NULL, '舞馬詞 四 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ec43f54-be64-4219-8f1a-b0234cc347b3', '舞馬詞 五', '舞马词 五', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["二聖先天合德，羣靈率土可封。","擊石驂驔紫燕，摐金顧步蒼龍。"]', '["二聖先天合德，羣靈率土可封。","擊石驂驔紫燕，摐金顧步蒼龙。"]', '诗', 'shi', '', NULL, '舞馬詞 五 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cd4c930-9c6e-48d1-9e99-a11829d26134', '舞馬詞 六', '舞马词 六', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["聖君出震應籙，神馬浮河獻圖。","足蹋天庭鼓舞，心將帝樂踟躕。"]', '["聖君出震應籙，神马浮河獻圖。","足蹋天庭鼓舞，心將帝乐踟躕。"]', '诗', 'shi', '', NULL, '舞馬詞 六 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0927bec-fc6f-4c90-a66c-5c770dd47b1d', '蹋歌詞 一', '蹋歌词 一', '1d8e074f-60a4-43b8-9b9b-63b47e35082b', '唐', '["綵女迎金屋，仙姬出畫堂。","鴛鴦裁錦袖，翡翠貼花黃。","歌響舞分行，豔色動流光。"]', '["綵女迎金屋，仙姬出畫堂。","鴛鴦裁錦袖，翡翠貼花黄。","歌响舞分行，豔色动流光。"]', '诗', 'shi', '', NULL, '蹋歌詞 一 崔液 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a41345e0-994a-4afc-af0d-f64fab5f8950', '蹋歌詞 二', '蹋歌词 二', '1d8e074f-60a4-43b8-9b9b-63b47e35082b', '唐', '["庭際花微落，樓前漢已橫。","金壺催夜盡，羅袖舞寒輕。","樂笑暢歡情，未半著天明。"]', '["庭際花微落，楼前漢已橫。","金壺催夜尽，羅袖舞寒轻。","乐笑暢歡情，未半著天明。"]', '诗', 'shi', '', NULL, '蹋歌詞 二 崔液 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a305428-c083-4b95-acb1-855ebcd09873', '桂殿秋 一', '桂殿秋 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["仙女下，董雙成，漢殿夜涼吹玉笙。","曲終却從仙官去，萬戶千門惟月明。"]', '["仙女下，董雙成，漢殿夜涼吹玉笙。","曲終却從仙官去，万戶千门惟月明。"]', '诗', 'shi', '', NULL, '桂殿秋 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('861a8e22-08c6-4c52-a1f0-bf481d0ccbe7', '桂殿秋 二', '桂殿秋 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["河漢女，玉鍊顏，雲軿往往在人間。","九霄有路去無跡，嫋嫋香風生佩環。"]', '["河漢女，玉鍊顏，云軿往往在人间。","九霄有路去無跡，嫋嫋香风生佩环。"]', '诗', 'shi', '', NULL, '桂殿秋 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5da9d7d-1e52-4992-8be5-73e556b07e0b', '清平調 一', '清平調 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雲想衣裳花想容，春風拂檻露華濃。","若非羣玉山頭見，會向瑤臺月下逢。"]', '["云想衣裳花想容，春风拂檻露华濃。","若非羣玉山头见，會向瑤台月下逢。"]', '诗', 'shi', '', NULL, '清平調 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59063901-7dbc-4f22-974f-ddccab675cbc', '清平調 二', '清平調 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["一枝紅豔露凝香，雲雨巫山枉斷腸。","借問漢宮誰得似，可憐飛燕倚新妝。"]', '["一枝紅豔露凝香，云雨巫山枉斷腸。","借问漢宮誰得似，可怜飞燕倚新妝。"]', '诗', 'shi', '', NULL, '清平調 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f91f3117-2bf2-4d12-999a-aca174124715', '清平調 三', '清平調 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["名花傾國兩相歡，常得君王帶笑看。","解得春風無限恨，沈香亭北倚闌干。"]', '["名花傾国兩相歡，常得君王带笑看。","解得春风無限恨，沈香亭北倚闌干。"]', '诗', 'shi', '', NULL, '清平調 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64d66549-1b3e-4a28-84be-590777c9b5b5', '連理枝 一', '連理枝 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雪蓋宮樓閉，羅幕昏金翠。","鬬壓闌干，香心澹薄，梅梢輕倚。","噴寶猊香燼麝煙濃，馥紅綃翠被。"]', '["雪蓋宮楼閉，羅幕昏金翠。","鬬壓闌干，香心澹薄，梅梢轻倚。","噴寶猊香燼麝煙濃，馥紅綃翠被。"]', '诗', 'shi', '', NULL, '連理枝 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5e39c65-60fd-49d1-ba82-3f46a6be880d', '連理枝 二', '連理枝 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["淺畫雲垂帔，點滴昭陽淚。","咫尺宸居，君恩斷絕，似遙千里。","望水晶簾外竹枝寒，守羊車未至。"]', '["淺畫云垂帔，点滴昭陽泪。","咫尺宸居，君恩斷絕，似遙千里。","望水晶簾外竹枝寒，守羊车未至。"]', '诗', 'shi', '', NULL, '連理枝 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f98b9110-23de-481c-bd87-bcdf2c14d05c', '菩薩蠻', '菩薩蠻', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["平林漠漠煙如織，寒山一帶傷心碧。","暝色入高樓，有人樓上愁。","玉階空佇立，宿鳥歸飛急。","何處是歸程，長亭更短亭。"]', '["平林漠漠煙如织，寒山一带傷心碧。","暝色入高楼，有人楼上愁。","玉階空佇立，宿鸟归飞急。","何处是归程，长亭更短亭。"]', '诗', 'shi', '', NULL, '菩薩蠻 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35f9a3a0-9e54-4450-930d-f6bdc051ba1f', '憶秦娥', '憶秦娥', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["簫聲咽，秦娥夢斷秦樓月。","秦樓月，年年柳色，灞陵傷別。","樂遊原上清秋節，咸陽古道音塵絕。","音塵絕，西風殘照，漢家陵闕。"]', '["簫声咽，秦娥梦斷秦楼月。","秦楼月，年年柳色，灞陵傷別。","乐游原上清秋節，咸陽古道音塵絕。","音塵絕，西风殘照，漢家陵闕。"]', '诗', 'shi', '', NULL, '憶秦娥 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eae8a09d-b5b5-42bc-b196-2853ba90fc32', '清平樂 一', '清平乐 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["禁庭春晝，鶯羽披新繡。","百草巧求花下鬬，祗賭珠璣滿斗。","日晚却理殘妝，御前閑舞霓裳。","誰道腰肢窈窕，折旋笑得君王。"]', '["禁庭春晝，鶯羽披新繡。","百草巧求花下鬬，祗賭珠璣满斗。","日晚却理殘妝，御前闲舞霓裳。","誰道腰肢窈窕，折旋笑得君王。"]', '诗', 'shi', '', NULL, '清平樂 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12a47c99-b1dd-47cf-8a1a-d0aed438ee47', '清平樂 二', '清平乐 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["禁闈秋夜，月探金窗罅。","玉帳鴛鴦噴蘭麝，時落銀燈香灺。","女伴莫話孤眠，六宮羅綺三千。","一笑皆生百媚，宸衷教在誰邊。"]', '["禁闈秋夜，月探金窗罅。","玉帳鴛鴦噴蘭麝，时落銀灯香灺。","女伴莫話孤眠，六宮羅綺三千。","一笑皆生百媚，宸衷教在誰邊。"]', '诗', 'shi', '', NULL, '清平樂 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32654d69-48c7-4d34-ab41-939387e218f3', '清平樂 三', '清平乐 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["煙深水闊，音信無由達。","惟有碧天雲外月，偏照懸懸離別。","盡日感事傷懷，愁眉似鎖難開。","夜夜長留半被，待君魂夢歸來。"]', '["煙深水闊，音信無由達。","惟有碧天云外月，偏照懸懸離別。","尽日感事傷懷，愁眉似鎖难开。","夜夜长留半被，待君魂梦归来。"]', '诗', 'shi', '', NULL, '清平樂 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a56513d2-5de0-4941-b2f1-e0d33d681f20', '清平樂 四', '清平乐 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鸞衾鳳褥，夜夜常孤宿。","更被銀臺紅蠟燭，學妾淚珠相續。","花貌些子時光，拋人遠泛瀟湘。","欹枕悔聽寒漏，聲聲滴斷愁腸。"]', '["鸾衾鳳褥，夜夜常孤宿。","更被銀台紅蠟燭，学妾泪珠相續。","花貌些子时光，拋人远泛瀟湘。","欹枕悔听寒漏，声声滴斷愁腸。"]', '诗', 'shi', '', NULL, '清平樂 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1815804-563b-47ad-ace0-013a657a2454', '清平樂 五', '清平乐 五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["畫堂晨起，來報雪花墜。","高卷簾櫳看佳瑞，皓色遠迷庭砌。","盛氣光引爐煙，素草寒生玉佩。","應是天仙狂醉，亂把白雲揉碎。"]', '["畫堂晨起，来報雪花墜。","高卷簾櫳看佳瑞，皓色远迷庭砌。","盛氣光引爐煙，素草寒生玉佩。","應是天仙狂醉，亂把白云揉碎。"]', '诗', 'shi', '', NULL, '清平樂 五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a651660b-9ffb-4a39-bade-6f08a9a191c8', '欸乃曲 一', '欸乃曲 一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["偶存名跡在人間，順俗與時未安閑。","來謁大官兼問政，扁舟却入九疑山。"]', '["偶存名跡在人间，順俗與时未安闲。","来謁大官兼问政，扁舟却入九疑山。"]', '诗', 'shi', '', NULL, '欸乃曲 一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('825b4d77-f788-4fe9-8d4c-d03295a8d129', '欸乃曲 二', '欸乃曲 二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["湘江二月春水平，滿月和風宜夜行。","唱橈欲過平陽戍，守吏相呼問姓名。"]', '["湘江二月春水平，满月和风宜夜行。","唱橈欲過平陽戍，守吏相呼问姓名。"]', '诗', 'shi', '', NULL, '欸乃曲 二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47b69d9d-22a9-4cd2-8034-4a66ba168d04', '欸乃曲 三', '欸乃曲 三', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["千里楓林煙雨深，無朝無暮有猨吟。","倚橈靜聽曲中意，好似雲山韶濩音。"]', '["千里楓林煙雨深，無朝無暮有猨吟。","倚橈静听曲中意，好似云山韶濩音。"]', '诗', 'shi', '', NULL, '欸乃曲 三 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cafd6c88-e504-478a-817d-5fc1928fe196', '欸乃曲 四', '欸乃曲 四', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["零陵郡北湘水東，浯溪形勝滿湘中。","溪口石顛堪自逸，誰能相伴作漁翁。"]', '["零陵郡北湘水东，浯溪形勝满湘中。","溪口石顛堪自逸，誰能相伴作漁翁。"]', '诗', 'shi', '', NULL, '欸乃曲 四 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('319a4c84-ee02-4d8c-b2db-a10bb20d7b1f', '欸乃曲 五', '欸乃曲 五', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["下瀧船似入深淵，上瀧船似欲升天。","瀧南始到九疑郡，應絕高人乘興船。"]', '["下瀧船似入深淵，上瀧船似欲升天。","瀧南始到九疑郡，應絕高人乘兴船。"]', '诗', 'shi', '', NULL, '欸乃曲 五 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7916ae3-233e-46e1-97e1-7d561fb204f9', '漁父 一', '漁父 一', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["西塞山前白鷺飛，桃花流水鱖魚肥。","青箬笠，綠蓑衣，斜風細雨不須歸。"]', '["西塞山前白鷺飞，桃花流水鱖鱼肥。","青箬笠，綠蓑衣，斜风細雨不須归。"]', '诗', 'shi', '', NULL, '漁父 一 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec66e4c3-c21a-4d18-99f1-a21d0efcb1d7', '漁父 二', '漁父 二', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["釣臺漁父褐爲裘，兩兩三三舴艋舟。","能縱櫂，慣乘流，長江白浪不曾憂。"]', '["釣台漁父褐爲裘，兩兩三三舴艋舟。","能縱櫂，慣乘流，长江白浪不曾憂。"]', '诗', 'shi', '', NULL, '漁父 二 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d4c05b5-a879-4d95-b890-8774117b6f9f', '漁父 三', '漁父 三', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["霅溪灣裏釣魚翁，舴艋爲家西復東。","江上雪，浦邊風，笑著荷衣不歎窮。"]', '["霅溪灣裏釣鱼翁，舴艋爲家西复东。","江上雪，浦邊风，笑著荷衣不歎窮。"]', '诗', 'shi', '', NULL, '漁父 三 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f61f362-16e8-495e-bfbd-5914a758f42f', '漁父 四', '漁父 四', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["松江蟹舍主人歡，菰飯蓴羹亦共餐。","楓葉落，荻花乾，醉宿漁舟不覺寒。"]', '["松江蟹舍主人歡，菰飯蓴羹亦共餐。","楓葉落，荻花乾，醉宿漁舟不覺寒。"]', '诗', 'shi', '', NULL, '漁父 四 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37f68ce7-c771-45ee-96cc-c9107e641ec1', '漁父 五', '漁父 五', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["青草湖中月正圓，巴陵漁父櫂歌連。","釣車子，橛頭船，樂在風波不用仙。"]', '["青草湖中月正圓，巴陵漁父櫂歌連。","釣车子，橛头船，乐在风波不用仙。"]', '诗', 'shi', '', NULL, '漁父 五 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2d0b16b-1d7b-4735-8773-324bf0191675', '漁父', '漁父', '568ab229-a87e-425a-8e94-b305bf02d69d', '唐', '["樂是風波釣是閑，草堂松檜已勝攀。","太湖水，洞庭山，狂風浪起且須還。"]', '["乐是风波釣是闲，草堂松檜已勝攀。","太湖水，洞庭山，狂风浪起且須還。"]', '诗', 'shi', '', NULL, '漁父 張松齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a815f47-0331-40fe-9500-3a1b698b2deb', '章臺柳', '章台柳', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["章臺柳，章臺柳，往日依依今在否？縱使長條似舊垂，也應攀折他人手。"]', '["章台柳，章台柳，往日依依今在否？縱使长條似旧垂，也應攀折他人手。"]', '诗', 'shi', '', NULL, '章臺柳 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c467bd98-a27b-4810-8178-38eb61269796', '三臺 一', '三台 一', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["一年一年老去，明日後日花開。","未報長安平定，萬國豈得銜杯。"]', '["一年一年老去，明日後日花开。","未報长安平定，万国豈得銜杯。"]', '诗', 'shi', '', NULL, '三臺 一 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4a3ccdd-a8e6-45da-afcc-12a1db60f2c5', '三臺 二', '三台 二', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["冰泮寒塘水綠，雨餘百草皆生。","朝來衡門無事，晚下高齋有情。"]', '["冰泮寒塘水綠，雨餘百草皆生。","朝来衡门無事，晚下高斋有情。"]', '诗', 'shi', '', NULL, '三臺 二 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee3f8beb-8c76-4c7f-930c-ce1d566cced3', '調笑令 一', '調笑令 一', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["胡馬，胡馬，遠放燕支山下。","跑沙跑雪獨嘶，東望西望路迷。","迷路，迷路，邊草無窮日暮。"]', '["胡马，胡马，远放燕支山下。","跑沙跑雪独嘶，东望西望路迷。","迷路，迷路，邊草無窮日暮。"]', '诗', 'shi', '', NULL, '調笑令 一 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab3d4352-40f7-4d0c-9809-d591da9f2c45', '調笑令 二', '調笑令 二', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["河漢，河漢，曉挂秋城漫漫。","愁人起望相思，塞北江南別離。","離別，離別，河漢雖同路絕。"]', '["河漢，河漢，晓挂秋城漫漫。","愁人起望相思，塞北江南別離。","離別，離別，河漢雖同路絕。"]', '诗', 'shi', '', NULL, '調笑令 二 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4826c899-c283-4054-84a9-6a290c6c62db', '三臺 一', '三台 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["魚藻池邊射鴨，芙蓉苑裏看花。","日色柘袍相似，不著紅鸞扇遮。"]', '["鱼藻池邊射鴨，芙蓉苑裏看花。","日色柘袍相似，不著紅鸾扇遮。"]', '诗', 'shi', '', NULL, '三臺 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc2e8477-7436-4e4c-9b8c-bf242a325691', '三臺 二', '三台 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["池北池南草綠，殿前殿後花紅。","天子千秋萬歲，未央明月清風。"]', '["池北池南草綠，殿前殿後花紅。","天子千秋万歲，未央明月清风。"]', '诗', 'shi', '', NULL, '三臺 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55ea44f4-fd09-4fc2-a06c-b0012ff44281', '三臺 三', '三台 三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["揚州橋邊小婦，長干市裏商人。","三年不得消息，各自拜鬼求神。"]', '["揚州橋邊小婦，长干市裏商人。","三年不得消息，各自拜鬼求神。"]', '诗', 'shi', '', NULL, '三臺 三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6d96ec6-f3d5-429e-9e29-52c108f34561', '三臺 四', '三台 四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["青草湖邊草色，飛猨嶺上猨聲。","萬里三湘客到，有風有雨人行。"]', '["青草湖邊草色，飞猨嶺上猨声。","万里三湘客到，有风有雨人行。"]', '诗', 'shi', '', NULL, '三臺 四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4325ee75-6b58-4d3e-b6ad-3b3df49f7f24', '三臺 五', '三台 五', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["樹頭花落花開，道上人去人來。","朝愁暮愁即老，百年幾度三臺。"]', '["樹头花落花开，道上人去人来。","朝愁暮愁即老，百年幾度三台。"]', '诗', 'shi', '', NULL, '三臺 五 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50b9cd44-6c49-4e7e-95d0-ef47fc4a00a0', '三臺 六', '三台 六', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["鬬身彊健且爲，頭白齒落難追。","準擬百年千歲，能得幾許多時。"]', '["鬬身彊健且爲，头白齒落难追。","準擬百年千歲，能得幾許多时。"]', '诗', 'shi', '', NULL, '三臺 六 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53640410-5611-4d86-83ed-c0aa7f2e4930', '調笑令 一', '調笑令 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["團扇，團扇，美人竝來遮面。","玉顏顦顇三年，誰復商量管弦。","弦管，弦管，春草昭陽路斷。"]', '["團扇，團扇，美人竝来遮面。","玉顏顦顇三年，誰复商量管弦。","弦管，弦管，春草昭陽路斷。"]', '诗', 'shi', '', NULL, '調笑令 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b5ad1b1-6a9c-492b-860b-936e922323da', '調笑令 二', '調笑令 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["胡蝶，胡蝶，飛上金枝玉葉。","君前對舞春風，百葉桃花樹紅。","紅樹，紅樹，燕語鶯啼日暮。"]', '["胡蝶，胡蝶，飞上金枝玉葉。","君前对舞春风，百葉桃花樹紅。","紅樹，紅樹，燕語鶯啼日暮。"]', '诗', 'shi', '', NULL, '調笑令 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7324810b-af18-4a39-af66-bbf93c45f247', '調笑令 三', '調笑令 三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["羅袖，羅袖，暗舞春風依舊。","遙看歌舞玉樓，好日新妝坐愁。","愁坐，愁坐，一世虛生虛過。"]', '["羅袖，羅袖，暗舞春风依旧。","遙看歌舞玉楼，好日新妝坐愁。","愁坐，愁坐，一世虛生虛過。"]', '诗', 'shi', '', NULL, '調笑令 三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b730ae2-7e32-4eb7-9b37-e1844e83a743', '調笑令 四', '調笑令 四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["楊柳，楊柳，日暮白沙渡口。","船頭江水茫茫，商人少婦斷腸。","腸斷，腸斷，鷓鴣夜飛失伴。"]', '["楊柳，楊柳，日暮白沙渡口。","船头江水茫茫，商人少婦斷腸。","腸斷，腸斷，鷓鴣夜飞失伴。"]', '诗', 'shi', '', NULL, '調笑令 四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('125198bd-4bfd-43ef-ae9c-74bbd8fc114e', '調笑令', '調笑令', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["邊草，邊草，邊草盡來兵老。","山南山北雪晴，千里萬里月明。","明月，明月，胡笳一聲愁絕。"]', '["邊草，邊草，邊草尽来兵老。","山南山北雪晴，千里万里月明。","明月，明月，胡笳一声愁絕。"]', '诗', 'shi', '', NULL, '調笑令 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45868452-c3f4-449b-be00-11027f4d11c5', '紇那曲 一', '紇那曲 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["楊柳鬱青青，竹枝無限情。","同郎一回顧，聽唱紇那聲。"]', '["楊柳鬱青青，竹枝無限情。","同郎一回顧，听唱紇那声。"]', '诗', 'shi', '', NULL, '紇那曲 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f443629-464c-4f44-aab8-ebd11e96e133', '紇那曲 二', '紇那曲 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["蹋曲興無窮，調同辭不同。","願郎千萬壽，長作主人翁。"]', '["蹋曲兴無窮，調同辞不同。","願郎千万壽，长作主人翁。"]', '诗', 'shi', '', NULL, '紇那曲 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f98769ab-7570-403c-9cc4-b0a37f53b128', '憶江南 一', '憶江南 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["春去也，多謝洛城人。","弱柳從風疑舉袂，叢蘭裛露似霑巾，獨坐亦含嚬。"]', '["春去也，多謝洛城人。","弱柳從风疑舉袂，叢蘭裛露似霑巾，独坐亦含嚬。"]', '诗', 'shi', '', NULL, '憶江南 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ba48f1b-7fa7-4af7-b4ee-dabca81e4aa6', '憶江南 二', '憶江南 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["春去也，共惜豔陽年。","猶有桃花流水上，無辭竹葉醉尊前，惟待見青天。"]', '["春去也，共惜豔陽年。","猶有桃花流水上，無辞竹葉醉尊前，惟待见青天。"]', '诗', 'shi', '', NULL, '憶江南 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe80a80e-47ab-4df7-9caf-38696df0a6d2', '瀟湘神 一', '瀟湘神 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["湘水流，湘水流，九疑雲物至今愁。","若問二妃何處所，零陵芳草露中秋。"]', '["湘水流，湘水流，九疑云物至今愁。","若问二妃何处所，零陵芳草露中秋。"]', '诗', 'shi', '', NULL, '瀟湘神 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb5def99-f902-458f-be0a-0cf05a46f34b', '瀟湘神 二', '瀟湘神 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["斑竹枝，斑竹枝，淚痕點點寄相思。","楚客欲聽瑤瑟怨，瀟湘深夜月明時。"]', '["斑竹枝，斑竹枝，泪痕点点寄相思。","楚客欲听瑤瑟怨，瀟湘深夜月明时。"]', '诗', 'shi', '', NULL, '瀟湘神 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d114e7b2-6988-42a2-9715-8bb1571d760d', '拋毬樂 一', '拋毬乐 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["五色繡團圓，登君玳瑁筵。","最宜紅燭下，偏稱落花前。","上客如先起，應須贈一船。"]', '["五色繡團圓，登君玳瑁筵。","最宜紅燭下，偏稱落花前。","上客如先起，應須贈一船。"]', '诗', 'shi', '', NULL, '拋毬樂 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e2e08eb-8931-40e3-94b8-3e0938dc9947', '拋毬樂 二', '拋毬乐 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["春早見花枝，朝朝恨發遲。","及看花落後，却憶未開時。","幸有拋毬樂，一杯君莫辭。"]', '["春早见花枝，朝朝恨發遲。","及看花落後，却憶未开时。","幸有拋毬乐，一杯君莫辞。"]', '诗', 'shi', '', NULL, '拋毬樂 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90ad61e9-31b9-47da-8e98-880130a5bb2e', '花非花', '花非花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["花非花，霧非霧，夜半來，天明去。","來如春夢不多時，去似朝雲無覓處。"]', '["花非花，霧非霧，夜半来，天明去。","来如春梦不多时，去似朝云無覓处。"]', '诗', 'shi', '', NULL, '花非花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0449a6d9-ad81-4cea-99d4-70018fc863a2', '憶江南 一', '憶江南 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江南好，風景舊曾諳。","日出江花紅勝火，春來江水綠如藍，能不憶江南。"]', '["江南好，风景旧曾諳。","日出江花紅勝火，春来江水綠如藍，能不憶江南。"]', '诗', 'shi', '', NULL, '憶江南 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e8038d4-685d-47fe-a65f-3fb103a42f50', '憶江南 二', '憶江南 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江南憶，最憶是杭州。","山寺月中尋桂子，郡亭枕上看潮頭，何日更重遊。"]', '["江南憶，最憶是杭州。","山寺月中尋桂子，郡亭枕上看潮头，何日更重游。"]', '诗', 'shi', '', NULL, '憶江南 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23124f06-e77f-4e20-b28c-f848c1a7479d', '憶江南 三', '憶江南 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江南憶，其次憶吳宮。","吳酒一杯春竹葉，吳娃雙舞醉芙蓉，早晚得相逢。"]', '["江南憶，其次憶吳宮。","吳酒一杯春竹葉，吳娃雙舞醉芙蓉，早晚得相逢。"]', '诗', 'shi', '', NULL, '憶江南 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a0bfa8a-591e-437b-bd39-b5fdbd5b5bd2', '如夢令 一', '如梦令 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["前度小花靜院，不比尋常時見。","見了又還休，愁却等閑分散。","腸斷，腸斷，記取釵橫鬢亂。"]', '["前度小花静院，不比尋常时见。","见了又還休，愁却等闲分散。","腸斷，腸斷，記取釵橫鬢亂。"]', '诗', 'shi', '', NULL, '如夢令 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03c21a01-73a7-4bb0-b5aa-0852c8fce6fb', '如夢令 二', '如梦令 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["落月西窗驚起，好箇怱怱些子。","鬒鬢嚲輕鬆，凝了一雙秋水。","告你，告你，休向人間整理。"]', '["落月西窗驚起，好箇怱怱些子。","鬒鬢嚲轻鬆，凝了一雙秋水。","告你，告你，休向人间整理。"]', '诗', 'shi', '', NULL, '如夢令 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdaa4410-880c-4830-b7ef-d770ecdc28cc', '如夢令 三', '如梦令 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["頻日雅歡幽會，打得來來越曬。","說著暫分飛，蹙損一雙眉黛。","無奈，無奈，兩箇心兒總待。"]', '["頻日雅歡幽會，打得来来越曬。","说著暫分飞，蹙損一雙眉黛。","無奈，無奈，兩箇心兒總待。"]', '诗', 'shi', '', NULL, '如夢令 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4c60d0e-3945-4461-a9e1-d1d025227880', '長相思 一', '长相思 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["汴水流，泗水流，流到瓜洲古渡頭，吳山點點愁。","思悠悠，恨悠悠，恨到歸時方始休，月明人倚樓。"]', '["汴水流，泗水流，流到瓜洲古渡头，吳山点点愁。","思悠悠，恨悠悠，恨到归时方始休，月明人倚楼。"]', '诗', 'shi', '', NULL, '長相思 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('854a4e93-dc1b-4bde-a05c-d647097f9dcc', '長相思 二', '长相思 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["深畫眉，淺畫眉，蟬鬢鬅鬙雲滿衣，陽臺行雨回。","巫山高，巫山低，暮雨瀟瀟郎不歸，空房獨守時。"]', '["深畫眉，淺畫眉，蟬鬢鬅鬙云满衣，陽台行雨回。","巫山高，巫山低，暮雨瀟瀟郎不归，空房独守时。"]', '诗', 'shi', '', NULL, '長相思 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad3ff46e-1956-472a-9a70-d9f43d2084ba', '謫仙怨', '謫仙怨', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["晴川落日初低，惆悵孤舟解攜。","鳥向平蕪遠近，人隨流水東西。","白雲千里萬里，明月前溪後溪。","獨恨長沙謫去，江潭春草萋萋。"]', '["晴川落日初低，惆悵孤舟解携。","鸟向平蕪远近，人隨流水东西。","白云千里万里，明月前溪後溪。","独恨长沙謫去，江潭春草萋萋。"]', '诗', 'shi', '', NULL, '謫仙怨 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba3d87f9-cdcb-4f70-ac65-b69464a62794', '廣謫仙怨', '廣謫仙怨', '8e1ea6e8-e96d-4239-a955-5ebb7a5d0572', '唐', '["胡塵犯闕衝關，金輅提攜玉顏。","雲雨此時蕭散，君王何日歸還。","傷心朝恨暮恨，回首千山萬山。","獨望天邊初月，蛾眉猶自彎彎。"]', '["胡塵犯闕衝关，金輅提携玉顏。","云雨此时蕭散，君王何日归還。","傷心朝恨暮恨，回首千山万山。","独望天邊初月，蛾眉猶自彎彎。"]', '诗', 'shi', '', NULL, '廣謫仙怨 竇弘餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afdfbef0-2c07-4161-bc63-e5840e94a833', '廣謫仙怨', '廣謫仙怨', '9b42332b-d30a-4ffa-b7bb-b4ae1a591636', '唐', '["晴山礙目橫天，綠疊君王馬前。","鑾輅西巡蜀國，龍顏東望秦川。","曲江魂斷芳草，妃子愁凝暮煙。","長笛此時吹罷，何言獨爲嬋娟。"]', '["晴山礙目橫天，綠叠君王马前。","鑾輅西巡蜀国，龙顏东望秦川。","曲江魂斷芳草，妃子愁凝暮煙。","长笛此时吹罷，何言独爲嬋娟。"]', '诗', 'shi', '', NULL, '廣謫仙怨 康駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21360c26-9b3a-490b-a231-8fc91d7ceca7', '八六子', '八六子', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["洞房深，畫屏燈照，山色凝翠沈沈。","聽夜雨，冷滴芭蕉，驚斷紅窗好夢，龍煙細飄繡衾。","辭恩久歸長信，鳳帳蕭疎，椒殿閑扃。","輦路苔侵，繡簾垂，遲遲漏傳丹禁。","蕣華偷悴，翠鬟羞整，愁坐望處，金輿漸遠。","何時綵仗重臨，正消魂，梧桐又移翠陰。"]', '["洞房深，畫屏灯照，山色凝翠沈沈。","听夜雨，冷滴芭蕉，驚斷紅窗好梦，龙煙細飄繡衾。","辞恩久归长信，鳳帳蕭疎，椒殿闲扃。","輦路苔侵，繡簾垂，遲遲漏傳丹禁。","蕣华偷悴，翠鬟羞整，愁坐望处，金輿漸远。","何时綵仗重臨，正消魂，梧桐又移翠陰。"]', '诗', 'shi', '', NULL, '八六子 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d46a229e-476e-4696-bd0a-4a5a9f8fe6aa', '憶江南', '憶江南', '2f2d1783-f04b-4f34-962b-b73e4cd4bd69', '唐', '["平生願，願作樂中箏。","得近玉人纖手子，砑羅裙上放嬌聲，便死也爲榮。"]', '["平生願，願作乐中箏。","得近玉人纖手子，砑羅裙上放嬌声，便死也爲榮。"]', '诗', 'shi', '', NULL, '憶江南 崔懷寶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8dc5127-3cd8-44b8-8be0-7474b3c50891', '閑中好', '闲中好', '9c15b7ed-1faf-4d56-8990-7ab8d9f469a0', '唐', '["閑中好，盡日松爲侶。","此趣人不知，輕風度僧語。"]', '["闲中好，尽日松爲侶。","此趣人不知，轻风度僧語。"]', '诗', 'shi', '', NULL, '閑中好 鄭符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4b63d22-e387-4bb6-9770-811082b02653', '閑中好', '闲中好', 'ebd93182-a999-4dc8-8da7-a327b143f8d7', '唐', '["閑中好，塵務不縈心。","坐對當窗木，看移三面陰。"]', '["闲中好，塵務不縈心。","坐对當窗木，看移三面陰。"]', '诗', 'shi', '', NULL, '閑中好 段成式 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f87a7a6-f620-4d6c-a446-09fa9c0d8fbc', '閑中好', '闲中好', 'b34fe56e-43e8-4b97-9f4a-e2595e92f67d', '唐', '["閑中好，幽磬度聲遲。","卷上論題肇，畫盡僧姓支。"]', '["闲中好，幽磬度声遲。","卷上論題肇，畫尽僧姓支。"]', '诗', 'shi', '', NULL, '閑中好 張希復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d99e2f5e-ee89-4cd7-a863-57c59f6580c1', '南歌子 一', '南歌子 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["手裏金鸚鵡，胸前繡鳳凰。","偷眼暗形相。","不如從嫁與，作鴛鴦。"]', '["手裏金鸚鵡，胸前繡鳳凰。","偷眼暗形相。","不如從嫁與，作鴛鴦。"]', '诗', 'shi', '', NULL, '南歌子 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49a955c2-6df5-4738-8cbb-92439838ae5d', '南歌子 二', '南歌子 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["似帶如絲柳，團酥握雪花。","簾卷玉鉤斜。","九衢塵欲暮，逐香車。"]', '["似带如絲柳，團酥握雪花。","簾卷玉鉤斜。","九衢塵欲暮，逐香车。"]', '诗', 'shi', '', NULL, '南歌子 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4079336c-10ee-4be9-b3e2-f441de49255a', '南歌子 三', '南歌子 三', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["倭墮低梳髻，連娟細掃眉。","終日兩相思。","爲君憔悴盡，百花時。"]', '["倭墮低梳髻，連娟細掃眉。","終日兩相思。","爲君憔悴尽，百花时。"]', '诗', 'shi', '', NULL, '南歌子 三 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('584bfc0d-09cb-4658-ae15-bf501081ad0a', '南歌子 四', '南歌子 四', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["臉上金霞細，眉間翠鈿深。","欹枕覆鴛衾。","隔簾鸎百轉，感君心。"]', '["臉上金霞細，眉间翠鈿深。","欹枕覆鴛衾。","隔簾鸎百轉，感君心。"]', '诗', 'shi', '', NULL, '南歌子 四 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29d3df5c-6e64-422a-a069-15fd99d50250', '南歌子 五', '南歌子 五', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["撲蘂添黃子，呵花滿翠鬟。","鴛枕映屏山。","月明三五夜，對芳顏。"]', '["撲蘂添黄子，呵花满翠鬟。","鴛枕映屏山。","月明三五夜，对芳顏。"]', '诗', 'shi', '', NULL, '南歌子 五 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2408519c-0eef-4b3b-b96c-a1259ed1922e', '南歌子 六', '南歌子 六', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["轉盼如波眼，娉婷似柳腰。","花裏暗相招。","憶君腸欲斷，恨春宵。"]', '["轉盼如波眼，娉婷似柳腰。","花裏暗相招。","憶君腸欲斷，恨春宵。"]', '诗', 'shi', '', NULL, '南歌子 六 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e189e4f-276d-4a7e-8e00-8863c6147dd7', '南歌子 七', '南歌子 七', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["嬾拂鴛鴦枕，休縫翡翠裙。","羅帳罷爐熏。","近來心更切，爲思君。"]', '["嬾拂鴛鴦枕，休縫翡翠裙。","羅帳罷爐熏。","近来心更切，爲思君。"]', '诗', 'shi', '', NULL, '南歌子 七 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f11f101-e336-46bd-abc2-85695fb6f265', '荷葉杯 一', '荷葉杯 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["一點露珠凝冷，波影，滿池塘。","綠莖紅豔兩相亂，腸斷，水風涼。"]', '["一点露珠凝冷，波影，满池塘。","綠莖紅豔兩相亂，腸斷，水风涼。"]', '诗', 'shi', '', NULL, '荷葉杯 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc72eed6-4019-476d-931b-f188b00963c2', '荷葉杯 二', '荷葉杯 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["鏡水夜來秋月，如雪，采蓮時。","小娘紅粉對寒浪，惆悵，正思惟。"]', '["镜水夜来秋月，如雪，采蓮时。","小娘紅粉对寒浪，惆悵，正思惟。"]', '诗', 'shi', '', NULL, '荷葉杯 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bbcb4bd-3d77-4200-8159-27a16d599c93', '荷葉杯 三', '荷葉杯 三', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["楚女欲歸南浦，朝雨，濕愁紅。","小船搖漾入花裏，波起，隔西風。"]', '["楚女欲归南浦，朝雨，濕愁紅。","小船搖漾入花裏，波起，隔西风。"]', '诗', 'shi', '', NULL, '荷葉杯 三 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fedbcda-2e90-45b2-bca9-5ce76a39b0c6', '憶江南 一', '憶江南 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["千萬恨，恨極在天涯。","山月不知心裏事，水風空落眼前花，搖曳碧雲斜。"]', '["千万恨，恨極在天涯。","山月不知心裏事，水风空落眼前花，搖曳碧云斜。"]', '诗', 'shi', '', NULL, '憶江南 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d636903d-bd15-4d66-8198-e245421b2d43', '憶江南 二', '憶江南 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["梳洗罷，獨倚望江樓。","過盡千帆皆不是，斜暉脈脈水悠悠，腸斷白蘋洲。"]', '["梳洗罷，独倚望江楼。","過尽千帆皆不是，斜暉脈脈水悠悠，腸斷白蘋洲。"]', '诗', 'shi', '', NULL, '憶江南 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a3c48ce-3087-4345-9060-bcace431fa06', '蕃女怨 一', '蕃女怨 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["萬枝香雪開已遍，細雨雙燕。","鈿蟬箏，金雀扇，畫梁相見。","鴈門消息不歸來，又飛回。"]', '["万枝香雪开已遍，細雨雙燕。","鈿蟬箏，金雀扇，畫梁相见。","鴈门消息不归来，又飞回。"]', '诗', 'shi', '', NULL, '蕃女怨 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f47370d-d3b1-405d-822c-14cb1bccd6ff', '蕃女怨 二', '蕃女怨 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["磧南沙上驚鴈起，飛雪千里。","玉連環，金鏃箭，年年征戰。","畫樓離恨錦屏空，杏花紅。"]', '["磧南沙上驚鴈起，飞雪千里。","玉連环，金鏃箭，年年征戰。","畫楼離恨錦屏空，杏花紅。"]', '诗', 'shi', '', NULL, '蕃女怨 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0347b7f5-9733-4661-94b3-d32e7b2e41c1', '遐方怨 一', '遐方怨 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["憑繡檻，解羅幃。","未得君書，斷腸瀟湘春鴈飛。","不知征馬幾時歸。","海棠花謝也，雨霏霏。"]', '["憑繡檻，解羅幃。","未得君书，斷腸瀟湘春鴈飞。","不知征马幾时归。","海棠花謝也，雨霏霏。"]', '诗', 'shi', '', NULL, '遐方怨 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8e18621-ec00-42be-88be-ead999a9b448', '遐方怨 二', '遐方怨 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["花半拆，雨初晴。","未卷珠簾，夢殘惆悵聞曉鸎。","宿妝眉淺粉山橫。","約鬟鸞鏡裏，繡羅輕。"]', '["花半拆，雨初晴。","未卷珠簾，梦殘惆悵闻晓鸎。","宿妝眉淺粉山橫。","約鬟鸾镜裏，繡羅轻。"]', '诗', 'shi', '', NULL, '遐方怨 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2352b4ff-5ef8-4823-a9aa-c40b51317d91', '訴衷情', '訴衷情', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["鸎語，花舞，春晝午，雨霏微。","金帶枕，宮錦，鳳凰帷。","柳弱燕交飛，依依。","遼陽音信稀，夢中歸。"]', '["鸎語，花舞，春晝午，雨霏微。","金带枕，宮錦，鳳凰帷。","柳弱燕交飞，依依。","遼陽音信稀，梦中归。"]', '诗', 'shi', '', NULL, '訴衷情 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09e2a67e-6769-40cb-8e77-5d3997fc0910', '定西番 一', '定西番 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["漢使昔年離別，攀弱柳，折寒梅，上高臺。","千里玉關春雪，鴈來人不來。","羌笛一聲愁絕，月裴回。"]', '["漢使昔年離別，攀弱柳，折寒梅，上高台。","千里玉关春雪，鴈来人不来。","羌笛一声愁絕，月裴回。"]', '诗', 'shi', '', NULL, '定西番 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c9069ed-53b4-4a1d-a7ee-a8886755fe84', '定西番 二', '定西番 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["海燕欲飛調羽，萱草綠，杏花紅，隔簾櫳。","雙鬢翠霞金縷，一枝春豔濃。","樓上月明三五，瑣窗中。"]', '["海燕欲飞調羽，萱草綠，杏花紅，隔簾櫳。","雙鬢翠霞金縷，一枝春豔濃。","楼上月明三五，瑣窗中。"]', '诗', 'shi', '', NULL, '定西番 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4335ddbc-1bb4-40a8-a1cc-7d54f28b9da7', '定西番 三', '定西番 三', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["細雨曉鸎春晚，人似玉，柳如眉，正相思。","羅幕翠簾初卷，鏡中花一枝。","腸斷塞門消息，鴈來稀。"]', '["細雨晓鸎春晚，人似玉，柳如眉，正相思。","羅幕翠簾初卷，镜中花一枝。","腸斷塞门消息，鴈来稀。"]', '诗', 'shi', '', NULL, '定西番 三 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('309d735a-1524-4b44-bdcd-fabcfa11b5de', '思帝鄉', '思帝乡', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["花花，滿枝紅似霞。","羅袖畫簾腸斷，卓香車。","回面共人閑語，戰箆金鳳斜。","惟有阮郎春盡，不歸家。"]', '["花花，满枝紅似霞。","羅袖畫簾腸斷，卓香车。","回面共人闲語，戰箆金鳳斜。","惟有阮郎春尽，不归家。"]', '诗', 'shi', '', NULL, '思帝鄉 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('013cb0b3-b1fa-4af0-90a4-7a9b726de72a', '酒泉子 一', '酒泉子 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["花映柳條，閑向綠萍池上。","凭欄干，窺細浪，雨蕭蕭。","近來音信兩疎索，洞房空寂寞。","掩銀屏，垂翠箔，度春宵。"]', '["花映柳條，闲向綠萍池上。","凭欄干，窺細浪，雨蕭蕭。","近来音信兩疎索，洞房空寂寞。","掩銀屏，垂翠箔，度春宵。"]', '诗', 'shi', '', NULL, '酒泉子 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b09b9100-ebd2-4273-bce3-ddd1e4aaa0c2', '酒泉子 二', '酒泉子 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["日映紗窗，金鴨小屏山碧。","故鄉春，煙靄隔，背蘭釭。","宿妝惆悵倚高閣，千里雲影薄。","草初齊，花又落，燕雙飛。"]', '["日映紗窗，金鴨小屏山碧。","故乡春，煙靄隔，背蘭釭。","宿妝惆悵倚高閣，千里云影薄。","草初齊，花又落，燕雙飞。"]', '诗', 'shi', '', NULL, '酒泉子 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7cf2121-6dad-4ab1-87d5-617011d94aea', '酒泉子 三', '酒泉子 三', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["楚女不歸，樓枕小河春水。","月孤明，風又起，杏花稀。","玉釵斜篸雲鬟重，裙上金縷鳳。","八行書，千里夢，鴈南飛。"]', '["楚女不归，楼枕小河春水。","月孤明，风又起，杏花稀。","玉釵斜篸云鬟重，裙上金縷鳳。","八行书，千里梦，鴈南飞。"]', '诗', 'shi', '', NULL, '酒泉子 三 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2af81995-8280-4643-97c8-6338ac5b6823', '酒泉子 四', '酒泉子 四', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["羅帶惹香，猶繫別時紅豆。","淚痕新，金縷舊，斷離腸。","一雙嬌燕語雕梁，還是去年時節。","綠楊濃，芳草歇，柳花狂。"]', '["羅带惹香，猶繫別时紅豆。","泪痕新，金縷旧，斷離腸。","一雙嬌燕語雕梁，還是去年时節。","綠楊濃，芳草歇，柳花狂。"]', '诗', 'shi', '', NULL, '酒泉子 四 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d0722d8-d700-4352-aa87-65ebb23e15a3', '玉蝴蝶', '玉蝴蝶', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["秋風淒切傷離，行客未歸時。","塞外草先衰，江南鴈到遲。","芙蓉凋嫩臉，楊柳墮新眉。","搖落使人悲，斷腸誰得知。"]', '["秋风淒切傷離，行客未归时。","塞外草先衰，江南鴈到遲。","芙蓉凋嫩臉，楊柳墮新眉。","搖落使人悲，斷腸誰得知。"]', '诗', 'shi', '', NULL, '玉蝴蝶 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10cb84f1-60b5-4f09-8534-4e0c7cba518d', '女冠子 一', '女冠子 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["含嬌含笑，宿翠殘紅窈窕，鬢如蟬。","寒玉簪秋水，輕紗卷碧煙。","雪胸鸞鏡裏，琪樹鳳樓前。","寄語青娥伴，早求仙。"]', '["含嬌含笑，宿翠殘紅窈窕，鬢如蟬。","寒玉簪秋水，轻紗卷碧煙。","雪胸鸾镜裏，琪樹鳳楼前。","寄語青娥伴，早求仙。"]', '诗', 'shi', '', NULL, '女冠子 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d6d08c3-7cc8-4d52-ba70-7182b5e9a82b', '女冠子 二', '女冠子 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["霞帔雲髮，鈿鏡仙容似雪，畫愁眉。","遮語回輕扇，含羞下繡幃。","玉樓相望久，花洞恨來遲。","早晚乘鸞去，莫相遺。"]', '["霞帔云髮，鈿镜仙容似雪，畫愁眉。","遮語回轻扇，含羞下繡幃。","玉楼相望久，花洞恨来遲。","早晚乘鸾去，莫相遺。"]', '诗', 'shi', '', NULL, '女冠子 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a0f1a5e-baa5-4627-aff1-6ffdac55ca26', '歸國遙 一', '归国遙 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["香玉，翠鳳寶釵垂{罒/彔}𦌉，鈿筐交勝金粟，越羅春水綠。","畫堂照簾殘燭，夢餘更漏促。","謝娘無限心曲，曉屏山斷續。"]', '["香玉，翠鳳寶釵垂{罒/彔}𦌉，鈿筐交勝金粟，越羅春水綠。","畫堂照簾殘燭，梦餘更漏促。","謝娘無限心曲，晓屏山斷續。"]', '诗', 'shi', '', NULL, '歸國遙 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0083a2d5-c7d0-4be7-a8c3-7c76ebbfe3fe', '歸國遙 二', '归国遙 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["雙臉，小鳳戰箆金颭豔，舞衣無力風歛，藕絲秋色染。","錦帳繡幃斜掩，露珠清曉簟。","粉心黃蘂花靨，黛眉山兩點。"]', '["雙臉，小鳳戰箆金颭豔，舞衣無力风歛，藕絲秋色染。","錦帳繡幃斜掩，露珠清晓簟。","粉心黄蘂花靨，黛眉山兩点。"]', '诗', 'shi', '', NULL, '歸國遙 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20e442bb-ecba-4adc-94cd-67ab05096349', '菩薩蠻 一', '菩薩蠻 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["小山重疊金明滅，鬢雲欲度香顋雪。","嬾起畫蛾眉，弄妝梳洗遲。","照花前後鏡，花面交相映。","新帖繡羅襦，雙雙金鷓鴣。"]', '["小山重叠金明滅，鬢云欲度香顋雪。","嬾起畫蛾眉，弄妝梳洗遲。","照花前後镜，花面交相映。","新帖繡羅襦，雙雙金鷓鴣。"]', '诗', 'shi', '', NULL, '菩薩蠻 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f1328cc-d58f-4320-a56a-1f8c2c2b07a4', '菩薩蠻 二', '菩薩蠻 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["水精簾裏頗黎枕，暖香惹夢鴛鴦錦。","江上柳如煙，鴈飛殘月天。","藕絲秋色淺，人勝參差翦。","雙鬢隔香紅，玉釵頭上風。"]', '["水精簾裏頗黎枕，暖香惹梦鴛鴦錦。","江上柳如煙，鴈飞殘月天。","藕絲秋色淺，人勝參差翦。","雙鬢隔香紅，玉釵头上风。"]', '诗', 'shi', '', NULL, '菩薩蠻 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d653ca8-6648-457e-9174-9787265e7a12', '菩薩蠻 三', '菩薩蠻 三', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["蘂黃無限當山額，宿妝隱笑紗窗隔。","相見牡丹時，暫來還別離。","翠釵金作股，釵上蝶雙舞。","心事竟誰知，月明花滿枝。"]', '["蘂黄無限當山額，宿妝隐笑紗窗隔。","相见牡丹时，暫来還別離。","翠釵金作股，釵上蝶雙舞。","心事竟誰知，月明花满枝。"]', '诗', 'shi', '', NULL, '菩薩蠻 三 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94d5cd0f-ec65-45e1-83e2-eb316bb347c4', '菩薩蠻 四', '菩薩蠻 四', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["翠翹金縷雙鸂鶒，水文細起春池碧。","池上海棠梨，雨晴紅滿枝。","繡衫遮笑靨，煙草黏飛蝶。","青瑣對芳菲，玉關音信稀。"]', '["翠翹金縷雙鸂鶒，水文細起春池碧。","池上海棠梨，雨晴紅满枝。","繡衫遮笑靨，煙草黏飞蝶。","青瑣对芳菲，玉关音信稀。"]', '诗', 'shi', '', NULL, '菩薩蠻 四 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d3a1249-3b58-4360-996c-8c9408a8cb0e', '菩薩蠻 五', '菩薩蠻 五', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["杏花含露團香雪，綠楊陌上多離別。","燈在月朧明，覺來聞曉鸎。","玉鉤褰翠幕，妝淺舊眉薄。","春夢正關情，鏡中蟬鬢輕。"]', '["杏花含露團香雪，綠楊陌上多離別。","灯在月朧明，覺来闻晓鸎。","玉鉤褰翠幕，妝淺旧眉薄。","春梦正关情，镜中蟬鬢轻。"]', '诗', 'shi', '', NULL, '菩薩蠻 五 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e57f3096-5a69-444e-8454-517585ad99a4', '菩薩蠻 六', '菩薩蠻 六', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["玉樓明月長相憶，柳絲嫋娜春無力。","門外草萋萋，送君聞馬嘶。","畫羅金翡翠，香燭銷成淚。","花落子規啼，綠窗殘夢迷。"]', '["玉楼明月长相憶，柳絲嫋娜春無力。","门外草萋萋，送君闻马嘶。","畫羅金翡翠，香燭銷成泪。","花落子規啼，綠窗殘梦迷。"]', '诗', 'shi', '', NULL, '菩薩蠻 六 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('129d6ad5-e635-4562-9e39-615b639c1d71', '菩薩蠻 七', '菩薩蠻 七', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["鳳凰相對盤金縷，牡丹一夜經微雨。","明鏡照新妝，鬢輕雙臉長。","畫樓相望久，闌外垂絲柳。","音信不歸來，社前雙燕回。"]', '["鳳凰相对盤金縷，牡丹一夜經微雨。","明镜照新妝，鬢轻雙臉长。","畫楼相望久，闌外垂絲柳。","音信不归来，社前雙燕回。"]', '诗', 'shi', '', NULL, '菩薩蠻 七 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0d6dc9e-67cb-4925-8136-7065816e7dd3', '菩薩蠻 八', '菩薩蠻 八', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["牡丹花謝鸎聲歇，綠楊滿院中庭月。","相憶夢難成，背窗燈半明。","翠鈿金壓臉，寂寞香閨掩。","人遠淚闌干，燕飛春又殘。"]', '["牡丹花謝鸎声歇，綠楊满院中庭月。","相憶梦难成，背窗灯半明。","翠鈿金壓臉，寂寞香閨掩。","人远泪闌干，燕飞春又殘。"]', '诗', 'shi', '', NULL, '菩薩蠻 八 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aec61346-5b64-4770-9e3e-1a29ae2c80c1', '菩薩蠻 九', '菩薩蠻 九', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["滿宮明月梨花白，故人萬里關山隔。","金鴈一雙飛，淚痕霑繡衣。","小園芳草綠，家住越溪曲。","楊柳色依依，燕歸君不歸。"]', '["满宮明月梨花白，故人万里关山隔。","金鴈一雙飞，泪痕霑繡衣。","小园芳草綠，家住越溪曲。","楊柳色依依，燕归君不归。"]', '诗', 'shi', '', NULL, '菩薩蠻 九 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a35ef9ce-aeb6-4e0e-914d-1aab3aebe6bb', '菩薩蠻 十', '菩薩蠻 十', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["寶函鈿雀金鸂鶒，沈香閣上吳山碧。","楊柳又如絲，驛橋春雨時。","畫樓音信斷，芳草江南岸。","鸞鏡與花枝，此情誰得知。"]', '["寶函鈿雀金鸂鶒，沈香閣上吳山碧。","楊柳又如絲，驛橋春雨时。","畫楼音信斷，芳草江南岸。","鸾镜與花枝，此情誰得知。"]', '诗', 'shi', '', NULL, '菩薩蠻 十 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54967543-bf02-46b8-bd97-d49b6919ccc5', '菩薩蠻 十一', '菩薩蠻 十一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["南園滿地堆輕絮，愁聞一霎清明雨。","雨後却斜陽，杏花零落香。","無言勻睡臉，枕上屏山掩。","時節欲黃昏，無憀獨倚門。"]', '["南园满地堆轻絮，愁闻一霎清明雨。","雨後却斜陽，杏花零落香。","無言勻睡臉，枕上屏山掩。","时節欲黄昏，無憀独倚门。"]', '诗', 'shi', '', NULL, '菩薩蠻 十一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a11c4a1d-0988-4501-b592-756fa6317cd8', '菩薩蠻 十二', '菩薩蠻 十二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["夜來皓月纔當午，重簾悄悄無人語。","深處麝煙長，臥時留薄妝。","當年還自惜，往事那堪憶。","花露月明殘，錦衾知曉寒。"]', '["夜来皓月纔當午，重簾悄悄無人語。","深处麝煙长，臥时留薄妝。","當年還自惜，往事那堪憶。","花露月明殘，錦衾知晓寒。"]', '诗', 'shi', '', NULL, '菩薩蠻 十二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c158c424-8616-486f-b519-a348a703b5a6', '菩薩蠻 十三', '菩薩蠻 十三', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["雨晴夜合玲瓏日，萬枝香嫋紅絲拂。","閑夢憶金堂，滿庭萱草長。","繡簾垂{罒/彔}𦌉，眉黛遠山綠。","春水渡溪橋，凭闌魂欲消。"]', '["雨晴夜合玲瓏日，万枝香嫋紅絲拂。","闲梦憶金堂，满庭萱草长。","繡簾垂{罒/彔}𦌉，眉黛远山綠。","春水渡溪橋，凭闌魂欲消。"]', '诗', 'shi', '', NULL, '菩薩蠻 十三 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1280cd85-731d-4ca7-8f5f-6d70b862a775', '菩薩蠻 十四', '菩薩蠻 十四', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["竹風輕動庭除冷，珠簾月上玲瓏影。","山枕隱濃妝，綠檀金鳳凰。","兩蛾愁黛淺，故國吳宮遠。","春恨正關情，畫樓殘點聲。"]', '["竹风轻动庭除冷，珠簾月上玲瓏影。","山枕隐濃妝，綠檀金鳳凰。","兩蛾愁黛淺，故国吳宮远。","春恨正关情，畫楼殘点声。"]', '诗', 'shi', '', NULL, '菩薩蠻 十四 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1346cd4b-1453-4020-93fe-99d397977198', '菩薩蠻 十五', '菩薩蠻 十五', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["玉纖彈處真珠落，流多暗濕鉛華薄。","春露浥朝花，秋波浸晚霞。","風流心上物，本爲風流出。","看取薄情人，羅衣無此痕。"]', '["玉纖彈处真珠落，流多暗濕鉛华薄。","春露浥朝花，秋波浸晚霞。","风流心上物，本爲风流出。","看取薄情人，羅衣無此痕。"]', '诗', 'shi', '', NULL, '菩薩蠻 十五 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97837150-d035-4bee-90a1-704fc2f1906f', '清平樂 一', '清平乐 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["上陽春晚，宮女愁蛾淺。","新歲清平思同輦，爭奈長安路遠。","鳳帳鴛被徒熏，寂寞花瑣千門。","競把黃金買賦，爲妾將上明君。"]', '["上陽春晚，宮女愁蛾淺。","新歲清平思同輦，爭奈长安路远。","鳳帳鴛被徒熏，寂寞花瑣千门。","競把黄金買賦，爲妾將上明君。"]', '诗', 'shi', '', NULL, '清平樂 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('692f8ff9-36e0-46d9-b47e-9ddbcebfd6a8', '清平樂 二', '清平乐 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["洛陽愁絕，楊柳花飄雪。","終日行人爭攀折，橋下水流嗚咽。","上馬爭勸離觴，南浦鸎聲斷腸。","愁殺平原年少，回首揮淚千行。"]', '["洛陽愁絕，楊柳花飄雪。","終日行人爭攀折，橋下水流嗚咽。","上马爭勸離觴，南浦鸎声斷腸。","愁殺平原年少，回首揮泪千行。"]', '诗', 'shi', '', NULL, '清平樂 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b13c8eb-d23f-4587-a32f-45c6e8503c88', '更漏子 一', '更漏子 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["柳絲長，春雨細，花外漏聲迢遞。","驚塞鴈，起城烏，畫屏金鷓鴣。","香霧薄，透簾幕，惆悵謝家池閣。","紅燭背，繡簾垂，夢長君不知。"]', '["柳絲长，春雨細，花外漏声迢遞。","驚塞鴈，起城烏，畫屏金鷓鴣。","香霧薄，透簾幕，惆悵謝家池閣。","紅燭背，繡簾垂，梦长君不知。"]', '诗', 'shi', '', NULL, '更漏子 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dfde7bc-49f5-4fbd-b0c2-c089c1575cec', '更漏子 二', '更漏子 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["星斗稀，鐘鼓歇，簾外曉鸎殘月。","蘭露重，柳風斜，滿庭堆落花。","虛閣上，倚闌望，還似去年惆悵。","春欲暮，思無窮，舊歡如夢中。"]', '["星斗稀，鐘鼓歇，簾外晓鸎殘月。","蘭露重，柳风斜，满庭堆落花。","虛閣上，倚闌望，還似去年惆悵。","春欲暮，思無窮，旧歡如梦中。"]', '诗', 'shi', '', NULL, '更漏子 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e512119-eba8-4410-9cbf-e22eff3aef96', '更漏子 三', '更漏子 三', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["金雀釵，紅粉面，花裏暫時相見。","知我意，感君憐，此情須問天。","香作穗，蠟成淚，還似兩人心意。","山枕膩，錦衾寒，覺來更漏殘。"]', '["金雀釵，紅粉面，花裏暫时相见。","知我意，感君怜，此情須问天。","香作穗，蠟成泪，還似兩人心意。","山枕膩，錦衾寒，覺来更漏殘。"]', '诗', 'shi', '', NULL, '更漏子 三 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd66a36e-6a76-4fc2-afef-fda908827990', '更漏子 四', '更漏子 四', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["相見稀，相憶久，眉淺淡煙如柳。","垂翠幕，結同心，待郎熏繡衾。","城上月，白如雪，蟬鬢美人愁絕。","宮樹暗，鵲橋橫，玉籤初報明。"]', '["相见稀，相憶久，眉淺淡煙如柳。","垂翠幕，結同心，待郎熏繡衾。","城上月，白如雪，蟬鬢美人愁絕。","宮樹暗，鵲橋橫，玉籤初報明。"]', '诗', 'shi', '', NULL, '更漏子 四 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb839cc2-8338-4352-8e8a-9bb2267aec34', '更漏子 五', '更漏子 五', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["背江樓，臨海月，城上角聲嗚咽。","堤柳動，島煙昏，兩行征鴈分。","京口路，歸帆渡，正是芳菲欲度。","銀燭盡，玉繩低，一聲村落雞。"]', '["背江楼，臨海月，城上角声嗚咽。","堤柳动，島煙昏，兩行征鴈分。","京口路，归帆渡，正是芳菲欲度。","銀燭尽，玉繩低，一声村落雞。"]', '诗', 'shi', '', NULL, '更漏子 五 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('238276c5-45e7-40f9-ad7c-dd1f1dbbc334', '更漏子 六', '更漏子 六', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["玉爐香，紅蠟淚，偏照畫堂秋思。","眉翠薄，鬢雲殘，夜長衾枕寒。","梧桐樹，三更雨，不道離情正苦。","一葉葉，一聲聲，空階滴到明。"]', '["玉爐香，紅蠟泪，偏照畫堂秋思。","眉翠薄，鬢云殘，夜长衾枕寒。","梧桐樹，三更雨，不道離情正苦。","一葉葉，一声声，空階滴到明。"]', '诗', 'shi', '', NULL, '更漏子 六 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e69e38f-b892-4d36-9905-33fb2fe6c14e', '河瀆神 一', '河瀆神 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["河上望叢祠，廟前春雨來時。","楚山無限鳥飛遲，蘭櫂空傷別離。","何處杜鵑啼不歇，豔紅開盡如血。","蟬鬢美人愁絕，百花芳草佳節。"]', '["河上望叢祠，廟前春雨来时。","楚山無限鸟飞遲，蘭櫂空傷別離。","何处杜鵑啼不歇，豔紅开尽如血。","蟬鬢美人愁絕，百花芳草佳節。"]', '诗', 'shi', '', NULL, '河瀆神 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58012e00-5719-457d-b52d-bf978ec22547', '河瀆神 二', '河瀆神 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["孤廟對寒潮，西陵風雨瀟瀟。","謝娘惆悵倚蘭橈，淚流玉筯千條。","暮天愁聽思歸樂，早梅香滿山郭。","回首兩情蕭索，離魂何處飄泊。"]', '["孤廟对寒潮，西陵风雨瀟瀟。","謝娘惆悵倚蘭橈，泪流玉筯千條。","暮天愁听思归乐，早梅香满山郭。","回首兩情蕭索，離魂何处飄泊。"]', '诗', 'shi', '', NULL, '河瀆神 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a8ae2f7-d5b9-4cc6-bb6e-be9c7b44a2ab', '河瀆神 三', '河瀆神 三', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["銅鼓賽神來，滿庭幡蓋裴回。","水村江浦過風雷，楚山如畫煙開。","離別艣聲空蕭索，玉容惆悵妝薄。","青麥燕飛落落，卷簾愁對珠閣。"]', '["銅鼓賽神来，满庭幡蓋裴回。","水村江浦過风雷，楚山如畫煙开。","離別艣声空蕭索，玉容惆悵妝薄。","青麦燕飞落落，卷簾愁对珠閣。"]', '诗', 'shi', '', NULL, '河瀆神 三 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba91117a-dd0e-4455-8975-99ef02e8b843', '河傳 一', '河傳 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["江畔，相喚。","曉妝鮮，仙景箇女采蓮。","請君莫向那岸邊，少年，好花新滿船。","紅袖搖曳逐風輭，垂玉腕，腸向柳絲斷。","浦南歸，浦北歸，莫知，晚來人已稀。"]', '["江畔，相喚。","晓妝鲜，仙景箇女采蓮。","請君莫向那岸邊，少年，好花新满船。","紅袖搖曳逐风輭，垂玉腕，腸向柳絲斷。","浦南归，浦北归，莫知，晚来人已稀。"]', '诗', 'shi', '', NULL, '河傳 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59640eba-5492-4033-8a8c-86b1c43dc6da', '河傳 二', '河傳 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["湖上，閑望。","雨蕭蕭，煙浦花橋路遙。","謝娘翠蛾愁不銷，終朝，夢魂迷晚潮。","蕩子天涯歸櫂遠，春已晚，鸎語空腸斷。","若耶溪，溪水西，柳堤，不聞郎馬嘶。"]', '["湖上，闲望。","雨蕭蕭，煙浦花橋路遙。","謝娘翠蛾愁不銷，終朝，梦魂迷晚潮。","蕩子天涯归櫂远，春已晚，鸎語空腸斷。","若耶溪，溪水西，柳堤，不闻郎马嘶。"]', '诗', 'shi', '', NULL, '河傳 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b5c549d-af0b-4f05-9e78-763658c137e5', '河傳 三', '河傳 三', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["同伴，相喚。","杏花稀，夢裏每愁依違。","仙客一去燕已飛，不歸，淚痕空滿衣。","天際雲鳥引情遠，春已晚，煙靄渡南苑。","雪梅香，柳帶長，小娘，轉令人意傷。"]', '["同伴，相喚。","杏花稀，梦裏每愁依違。","仙客一去燕已飞，不归，泪痕空满衣。","天際云鸟引情远，春已晚，煙靄渡南苑。","雪梅香，柳带长，小娘，轉令人意傷。"]', '诗', 'shi', '', NULL, '河傳 三 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0874544-8b86-4a63-bbf4-cfccf26114ab', '木蘭花', '木蘭花', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["家臨長信往來道，乳燕雙雙拂煙草。","油壁車輕金犢肥，流蘇帳曉春雞早。","籠中嬌鳥暖猶睡，簾外落花閑不掃。","衰桃一樹近前池，似惜容顏鏡中老。"]', '["家臨长信往来道，乳燕雙雙拂煙草。","油壁车轻金犢肥，流蘇帳晓春雞早。","籠中嬌鸟暖猶睡，簾外落花闲不掃。","衰桃一樹近前池，似惜容顏镜中老。"]', '诗', 'shi', '', NULL, '木蘭花 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1cdb255-eda0-45b8-8b59-5894c442174a', '竹枝 一', '竹枝 一', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["檳榔花發鷓鴣啼，雄飛煙瘴雌亦飛。"]', '["檳榔花發鷓鴣啼，雄飞煙瘴雌亦飞。"]', '诗', 'shi', '', NULL, '竹枝 一 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73c6fda5-4058-45ad-b06e-ff18a10b2ec6', '竹枝 二', '竹枝 二', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["木棉花盡荔支垂，千花萬花待郎歸。"]', '["木棉花尽荔支垂，千花万花待郎归。"]', '诗', 'shi', '', NULL, '竹枝 二 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba8145c8-9eff-4780-9aa5-6e726c198f75', '竹枝 三', '竹枝 三', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["芙蓉竝蔕一心連，花侵槅子眼應穿。"]', '["芙蓉竝蔕一心連，花侵槅子眼應穿。"]', '诗', 'shi', '', NULL, '竹枝 三 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('698d2590-f28a-4943-854e-390329352e7f', '竹枝 四', '竹枝 四', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["筵中蠟燭淚珠紅，合歡桃核兩人同。"]', '["筵中蠟燭泪珠紅，合歡桃核兩人同。"]', '诗', 'shi', '', NULL, '竹枝 四 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6c142a7-3387-4665-92d9-b3630f385dbd', '竹枝 五', '竹枝 五', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["斜江風起動橫波，劈開蓮子苦心多。"]', '["斜江风起动橫波，劈开蓮子苦心多。"]', '诗', 'shi', '', NULL, '竹枝 五 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed3f9d13-10e8-47cc-a74b-b9c109247630', '竹枝 六', '竹枝 六', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["山頭桃花谷底杏，兩花窈窕遙相映。"]', '["山头桃花谷底杏，兩花窈窕遙相映。"]', '诗', 'shi', '', NULL, '竹枝 六 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad0cd96c-0d2a-4e18-98cc-86b5f5cd0e9a', '摘得新 一', '摘得新 一', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["酌一巵，須教玉笛吹。","錦筵紅蠟燭，莫來遲。","繁紅一夜經風雨，是空枝。"]', '["酌一巵，須教玉笛吹。","錦筵紅蠟燭，莫来遲。","繁紅一夜經风雨，是空枝。"]', '诗', 'shi', '', NULL, '摘得新 一 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60996354-2277-4a59-a0fd-cce8c675181f', '摘得新 二', '摘得新 二', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["摘得新，枝枝葉葉春。","管弦兼美酒，最關人。","平生都得幾十度，展香茵。"]', '["摘得新，枝枝葉葉春。","管弦兼美酒，最关人。","平生都得幾十度，展香茵。"]', '诗', 'shi', '', NULL, '摘得新 二 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08fe7156-eb95-411d-809c-51d92c029aa3', '采蓮子 一', '采蓮子 一', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["菡萏香連十頃陂，小姑貪戲采蓮遲。","晚來弄水船頭濕，更脫紅裙裹鴨兒。"]', '["菡萏香連十頃陂，小姑貪戲采蓮遲。","晚来弄水船头濕，更脫紅裙裹鴨兒。"]', '诗', 'shi', '', NULL, '采蓮子 一 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d489d9db-9571-459d-aceb-8a912abb453c', '采蓮子 二', '采蓮子 二', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["船動湖光灩灩秋，貪看年少信船流。","無端隔水拋蓮子，遙被人知半日羞。"]', '["船动湖光灩灩秋，貪看年少信船流。","無端隔水拋蓮子，遙被人知半日羞。"]', '诗', 'shi', '', NULL, '采蓮子 二 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81f23259-5fc8-488a-9523-85f7759ba8df', '拋毬樂 一', '拋毬乐 一', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["紅撥一聲飄，輕裘墜越綃。","帶翻金孔雀，香滿繡蜂腰。","少少拋分數，花枝正索饒。"]', '["紅撥一声飄，轻裘墜越綃。","带翻金孔雀，香满繡蜂腰。","少少拋分數，花枝正索饒。"]', '诗', 'shi', '', NULL, '拋毬樂 一 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8af29ea4-4586-4743-ac50-a1569721e712', '拋毬樂 二', '拋毬乐 二', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["金蹙花毬小，真珠繡帶垂。","幾回衝蠟燭，千度入香懷。","上客終須醉，觥盂且亂排。"]', '["金蹙花毬小，真珠繡带垂。","幾回衝蠟燭，千度入香懷。","上客終須醉，觥盂且亂排。"]', '诗', 'shi', '', NULL, '拋毬樂 二 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f659dbb-07e0-4ff0-bf9c-b53d5bde41fe', '憶江南 一', '憶江南 一', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["蘭燼落，屏上暗紅蕉。","閑夢江南梅熟日，夜船吹笛雨瀟瀟，人語驛邊橋。"]', '["蘭燼落，屏上暗紅蕉。","闲梦江南梅熟日，夜船吹笛雨瀟瀟，人語驛邊橋。"]', '诗', 'shi', '', NULL, '憶江南 一 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9a2319e-63d7-4f0d-8009-4f4e1e613015', '憶江南 二', '憶江南 二', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["樓上寢，殘月下簾旌。","夢見秣陵惆悵事，桃花柳絮滿江城，雙髻坐吹笙。"]', '["楼上寢，殘月下簾旌。","梦见秣陵惆悵事，桃花柳絮满江城，雙髻坐吹笙。"]', '诗', 'shi', '', NULL, '憶江南 二 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b45591f0-1efa-41b4-98c1-4c24d16a2ecf', '天仙子 一', '天仙子 一', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["晴野鷺鷥飛一隻，水葓花發秋江碧。","劉郎此日別天仙，登綺席，淚珠滴，十二晚峰青歷歷。"]', '["晴野鷺鷥飞一隻，水葓花發秋江碧。","劉郎此日別天仙，登綺席，泪珠滴，十二晚峰青歷歷。"]', '诗', 'shi', '', NULL, '天仙子 一 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('505369c9-16c4-4d03-b3c5-e60564f3f9ce', '天仙子 二', '天仙子 二', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["躑躅花開紅照水，鷓鴣飛遶青山觜。","行人經歲始歸來，千萬里，錯相倚，懊惱天仙應有以。"]', '["躑躅花开紅照水，鷓鴣飞遶青山觜。","行人經歲始归来，千万里，錯相倚，懊惱天仙應有以。"]', '诗', 'shi', '', NULL, '天仙子 二 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cedfa8ac-6f74-4a8a-bedb-7d27bb702a38', '怨回紇 一', '怨回紇 一', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["白首南朝女，愁聽異域歌。","收兵頡利國，飲馬胡盧河。","毳布腥膻久，穹廬歲月多。","雕窠城上宿，吹笛淚滂沱。"]', '["白首南朝女，愁听異域歌。","收兵頡利国，饮马胡盧河。","毳布腥膻久，穹廬歲月多。","雕窠城上宿，吹笛泪滂沱。"]', '诗', 'shi', '', NULL, '怨回紇 一 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b5cb663-1c54-4cd8-aa89-74de2c388491', '怨回紇 二', '怨回紇 二', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["祖席駐征櫂，開帆候信潮。","隔筵桃葉泣，吹管杏花飄。","船去鷗飛閣，人歸塵上橋。","別離惆悵淚，江路濕紅蕉。"]', '["祖席駐征櫂，开帆候信潮。","隔筵桃葉泣，吹管杏花飄。","船去鷗飞閣，人归塵上橋。","別離惆悵泪，江路濕紅蕉。"]', '诗', 'shi', '', NULL, '怨回紇 二 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed5a41e7-878b-4ca5-babb-5b575d05c643', '酒泉子', '酒泉子', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["買得杏花，十載歸來方始坼。","假山西畔藥闌東，滿枝紅。","旋開旋落旋成空，白髮多情人更惜。","黃昏把酒祝東風，且從容。"]', '["買得杏花，十載归来方始坼。","假山西畔藥闌东，满枝紅。","旋开旋落旋成空，白髮多情人更惜。","黄昏把酒祝东风，且從容。"]', '诗', 'shi', '', NULL, '酒泉子 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f2af012-09a6-46db-b130-907df31e785b', '生查子 一', '生查子 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["侍女動妝匳，故故驚人睡。","那知本未眠，背面偷垂淚。"]', '["侍女动妝匳，故故驚人睡。","那知本未眠，背面偷垂泪。"]', '诗', 'shi', '', NULL, '生查子 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceb48c64-76c5-4f2d-b560-bc32e30394e1', '生查子 二', '生查子 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["嬾卸鳳凰釵，羞入鴛鴦被。","時復見殘燈，和煙墜金穗。"]', '["嬾卸鳳凰釵，羞入鴛鴦被。","时复见殘灯，和煙墜金穗。"]', '诗', 'shi', '', NULL, '生查子 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d69d25c6-8b19-466a-8b96-e349dbc99fb7', '浣溪沙 一', '浣溪沙 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["攏鬢新收玉步搖，背燈初解繡裙腰，枕寒衾冷異香焦。","深院不關春寂寂，落花和雨夜迢迢，恨情殘醉却無聊。"]', '["攏鬢新收玉步搖，背灯初解繡裙腰，枕寒衾冷異香焦。","深院不关春寂寂，落花和雨夜迢迢，恨情殘醉却無聊。"]', '诗', 'shi', '', NULL, '浣溪沙 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27179e3f-b16b-4a28-98ca-7bdd076cecaf', '浣溪沙 二', '浣溪沙 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["宿醉離愁慢髻鬟，六銖衣薄惹輕寒，慵紅悶翠掩青鸞。","羅韈況兼金菡萏，雪肌仍是玉琅玕，骨香腰細更沈檀。"]', '["宿醉離愁慢髻鬟，六銖衣薄惹轻寒，慵紅悶翠掩青鸾。","羅韈況兼金菡萏，雪肌仍是玉琅玕，骨香腰細更沈檀。"]', '诗', 'shi', '', NULL, '浣溪沙 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4c7fb93-ea8c-4722-a737-0dbca1405089', '浣溪沙', '浣溪沙', 'bb3aa3f2-888f-4b5a-97da-0104e38f8deb', '唐', '["枕障熏爐隔繡帷，二年終日苦相思，杏花明月始應知。","天上人間何處去，舊歡新夢覺來時，黃昏微雨畫簾垂。"]', '["枕障熏爐隔繡帷，二年終日苦相思，杏花明月始應知。","天上人间何处去，旧歡新梦覺来时，黄昏微雨畫簾垂。"]', '诗', 'shi', '', NULL, '浣溪沙 張曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e3cdbdd-48b2-4716-a5e7-f2934bda41fe', '卜算子慢', '卜算子慢', 'ad836fae-3174-4b73-8083-c227b88b6a39', '唐', '["桃花院落，煙重露寒，寂寞禁煙晴晝。","風拂珠簾，還記去年時候，惜春心，不喜閑窗繡。","倚屏山，和衣睡覺，醺醺暗消殘酒。","獨倚危闌久，把玉筍偷彈，黛蛾輕鬬。","一點相思，萬般自家甘受，抽金釵，欲買丹青手。","寫別來，容顏寄與，使知人清瘦。"]', '["桃花院落，煙重露寒，寂寞禁煙晴晝。","风拂珠簾，還記去年时候，惜春心，不喜闲窗繡。","倚屏山，和衣睡覺，醺醺暗消殘酒。","独倚危闌久，把玉筍偷彈，黛蛾轻鬬。","一点相思，万般自家甘受，抽金釵，欲買丹青手。","寫別来，容顏寄與，使知人清瘦。"]', '诗', 'shi', '', NULL, '卜算子慢 鍾輻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29942425-f596-4d56-89b2-81637d2b2bb3', '訴衷情 一', '訴衷情 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["燭燼香殘簾半卷，夢初驚。","花欲謝，深夜，月籠明。","何處按歌聲，輕輕。","舞衣塵暗生，負春情。"]', '["燭燼香殘簾半卷，梦初驚。","花欲謝，深夜，月籠明。","何处按歌声，轻轻。","舞衣塵暗生，負春情。"]', '诗', 'shi', '', NULL, '訴衷情 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f0d6c56-de58-4992-b48d-77d5917a5ceb', '訴衷情 二', '訴衷情 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["碧沼紅芳煙雨靜，倚蘭橈。","垂玉佩，交帶，嫋纖腰。","鴛夢隔星橋，迢迢。","越羅香暗銷，墜花翹。"]', '["碧沼紅芳煙雨静，倚蘭橈。","垂玉佩，交带，嫋纖腰。","鴛梦隔星橋，迢迢。","越羅香暗銷，墜花翹。"]', '诗', 'shi', '', NULL, '訴衷情 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60a1bd30-5033-4c03-a8c8-4d91eec6b630', '天仙子 一', '天仙子 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["悵望前回夢裏期，看花不語苦尋思。","露桃宮裏小腰肢。","眉眼細，鬢雲垂，惟有多情宋玉知。"]', '["悵望前回梦裏期，看花不語苦尋思。","露桃宮裏小腰肢。","眉眼細，鬢云垂，惟有多情宋玉知。"]', '诗', 'shi', '', NULL, '天仙子 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('648900d9-6999-4909-a943-9add2ad2bcac', '天仙子 二', '天仙子 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["深夜歸來長酩酊，扶入流蘇猶未醒。","醺醺酒氣麝蘭和。","驚睡覺，笑呵呵，長笑人生能幾何。"]', '["深夜归来长酩酊，扶入流蘇猶未醒。","醺醺酒氣麝蘭和。","驚睡覺，笑呵呵，长笑人生能幾何。"]', '诗', 'shi', '', NULL, '天仙子 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0a1ccbc-8cc5-4f3c-a024-8303e3ab0bc7', '天仙子 三', '天仙子 三', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["蟾彩霜華夜不分，天外鴻聲枕上聞。","繡衾香冷嬾重熏。","人寂寂，葉紛紛，纔睡依前夢見君。"]', '["蟾彩霜华夜不分，天外鴻声枕上闻。","繡衾香冷嬾重熏。","人寂寂，葉紛紛，纔睡依前梦见君。"]', '诗', 'shi', '', NULL, '天仙子 三 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aac76176-db3b-4990-89e6-8a3230869e0d', '天仙子 四', '天仙子 四', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["夢覺雲屏依舊空，杜鵑聲咽隔簾櫳。","玉郎薄倖去無蹤。","一日日，恨重重，淚界蓮顋兩線紅。"]', '["梦覺云屏依旧空，杜鵑声咽隔簾櫳。","玉郎薄倖去無蹤。","一日日，恨重重，泪界蓮顋兩線紅。"]', '诗', 'shi', '', NULL, '天仙子 四 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('409e5539-3379-47f8-9a13-77300a699ae2', '天仙子 五', '天仙子 五', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["金似衣裳玉似身，眼如秋水鬢如雲。","霞帬月帔一羣羣。","來洞口，望煙分，劉阮不歸春日曛。"]', '["金似衣裳玉似身，眼如秋水鬢如云。","霞帬月帔一羣羣。","来洞口，望煙分，劉阮不归春日曛。"]', '诗', 'shi', '', NULL, '天仙子 五 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c390026-5dde-4d21-80f0-dd5746be495c', '江城子 一', '江城子 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["恩重嬌多情易傷，漏更長，解鴛鴦。","朱脣未動，先覺口脂香。","緩揭繡衾抽皓腕，移鳳枕，枕檀郎。"]', '["恩重嬌多情易傷，漏更长，解鴛鴦。","朱脣未动，先覺口脂香。","緩揭繡衾抽皓腕，移鳳枕，枕檀郎。"]', '诗', 'shi', '', NULL, '江城子 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f52ad30-ca30-4833-a1b4-a5752441b6ed', '江城子 二', '江城子 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["髻鬟狼藉黛眉長，出蘭房，別檀郎。","角聲嗚咽，星斗漸微茫。","露冷月殘人未起，留不住，淚千行。"]', '["髻鬟狼藉黛眉长，出蘭房，別檀郎。","角声嗚咽，星斗漸微茫。","露冷月殘人未起，留不住，泪千行。"]', '诗', 'shi', '', NULL, '江城子 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f287557f-c276-4aeb-bcd1-20533cab8bdb', '定西番 一', '定西番 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["挑盡金燈紅燼，人灼灼，漏遲遲，未眠時。","斜倚銀屏無語，閑愁上翠眉。","悶殺梧桐殘雨，滴相思。"]', '["挑尽金灯紅燼，人灼灼，漏遲遲，未眠时。","斜倚銀屏無語，闲愁上翠眉。","悶殺梧桐殘雨，滴相思。"]', '诗', 'shi', '', NULL, '定西番 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14f3ee46-1944-49a7-8ea7-9fd5d0534321', '定西番 二', '定西番 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["芳草叢生縷結，花豔豔，雨濛濛，曉庭中。","塞遠久無音問，愁銷鏡裏紅。","紫燕黃鸝猶至，恨何窮。"]', '["芳草叢生縷結，花豔豔，雨濛濛，晓庭中。","塞远久無音问，愁銷镜裏紅。","紫燕黄鸝猶至，恨何窮。"]', '诗', 'shi', '', NULL, '定西番 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e1d6b9c-aa84-4309-b105-2700ed07d9da', '思帝鄉 一', '思帝乡 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["雲髻墜，鳳釵垂。","髻墜釵垂無力，枕函欹。","翡翠屏深月落，漏依依。","說盡人間天上，兩心知。"]', '["云髻墜，鳳釵垂。","髻墜釵垂無力，枕函欹。","翡翠屏深月落，漏依依。","说尽人间天上，兩心知。"]', '诗', 'shi', '', NULL, '思帝鄉 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e995761d-3ea2-4f50-b1e6-62d2916b6244', '思帝鄉 二', '思帝乡 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["春日遊，杏花吹滿頭。","陌上誰家年少，足風流。","妾擬將身嫁與，一生休。","縱被無情棄，不能羞。"]', '["春日游，杏花吹满头。","陌上誰家年少，足风流。","妾擬將身嫁與，一生休。","縱被無情棄，不能羞。"]', '诗', 'shi', '', NULL, '思帝鄉 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f04cc740-75db-467e-a766-ad7b18c13acb', '上行杯 一', '上行杯 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["芳草灞陵春岸，柳煙深，滿樓弦管，一曲離聲腸寸斷。","今日送君千萬，紅縷玉盤金鏤盞。","須勸，珍重意，莫辭滿。"]', '["芳草灞陵春岸，柳煙深，满楼弦管，一曲離声腸寸斷。","今日送君千万，紅縷玉盤金鏤盞。","須勸，珍重意，莫辞满。"]', '诗', 'shi', '', NULL, '上行杯 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6271cce-f1d1-4d87-b001-ef3199659743', '上行杯 二', '上行杯 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["白馬玉鞭金轡，少年郎，離別容易，迢遰去程千萬里。","惆悵異鄉雲水，滿酌一杯勸和淚。","須愧，珍重意，莫辭醉。"]', '["白马玉鞭金轡，少年郎，離別容易，迢遰去程千万里。","惆悵異乡云水，满酌一杯勸和泪。","須愧，珍重意，莫辞醉。"]', '诗', 'shi', '', NULL, '上行杯 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7e043d8-a51c-4c01-8ad7-0a78cc51212f', '酒泉子', '酒泉子', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["月落星沈，樓上美人春睡。","綠雲欹，金枕膩，畫屏深。","子規啼破相思夢，曙色東方纔動。","柳煙輕，花露重，思難任。"]', '["月落星沈，楼上美人春睡。","綠云欹，金枕膩，畫屏深。","子規啼破相思梦，曙色东方纔动。","柳煙轻，花露重，思难任。"]', '诗', 'shi', '', NULL, '酒泉子 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8e58789-d4a7-4a8b-98a7-14c44b87f29e', '女冠子 一', '女冠子 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["四月十七，正是去年今日。","別君時。","忍淚佯低面，含羞半歛眉。","不知魂已斷，空有夢相隨。","除却天邊月，沒人知。"]', '["四月十七，正是去年今日。","別君时。","忍泪佯低面，含羞半歛眉。","不知魂已斷，空有梦相隨。","除却天邊月，沒人知。"]', '诗', 'shi', '', NULL, '女冠子 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df261b12-9ddf-42f6-b0b7-7f571ca32d43', '女冠子 二', '女冠子 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["昨夜夜半，枕上分明夢見。","語多時。","依舊桃花面，頻低柳葉眉。","半羞還半喜，欲去又依依。","覺來知是夢，不勝悲。"]', '["昨夜夜半，枕上分明梦见。","語多时。","依旧桃花面，頻低柳葉眉。","半羞還半喜，欲去又依依。","覺来知是梦，不勝悲。"]', '诗', 'shi', '', NULL, '女冠子 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f9bf347-2367-4cbd-b762-2b008d540ead', '浣溪沙 一', '浣溪沙 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["清曉妝成寒食天，柳毬斜嫋間花鈿，卷簾直出畫堂前。","指點牡丹初綻朵，日高猶自凭朱闌，含嚬不語恨春殘。"]', '["清晓妝成寒食天，柳毬斜嫋间花鈿，卷簾直出畫堂前。","指点牡丹初綻朵，日高猶自凭朱闌，含嚬不語恨春殘。"]', '诗', 'shi', '', NULL, '浣溪沙 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27d48bf9-2972-47a2-af8f-d5ecbdb6bb27', '浣溪沙 二', '浣溪沙 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["欲上鞦韆四體慵，擬交人送又心忪，畫堂簾幕月明風。","此夜有情誰不極，隔牆梨雪又玲瓏，玉容憔悴惹微紅。"]', '["欲上鞦韆四體慵，擬交人送又心忪，畫堂簾幕月明风。","此夜有情誰不極，隔牆梨雪又玲瓏，玉容憔悴惹微紅。"]', '诗', 'shi', '', NULL, '浣溪沙 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ccf5f82-bcb1-4419-810d-a62543d95d9a', '浣溪沙 三', '浣溪沙 三', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["惆悵夢餘山月斜，孤燈照壁背紅紗，小樓高閣謝娘家。","暗想玉容何所似，一枝春雪凍梅花，滿身香霧簇朝霞。"]', '["惆悵梦餘山月斜，孤灯照壁背紅紗，小楼高閣謝娘家。","暗想玉容何所似，一枝春雪凍梅花，满身香霧簇朝霞。"]', '诗', 'shi', '', NULL, '浣溪沙 三 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4c15d56-fee2-4bfc-bbe7-f1597c011a12', '浣溪沙 四', '浣溪沙 四', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["綠樹藏鶯鶯正啼，柳絲斜拂白銅鞮，弄珠江上草萋萋。","日暮飲歸何處客，繡鞍驄馬一聲嘶，滿身蘭麝醉如泥。"]', '["綠樹藏鶯鶯正啼，柳絲斜拂白銅鞮，弄珠江上草萋萋。","日暮饮归何处客，繡鞍驄马一声嘶，满身蘭麝醉如泥。"]', '诗', 'shi', '', NULL, '浣溪沙 四 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c09f0c10-d20a-4398-aded-2b26242c24b5', '浣溪沙 五', '浣溪沙 五', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["夜夜相思更漏殘，傷心明月凭闌干，想君思我錦衾寒。","咫尺畫堂深似海，憶來惟把舊書看，幾時攜手入長安。"]', '["夜夜相思更漏殘，傷心明月凭闌干，想君思我錦衾寒。","咫尺畫堂深似海，憶来惟把旧书看，幾时携手入长安。"]', '诗', 'shi', '', NULL, '浣溪沙 五 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f470a0cf-9d73-4333-b964-0dd3d17b87fe', '歸國遙 一', '归国遙 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["春欲暮，滿地落花紅帶雨。","惆悵玉籠鸚鵡，單棲無伴侶。","南望去程何許，問花花不語。","早晚得同歸去，恨無雙翠羽。"]', '["春欲暮，满地落花紅带雨。","惆悵玉籠鸚鵡，單棲無伴侶。","南望去程何許，问花花不語。","早晚得同归去，恨無雙翠羽。"]', '诗', 'shi', '', NULL, '歸國遙 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05f64de6-deea-407f-bc8d-d8aed979198b', '歸國遙 二', '归国遙 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["金翡翠，爲我南飛傳我意。","罨畫橋邊春水，幾年花下醉。","別後只知相愧，淚珠難遠寄。","羅幕繡幃鴛被，舊歡如夢裏。"]', '["金翡翠，爲我南飞傳我意。","罨畫橋邊春水，幾年花下醉。","別後只知相愧，泪珠难远寄。","羅幕繡幃鴛被，旧歡如梦裏。"]', '诗', 'shi', '', NULL, '歸國遙 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04b24e8a-0e53-4fc1-971f-544a78678b7d', '歸國遙 三', '归国遙 三', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["春欲晚，戲蝶遊蜂花爛熳。","日落謝家池館，柳絲金縷斷。","睡覺綠鬟風亂，畫屏雲雨散。","閑倚博山長歎，淚流霑皓腕。"]', '["春欲晚，戲蝶游蜂花爛熳。","日落謝家池館，柳絲金縷斷。","睡覺綠鬟风亂，畫屏云雨散。","闲倚博山长歎，泪流霑皓腕。"]', '诗', 'shi', '', NULL, '歸國遙 三 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('945bf525-5f20-4196-b1ed-215bd81a8359', '菩薩蠻 一', '菩薩蠻 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["紅樓別夜堪惆悵，香燈半卷流蘇帳。","殘月出門時，美人和淚辭。","琵琶金翠羽，弦上黃鶯語。","勸我早歸家，綠窗人似花。"]', '["紅楼別夜堪惆悵，香灯半卷流蘇帳。","殘月出门时，美人和泪辞。","琵琶金翠羽，弦上黄鶯語。","勸我早归家，綠窗人似花。"]', '诗', 'shi', '', NULL, '菩薩蠻 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ebbdc32-a162-4a80-a574-0f5e3d760474', '菩薩蠻 二', '菩薩蠻 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["人人盡說江南好，遊人只合江南老。","春水碧於天，畫船聽雨眠。","壚邊人似月，皓腕凝雙雪。","未老莫還鄉，還鄉須斷腸。"]', '["人人尽说江南好，游人只合江南老。","春水碧於天，畫船听雨眠。","壚邊人似月，皓腕凝雙雪。","未老莫還乡，還乡須斷腸。"]', '诗', 'shi', '', NULL, '菩薩蠻 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2bacaeb-1887-47d7-af57-7290792457e1', '菩薩蠻 三', '菩薩蠻 三', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["如今却憶江南樂，當時年少春衫薄。","騎馬倚斜橋，滿樓紅袖招。","翠屏金屈曲，醉入花叢宿。","此度見花枝，白頭誓不歸。"]', '["如今却憶江南乐，當时年少春衫薄。","騎马倚斜橋，满楼紅袖招。","翠屏金屈曲，醉入花叢宿。","此度见花枝，白头誓不归。"]', '诗', 'shi', '', NULL, '菩薩蠻 三 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41ed887c-70da-4087-825a-17237e55d36e', '菩薩蠻 四', '菩薩蠻 四', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["勸君今夜須沈醉，尊前莫話明朝事。","珍重主人心，酒深情亦深。","須愁春漏短，莫訴金杯滿。","遇酒且呵呵，人生能幾何。"]', '["勸君今夜須沈醉，尊前莫話明朝事。","珍重主人心，酒深情亦深。","須愁春漏短，莫訴金杯满。","遇酒且呵呵，人生能幾何。"]', '诗', 'shi', '', NULL, '菩薩蠻 四 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf8c2e39-5d2a-44de-a03e-342d5dfde5bb', '菩薩蠻 五', '菩薩蠻 五', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["洛陽城裏春光好，洛陽才子他鄉老。","柳暗魏王堤，此時心轉迷。","桃花春水淥，水上鴛鴦浴。","凝恨對殘暉，憶君君不知。"]', '["洛陽城裏春光好，洛陽才子他乡老。","柳暗魏王堤，此时心轉迷。","桃花春水淥，水上鴛鴦浴。","凝恨对殘暉，憶君君不知。"]', '诗', 'shi', '', NULL, '菩薩蠻 五 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c50941b-6279-4578-8856-a78d4979b186', '更漏子', '更漏子', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["鐘鼓寒，樓閣暝，月照古桐金井。","深院閉，小庭空，落花香露紅。","煙柳重，春霧薄，燈背水窗高閣。","閑倚戶，暗霑衣，待郎郎不歸。"]', '["鐘鼓寒，楼閣暝，月照古桐金井。","深院閉，小庭空，落花香露紅。","煙柳重，春霧薄，灯背水窗高閣。","闲倚戶，暗霑衣，待郎郎不归。"]', '诗', 'shi', '', NULL, '更漏子 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e37e4e0d-877d-4a64-942b-ff4a09b5f1dc', '謁金門 一', '謁金门 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["春雨足，染就一溪新綠。","柳外飛來雙羽玉，弄晴相對浴。","樓外翠簾高軸，倚遍闌干幾曲。","雲淡水平煙樹簇，寸心千里目。"]', '["春雨足，染就一溪新綠。","柳外飞来雙羽玉，弄晴相对浴。","楼外翠簾高軸，倚遍闌干幾曲。","云淡水平煙樹簇，寸心千里目。"]', '诗', 'shi', '', NULL, '謁金門 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dd0d319-9822-44f2-961e-48bb8b5ba9e0', '謁金門 二', '謁金门 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["春漏促，金燼暗挑殘燭。","一夜簾前風撼竹，夢魂相斷續。","有箇嬌饒如玉，夜夜繡屏孤宿。","閑抱琵琶尋舊曲，遠山眉黛綠。"]', '["春漏促，金燼暗挑殘燭。","一夜簾前风撼竹，梦魂相斷續。","有箇嬌饒如玉，夜夜繡屏孤宿。","闲抱琵琶尋旧曲，远山眉黛綠。"]', '诗', 'shi', '', NULL, '謁金門 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8bda54b-7a15-4aaa-9499-f6fa2bf05ad6', '謁金門 三', '謁金门 三', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["空相憶，無記得傳消息。","天上嫦娥人不識，寄書何處覓。","新睡覺來無力，不忍把君書跡。","滿院落花春寂寂，斷腸芳草碧。"]', '["空相憶，無記得傳消息。","天上嫦娥人不識，寄书何处覓。","新睡覺来無力，不忍把君书跡。","满院落花春寂寂，斷腸芳草碧。"]', '诗', 'shi', '', NULL, '謁金門 三 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e2402f5-f813-40e4-9f86-dbf38f616036', '清平樂 一', '清平乐 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["春愁南陌，故國音書隔。","細雨霏霏梨花白，燕拂畫簾金額。","盡日相望王孫，塵滿衣上淚痕。","誰向橋邊吹笛，駐馬西望銷魂。"]', '["春愁南陌，故国音书隔。","細雨霏霏梨花白，燕拂畫簾金額。","尽日相望王孫，塵满衣上泪痕。","誰向橋邊吹笛，駐马西望銷魂。"]', '诗', 'shi', '', NULL, '清平樂 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c076f044-0efb-4ae8-9a9a-3c47a5c15a35', '清平樂 二', '清平乐 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["野花芳草，寂寞關山道。","柳吐金絲鶯語早，惆悵香閨暗老。","羅帶悔結同心，獨凭朱闌思深。","夢覺半牀斜月，小窗風觸鳴琴。"]', '["野花芳草，寂寞关山道。","柳吐金絲鶯語早，惆悵香閨暗老。","羅带悔結同心，独凭朱闌思深。","梦覺半牀斜月，小窗风觸鳴琴。"]', '诗', 'shi', '', NULL, '清平樂 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81b97e4e-af85-4bcd-a594-11e7f6a5c9a8', '清平樂 三', '清平乐 三', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["何處遊女，蜀國多雲雨。","雲解有情花解語，窣地繡羅金縷。","妝成不整金鈿，含羞待月鞦韆。","住在綠槐陰裏，門臨春水橋邊。"]', '["何处游女，蜀国多云雨。","云解有情花解語，窣地繡羅金縷。","妝成不整金鈿，含羞待月鞦韆。","住在綠槐陰裏，门臨春水橋邊。"]', '诗', 'shi', '', NULL, '清平樂 三 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f2bcc99-5451-437b-bb0b-043bac45ffee', '清平樂 四', '清平乐 四', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["鶯啼殘月，繡閣香燈滅。","門外馬嘶郎欲別，正是落花時節。","妝成不畫蛾眉，含愁獨倚金扉。","去路香塵莫掃，掃即郎去歸遲。"]', '["鶯啼殘月，繡閣香灯滅。","门外马嘶郎欲別，正是落花时節。","妝成不畫蛾眉，含愁独倚金扉。","去路香塵莫掃，掃即郎去归遲。"]', '诗', 'shi', '', NULL, '清平樂 四 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f17969b6-0bc4-4f85-9748-9473a24611b4', '清平樂 五', '清平乐 五', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["瑣窗春暮，滿地梨花雨。","君不歸來情又去，紅淚散霑金縷。","夢魂飛斷煙波，傷心不奈春何。","空把金針獨坐，鴛鴦愁繡雙窠。"]', '["瑣窗春暮，满地梨花雨。","君不归来情又去，紅泪散霑金縷。","梦魂飞斷煙波，傷心不奈春何。","空把金針独坐，鴛鴦愁繡雙窠。"]', '诗', 'shi', '', NULL, '清平樂 五 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2859d179-5e3c-4f0f-864a-e1fc4a0a50ea', '清平樂 六', '清平乐 六', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["綠楊春雨，金線飄千縷。","花拆香枝黃鸝語，玉勒雕鞍何處。","碧窗望斷燕鴻，翠簾睡眼溟濛。","寶瑟誰家彈罷，含悲斜倚屏風。"]', '["綠楊春雨，金線飄千縷。","花拆香枝黄鸝語，玉勒雕鞍何处。","碧窗望斷燕鴻，翠簾睡眼溟濛。","寶瑟誰家彈罷，含悲斜倚屏风。"]', '诗', 'shi', '', NULL, '清平樂 六 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('576d3866-0cdd-47c3-b984-b4187626504d', '喜遷鶯 一', '喜遷鶯 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["人洶洶，鼓𪔜𪔜，襟袖五更風。","大羅天上月朦朧，騎馬上虛空。","香滿衣，雲滿路，鸞鳳遶身飛舞。","霓旌絳節一羣羣，引見玉華君。"]', '["人洶洶，鼓𪔜𪔜，襟袖五更风。","大羅天上月朦朧，騎马上虛空。","香满衣，云满路，鸾鳳遶身飞舞。","霓旌絳節一羣羣，引见玉华君。"]', '诗', 'shi', '', NULL, '喜遷鶯 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce339bc5-b84f-47ff-baf2-23547c59aee0', '喜遷鶯 二', '喜遷鶯 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["街鼓動，禁城開，天上探人回。","鳳銜金牓出雲來，平地一聲雷。","鶯已遷，龍已化，一夜滿城車馬。","家家樓上簇神仙，爭看鶴沖天。"]', '["街鼓动，禁城开，天上探人回。","鳳銜金牓出云来，平地一声雷。","鶯已遷，龙已化，一夜满城车马。","家家楼上簇神仙，爭看鹤沖天。"]', '诗', 'shi', '', NULL, '喜遷鶯 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8771b7e-31ed-43e0-95b8-8de053a25b5c', '應天長 一', '應天长 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["綠槐陰裏黃鶯語，深院無人春晝午。","畫簾垂，金鳳舞，寂寞繡屏香一炷。","碧天雲，無定處。","空有夢魂來去，夜夜綠窗風雨，斷腸君信否。"]', '["綠槐陰裏黄鶯語，深院無人春晝午。","畫簾垂，金鳳舞，寂寞繡屏香一炷。","碧天云，無定处。","空有梦魂来去，夜夜綠窗风雨，斷腸君信否。"]', '诗', 'shi', '', NULL, '應天長 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef64ed93-a515-4994-880e-8f40af963dc2', '應天長 二', '應天长 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["別來半歲音書絕，一寸離腸千萬結。","難相見，易相別，又是玉樓花似雪。","暗相思，無處說。","惆悵夜來煙月，想得此時情切，淚霑紅袖黦。"]', '["別来半歲音书絕，一寸離腸千万結。","难相见，易相別，又是玉楼花似雪。","暗相思，無处说。","惆悵夜来煙月，想得此时情切，泪霑紅袖黦。"]', '诗', 'shi', '', NULL, '應天長 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f53a2bf4-c829-44ba-8c81-8693863afda6', '荷葉杯 一', '荷葉杯 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["絕代佳人難得，傾國，花下見無期。","一雙愁黛遠山眉，不忍更思惟。","閑掩翠屏金鳳，殘夢，羅幕畫堂空。","碧天無路信難通，惆悵舊房櫳。"]', '["絕代佳人难得，傾国，花下见無期。","一雙愁黛远山眉，不忍更思惟。","闲掩翠屏金鳳，殘梦，羅幕畫堂空。","碧天無路信难通，惆悵旧房櫳。"]', '诗', 'shi', '', NULL, '荷葉杯 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd5fe2ff-1cf1-4fac-bfcd-43e84b648303', '荷葉杯 二', '荷葉杯 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["記得那年花下，深夜，初識謝娘時。","水堂西面畫簾垂，攜手暗相期。","惆悵曉鶯殘月，相別，從此隔音塵。","如今俱是異鄉人，相見更無因。"]', '["記得那年花下，深夜，初識謝娘时。","水堂西面畫簾垂，携手暗相期。","惆悵晓鶯殘月，相別，從此隔音塵。","如今俱是異乡人，相见更無因。"]', '诗', 'shi', '', NULL, '荷葉杯 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a627e058-f359-400d-b882-1956d7553b52', '河傳 一', '河傳 一', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["何處，煙雨。","隋堤春暮，柳色蔥蘢。","畫橈金縷，翠旗高颭香風，水光融。","青娥殿脚春妝媚，輕雲裏，綽約司花妓。","江都宮闕，清淮月映迷樓，古今愁。"]', '["何处，煙雨。","隋堤春暮，柳色蔥蘢。","畫橈金縷，翠旗高颭香风，水光融。","青娥殿脚春妝媚，轻云裏，綽約司花妓。","江都宮闕，清淮月映迷楼，古今愁。"]', '诗', 'shi', '', NULL, '河傳 一 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5de4d457-4cd6-4892-b9b4-c174300d84fd', '河傳 二', '河傳 二', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["春晚，風暖。","錦城花滿，狂殺遊人。","玉鞭金勒尋勝，馳驟輕塵，惜良辰。","翠蛾爭勸臨邛酒，纖纖手，拂面垂絲柳。","歸時煙裏鐘鼓，正是黃昏，暗銷魂。"]', '["春晚，风暖。","錦城花满，狂殺游人。","玉鞭金勒尋勝，驰驟轻塵，惜良辰。","翠蛾爭勸臨邛酒，纖纖手，拂面垂絲柳。","归时煙裏鐘鼓，正是黄昏，暗銷魂。"]', '诗', 'shi', '', NULL, '河傳 二 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72e9adc5-9268-4f69-a46e-6a5677f23b1e', '河傳 三', '河傳 三', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["錦浦，春女。","繡衣金縷，霧薄雲輕。","花深柳暗，時節正是清明，雨初晴。","玉鞭魂斷煙霞路，鶯鶯語，一望巫山雨。","香塵隱映，遙望翠檻紅樓，黛眉愁。"]', '["錦浦，春女。","繡衣金縷，霧薄云轻。","花深柳暗，时節正是清明，雨初晴。","玉鞭魂斷煙霞路，鶯鶯語，一望巫山雨。","香塵隐映，遙望翠檻紅楼，黛眉愁。"]', '诗', 'shi', '', NULL, '河傳 三 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f983e804-e0fb-4bfb-93c4-3aa96b99951a', '怨王孫', '怨王孫', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["錦里，蠶市。","滿街珠翠，千萬紅妝。","玉蟬金雀，寶髻花簇鳴璫，繡衣長。","日斜歸去人難見，青樓遠，隊隊行雲散。","不知今夜，何處深鎖蘭房，隔仙鄉。"]', '["錦里，蠶市。","满街珠翠，千万紅妝。","玉蟬金雀，寶髻花簇鳴璫，繡衣长。","日斜归去人难见，青楼远，隊隊行云散。","不知今夜，何处深鎖蘭房，隔仙乡。"]', '诗', 'shi', '', NULL, '怨王孫 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43a3024c-bc2d-40ef-99ee-69c92029ff94', '木蘭花', '木蘭花', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["獨上小樓春欲暮，愁望玉關芳草路。","消息斷，不逢人，却歛細眉歸繡戶。","坐看落花空歎息，羅袂溼班紅淚滴。"]', '["独上小楼春欲暮，愁望玉关芳草路。","消息斷，不逢人，却歛細眉归繡戶。","坐看落花空歎息，羅袂溼班紅泪滴。"]', '诗', 'shi', '', NULL, '木蘭花 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16f4e1bd-d34d-41bf-8ee8-18f9eb86abd0', '小重山', '小重山', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["一閉昭陽春又春，夜寒宮漏永，夢君恩。","臥思陳事暗消魂，羅衣濕，紅袂有啼痕。","歌吹隔重閽，遶庭芳草綠，倚長門。","萬般惆悵向誰論，凝情立，宮殿欲黃昏。"]', '["一閉昭陽春又春，夜寒宮漏永，梦君恩。","臥思陳事暗消魂，羅衣濕，紅袂有啼痕。","歌吹隔重閽，遶庭芳草綠，倚长门。","万般惆悵向誰論，凝情立，宮殿欲黄昏。"]', '诗', 'shi', '', NULL, '小重山 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6335c7b-0752-416f-b144-04bf07c94a7a', '望遠行', '望远行', '1d129c74-b6d8-4c32-b989-99d9f979c2fb', '唐', '["欲別無言倚畫屏，含恨暗傷情。","謝家庭樹錦雞鳴，殘月落邊城。","人欲別，馬頻嘶，綠槐千里長堤。","出門芳草路萋萋，雲雨別來易東西。","不忍別君後，却入舊香閨。"]', '["欲別無言倚畫屏，含恨暗傷情。","謝家庭樹錦雞鳴，殘月落邊城。","人欲別，马頻嘶，綠槐千里长堤。","出门芳草路萋萋，云雨別来易东西。","不忍別君後，却入旧香閨。"]', '诗', 'shi', '', NULL, '望遠行 韋莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83ae33fd-c0bf-435b-8aa7-40a68032c1bb', '憶江南 一', '憶江南 一', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["銜泥燕，飛到畫堂前。","占得杏梁安穩處，體輕惟有主人憐，堪羨好因緣。"]', '["銜泥燕，飞到畫堂前。","占得杏梁安穩处，體轻惟有主人怜，堪羨好因緣。"]', '诗', 'shi', '', NULL, '憶江南 一 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d619d441-4db4-4b8b-bd04-2c0d25ca1f5d', '憶江南 二', '憶江南 二', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["紅繡被，兩兩間鴛鴦。","不是鳥中偏愛爾，爲緣交頸睡南塘，全勝薄情郎。"]', '["紅繡被，兩兩间鴛鴦。","不是鸟中偏愛爾，爲緣交頸睡南塘，全勝薄情郎。"]', '诗', 'shi', '', NULL, '憶江南 二 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10c6a4e6-090c-4e6f-91aa-5bf00c51e3d1', '西溪子', '西溪子', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["捍撥雙盤金鳳，蟬鬢玉釵搖動。","畫堂前，人不語，弦解語。","彈到昭君怨處，翠蛾愁，不擡頭。"]', '["捍撥雙盤金鳳，蟬鬢玉釵搖动。","畫堂前，人不語，弦解語。","彈到昭君怨处，翠蛾愁，不擡头。"]', '诗', 'shi', '', NULL, '西溪子 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('928e25d3-5590-45f9-9438-6e43f6ad912e', '江城子 一', '江城子 一', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["鵁鶄飛起郡城東，碧江空，半灘風。","越王宮殿，蘋葉藕花中。","簾卷水樓魚浪起，千片雪，雨濛濛。"]', '["鵁鶄飞起郡城东，碧江空，半灘风。","越王宮殿，蘋葉藕花中。","簾卷水楼鱼浪起，千片雪，雨濛濛。"]', '诗', 'shi', '', NULL, '江城子 一 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('970288bc-72e8-4562-886f-742df1e9f7c1', '江城子 二', '江城子 二', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["極浦煙消水鳥飛，離筵分手時，送金巵。","渡口楊花，狂雪任風吹。","日暮空江波浪急，芳草岸，柳如絲。"]', '["極浦煙消水鸟飞，離筵分手时，送金巵。","渡口楊花，狂雪任风吹。","日暮空江波浪急，芳草岸，柳如絲。"]', '诗', 'shi', '', NULL, '江城子 二 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b9ae734-4332-45a6-8597-09215dc98ea2', '定西番', '定西番', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["紫塞月明千里，金甲冷，戍樓寒，夢長安。","鄉思望中天闊，漏殘星亦殘。","畫角數聲嗚咽，雪漫漫。"]', '["紫塞月明千里，金甲冷，戍楼寒，梦长安。","乡思望中天闊，漏殘星亦殘。","畫角數声嗚咽，雪漫漫。"]', '诗', 'shi', '', NULL, '定西番 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58fd3c08-9571-47c0-bad1-78410254b711', '望江怨', '望江怨', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["東風急，惜別花時手頻執。","羅幃愁獨入，馬嘶殘雨春蕪溼。","倚門立，寄語薄情郎，粉香和淚泣。"]', '["东风急，惜別花时手頻執。","羅幃愁独入，马嘶殘雨春蕪溼。","倚门立，寄語薄情郎，粉香和泪泣。"]', '诗', 'shi', '', NULL, '望江怨 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc496acd-cf60-425e-977a-6cd5890bc7bc', '女冠子 一', '女冠子 一', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["綠雲高髻，點翠勻紅時世。","月如眉，淺笑含雙靨，低聲唱小詞。","眼看惟恐化，魂蕩欲相隨。","玉趾回嬌步，約佳期。"]', '["綠云高髻，点翠勻紅时世。","月如眉，淺笑含雙靨，低声唱小词。","眼看惟恐化，魂蕩欲相隨。","玉趾回嬌步，約佳期。"]', '诗', 'shi', '', NULL, '女冠子 一 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3e8a854-a2c6-4d14-8419-84833fefc300', '女冠子 二', '女冠子 二', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["錦江煙水，卓女燒春濃美。","小檀霞，繡帶芙蓉帳，金釵芍藥花。","額黃侵膩髮，臂釧透紅紗。","柳暗鶯啼處，認郎家。"]', '["錦江煙水，卓女燒春濃美。","小檀霞，繡带芙蓉帳，金釵芍藥花。","額黄侵膩髮，臂釧透紅紗。","柳暗鶯啼处，認郎家。"]', '诗', 'shi', '', NULL, '女冠子 二 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8688116-8a79-4f55-b891-57e0a2ab539c', '女冠子 三', '女冠子 三', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["星冠霞帔，住在蘂珠宮裏。","佩丁當，明翠搖蟬翼，纖珪理宿妝。","醮壇春[草]晝綠，藥院杏花香。","青鳥傳心事，寄劉郎。"]', '["星冠霞帔，住在蘂珠宮裏。","佩丁當，明翠搖蟬翼，纖珪理宿妝。","醮壇春[草]晝綠，藥院杏花香。","青鸟傳心事，寄劉郎。"]', '诗', 'shi', '', NULL, '女冠子 三 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8883ccb-4c65-4edf-b701-2f4475fff026', '女冠子 四', '女冠子 四', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["雙飛雙舞，春晝後園鶯語。","卷羅幃，錦字書封了，銀河雁過遲。","鴛鴦排寶帳，豆蔻繡連枝。","不語勻珠淚，落花時。"]', '["雙飞雙舞，春晝後园鶯語。","卷羅幃，錦字书封了，銀河雁過遲。","鴛鴦排寶帳，豆蔻繡連枝。","不語勻珠泪，落花时。"]', '诗', 'shi', '', NULL, '女冠子 四 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e8faa58-047a-41e4-b7ea-c7ffd5756dab', '酒泉子', '酒泉子', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["記得去年，煙暖杏園花正發，雪飄香。","江草綠，柳絲長。","鈿車纖手卷簾望，眉學春山樣。","鳳釵低嫋翠鬟上，落梅妝。"]', '["記得去年，煙暖杏园花正發，雪飄香。","江草綠，柳絲长。","鈿车纖手卷簾望，眉学春山樣。","鳳釵低嫋翠鬟上，落梅妝。"]', '诗', 'shi', '', NULL, '酒泉子 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce8e3f43-0b34-4613-9bb7-cf85071a188b', '菩薩蠻 一', '菩薩蠻 一', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["舞帬香暖金泥鳳，畫梁語燕驚殘夢。","門外柳花飛，玉郎猶未歸。","愁勻紅粉淚，眉翦春山翠。","何處是遼陽，錦屏春晝長。"]', '["舞帬香暖金泥鳳，畫梁語燕驚殘梦。","门外柳花飞，玉郎猶未归。","愁勻紅粉泪，眉翦春山翠。","何处是遼陽，錦屏春晝长。"]', '诗', 'shi', '', NULL, '菩薩蠻 一 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ab37595-767b-4924-902f-5f962bbef068', '菩薩蠻 二', '菩薩蠻 二', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["柳花飛處鶯聲急，晴街春色香車立。","金鳳小簾開，臉波和恨來。","今宵求夢想，難到青樓上。","贏得一場愁，鴛衾誰竝頭。"]', '["柳花飞处鶯声急，晴街春色香车立。","金鳳小簾开，臉波和恨来。","今宵求梦想，难到青楼上。","贏得一場愁，鴛衾誰竝头。"]', '诗', 'shi', '', NULL, '菩薩蠻 二 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('408bd8a3-b987-4b88-ba8b-27b7c55a8d39', '菩薩蠻 三', '菩薩蠻 三', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["玉釵風動春幡急，交枝紅杏籠煙泣。","樓上望卿卿，窗寒新雨晴。","熏爐蒙翠被，繡帳鴛鴦睡。","何處有相知，羨他初畫眉。"]', '["玉釵风动春幡急，交枝紅杏籠煙泣。","楼上望卿卿，窗寒新雨晴。","熏爐蒙翠被，繡帳鴛鴦睡。","何处有相知，羨他初畫眉。"]', '诗', 'shi', '', NULL, '菩薩蠻 三 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd8c6f79-c324-446b-8fab-63a4a36b3eaa', '菩薩蠻 四', '菩薩蠻 四', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["畫屏重疊巫陽翠，楚神尚有行雲意。","朝暮幾般心，向他情謾深。","風流今古隔，虛作瞿塘客。","山月照山花，夢回燈影斜。"]', '["畫屏重叠巫陽翠，楚神尚有行云意。","朝暮幾般心，向他情謾深。","风流今古隔，虛作瞿塘客。","山月照山花，梦回灯影斜。"]', '诗', 'shi', '', NULL, '菩薩蠻 四 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1383a58-f130-4560-872f-16975ba2be0b', '菩薩蠻 五', '菩薩蠻 五', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["風簾燕舞鶯啼柳，妝臺約鬢低纖手。","釵重髻盤珊，一枝紅牡丹。","門前行樂客，白馬嘶春色。","故故墜金鞭，回頭應眼穿。"]', '["风簾燕舞鶯啼柳，妝台約鬢低纖手。","釵重髻盤珊，一枝紅牡丹。","门前行乐客，白马嘶春色。","故故墜金鞭，回头應眼穿。"]', '诗', 'shi', '', NULL, '菩薩蠻 五 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9736d5ab-5e6a-4145-b9f5-812346504b2b', '菩薩蠻 六', '菩薩蠻 六', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["綠雲鬢上飛金雀，愁眉歛翠春煙薄。","香閣掩芙蓉，畫屏山幾重。","窗寒天欲曙，猶結同心苣。","啼粉涴羅衣，問郎何日歸。"]', '["綠云鬢上飞金雀，愁眉歛翠春煙薄。","香閣掩芙蓉，畫屏山幾重。","窗寒天欲曙，猶結同心苣。","啼粉涴羅衣，问郎何日归。"]', '诗', 'shi', '', NULL, '菩薩蠻 六 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca98eb76-6e78-4be7-8c2a-f7aa5120807c', '菩薩蠻 七', '菩薩蠻 七', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["玉爐冰簟鴛鴦錦，粉融香汗流山枕。","簾外轆轤聲，歛眉含笑驚。","柳陰煙漠漠，低鬢蟬釵落。","須作一生拌，盡君今日歡。"]', '["玉爐冰簟鴛鴦錦，粉融香汗流山枕。","簾外轆轤声，歛眉含笑驚。","柳陰煙漠漠，低鬢蟬釵落。","須作一生拌，尽君今日歡。"]', '诗', 'shi', '', NULL, '菩薩蠻 七 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42537e91-a63a-4a7d-9a88-984ed29cebfe', '更漏子 一', '更漏子 一', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["星漸稀，漏頻轉，何處輪臺聲怨？","香閣掩，杏花紅，月明楊柳風。","挑錦字，記情事，惟願兩心相似。","收淚語，背燈眠，玉釵橫枕邊。"]', '["星漸稀，漏頻轉，何处輪台声怨？","香閣掩，杏花紅，月明楊柳风。","挑錦字，記情事，惟願兩心相似。","收泪語，背灯眠，玉釵橫枕邊。"]', '诗', 'shi', '', NULL, '更漏子 一 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70e96b97-0ab9-4e42-9066-c09e9c22062b', '更漏子 二', '更漏子 二', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["春夜闌，更漏促，金燼暗挑殘燭。","驚夢斷，錦屏深，兩鄉明月心。","閨草碧，望歸客，還是不知消息。","孤負我，悔憐君，告天天不聞。"]', '["春夜闌，更漏促，金燼暗挑殘燭。","驚梦斷，錦屏深，兩乡明月心。","閨草碧，望归客，還是不知消息。","孤負我，悔怜君，告天天不闻。"]', '诗', 'shi', '', NULL, '更漏子 二 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('163ba0fa-887c-439b-99a0-fd0eb8b88a7b', '更漏子 三', '更漏子 三', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["南浦情，紅粉淚，爭奈兩人深意。","低翠黛，卷征衣，馬嘶霜葉飛。","招手別，寸腸結，還是去年時節。","書託鴈，夢歸家，覺來江月斜。"]', '["南浦情，紅粉泪，爭奈兩人深意。","低翠黛，卷征衣，马嘶霜葉飞。","招手別，寸腸結，還是去年时節。","书託鴈，梦归家，覺来江月斜。"]', '诗', 'shi', '', NULL, '更漏子 三 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6542e176-1eda-46ad-b194-766687bf07a2', '感恩多 一', '感恩多 一', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["兩條紅粉淚，多少香閨意。","彊攀桃李枝，歛愁眉。","陌上鶯啼蝶舞，柳花飛。","柳花飛，願得郎心，憶家還早歸。"]', '["兩條紅粉泪，多少香閨意。","彊攀桃李枝，歛愁眉。","陌上鶯啼蝶舞，柳花飞。","柳花飞，願得郎心，憶家還早归。"]', '诗', 'shi', '', NULL, '感恩多 一 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9baccb8-a483-4afe-b770-2afc73061001', '感恩多 二', '感恩多 二', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["自從南浦別，愁見丁香結。","近來情轉深，憶鴛衾。","幾度將書託煙雁，淚盈襟。","淚盈襟，禮月求天，願君知我心。"]', '["自從南浦別，愁见丁香結。","近来情轉深，憶鴛衾。","幾度將书託煙雁，泪盈襟。","泪盈襟，禮月求天，願君知我心。"]', '诗', 'shi', '', NULL, '感恩多 二 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28fe9c16-8842-4526-b672-5d2bc076f184', '應天長 一', '應天长 一', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["玉樓春望晴煙滅，舞衫斜卷金條脫。","黃鸝嬌轉聲初歇，杏花飄盡龍山雪。","鳳釵低赴節，筵上王孫愁絕。","鴛鴦對銜羅結，兩情深夜月。"]', '["玉楼春望晴煙滅，舞衫斜卷金條脫。","黄鸝嬌轉声初歇，杏花飄尽龙山雪。","鳳釵低赴節，筵上王孫愁絕。","鴛鴦对銜羅結，兩情深夜月。"]', '诗', 'shi', '', NULL, '應天長 一 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5077b7b5-aff5-4943-9c5d-54e2cfe7b04f', '應天長 二', '應天长 二', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["雙眉澹薄藏心事，清夜背燈嬌又醉。","玉釵橫，山枕膩，寶帳鴛鴦春睡美。","別經時，無限意，虛道相思憔悴。","莫信綵箋書裏，賺人腸斷字。"]', '["雙眉澹薄藏心事，清夜背灯嬌又醉。","玉釵橫，山枕膩，寶帳鴛鴦春睡美。","別經时，無限意，虛道相思憔悴。","莫信綵箋书裏，賺人腸斷字。"]', '诗', 'shi', '', NULL, '應天長 二 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dc0e15b-99fb-4b43-9d68-748973e5b3cf', '木蘭花', '木蘭花', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["春入橫塘搖淺浪，花落小園空惆悵。","此情誰信爲狂夫，恨翠愁紅流枕上。","小玉窗前嗔燕語，紅淚滴穿金線縷。","雁歸不見報郎歸，織成錦字封過與。"]', '["春入橫塘搖淺浪，花落小园空惆悵。","此情誰信爲狂夫，恨翠愁紅流枕上。","小玉窗前嗔燕語，紅泪滴穿金線縷。","雁归不见報郎归，织成錦字封過與。"]', '诗', 'shi', '', NULL, '木蘭花 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14278baf-d668-4f66-bb4d-24fedb2cb0b3', '西溪子', '西溪子', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["昨夜西溪遊賞，芳樹奇花千樣。","鎖春光，金尊滿，聽弦管，嬌妓舞衫香暖。","不覺到斜暉，馬馱歸。"]', '["昨夜西溪游賞，芳樹奇花千樣。","鎖春光，金尊满，听弦管，嬌妓舞衫香暖。","不覺到斜暉，马馱归。"]', '诗', 'shi', '', NULL, '西溪子 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf186ac2-650d-456c-9bb1-a36a20f856b0', '何滿子', '何满子', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["紅粉樓前月照，碧紗窗外鶯啼。","夢斷遼陽音信，那堪獨守空閨。","恨對百花時節，王孫綠草萋萋。"]', '["紅粉楼前月照，碧紗窗外鶯啼。","梦斷遼陽音信，那堪独守空閨。","恨对百花时節，王孫綠草萋萋。"]', '诗', 'shi', '', NULL, '何滿子 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9062fca-80cc-4502-8c34-895e76254acc', '訴衷情 一', '訴衷情 一', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["桃花流水漾縱橫，春晝彩霞明。","劉郎去，阮郎行，惆悵恨難平。","愁坐對雲屏，筭歸程。","何時攜手洞邊迎，訴衷情。"]', '["桃花流水漾縱橫，春晝彩霞明。","劉郎去，阮郎行，惆悵恨难平。","愁坐对云屏，筭归程。","何时携手洞邊迎，訴衷情。"]', '诗', 'shi', '', NULL, '訴衷情 一 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fda6ff9e-3e61-4fb1-a7d5-4049df22cbb8', '訴衷情 二', '訴衷情 二', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["鴛鴦交頸繡衣輕，碧沼藕花馨。","偎藻荇，映蘭汀，和雨浴浮萍。","思婦對心驚，想邊庭。","何時解佩掩雲屏，訴衷情。"]', '["鴛鴦交頸繡衣轻，碧沼藕花馨。","偎藻荇，映蘭汀，和雨浴浮萍。","思婦对心驚，想邊庭。","何时解佩掩云屏，訴衷情。"]', '诗', 'shi', '', NULL, '訴衷情 二 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f6984d9-50a0-4932-be6f-de39922b55c7', '中興樂', '中兴乐', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["豆蔻花繁煙豔深，丁香輭結同心。","翠鬟女，相與，共淘金。","紅蕉葉裏猩猩語，鴛鴦浦。","鏡中鸞舞，絲雨，隔荔枝陰。"]', '["豆蔻花繁煙豔深，丁香輭結同心。","翠鬟女，相與，共淘金。","紅蕉葉裏猩猩語，鴛鴦浦。","镜中鸾舞，絲雨，隔荔枝陰。"]', '诗', 'shi', '', NULL, '中興樂 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df5cc165-e84c-4264-be9f-0c448b52acbd', '醉花間 一', '醉花间 一', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["休相問，怕相問，相問還添恨。","春水滿塘生，鸂鶒還相趂。","昨夜雨霏霏，臨明寒一陣。","偏憶戍樓人，久絕邊庭信。"]', '["休相问，怕相问，相问還添恨。","春水满塘生，鸂鶒還相趂。","昨夜雨霏霏，臨明寒一陣。","偏憶戍楼人，久絕邊庭信。"]', '诗', 'shi', '', NULL, '醉花間 一 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e33f186-98a8-4265-a778-5f7823b6a051', '醉花間 二', '醉花间 二', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["深相憶，莫相憶，相憶情難極。","銀漢是紅牆，一帶遙相隔。","金盤珠露滴，兩岸榆花白。","風搖玉佩清，今夕爲何夕。"]', '["深相憶，莫相憶，相憶情难極。","銀漢是紅牆，一带遙相隔。","金盤珠露滴，兩岸榆花白。","风搖玉佩清，今夕爲何夕。"]', '诗', 'shi', '', NULL, '醉花間 二 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20f53ecf-d518-4729-bd7b-85fd7c305b80', '酒泉子', '酒泉子', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["綠樹春深，燕語鶯啼聲斷續，惠風飄蕩入芳叢，惹殘紅。","柳絲無力嫋煙空，金盞不辭須滿酌，海棠花下思朦朧，醉春風。"]', '["綠樹春深，燕語鶯啼声斷續，惠风飄蕩入芳叢，惹殘紅。","柳絲無力嫋煙空，金盞不辞須满酌，海棠花下思朦朧，醉春风。"]', '诗', 'shi', '', NULL, '酒泉子 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c62ce412-033e-4d02-985b-ada9f1d9d30d', '紗窗恨 一', '紗窗恨 一', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["新春燕子還來至，一雙飛。","壘巢泥溼時時墜，涴人衣。","後園裏看百花發，香風拂，繡戶金扉。","月照紗窗，恨依依。"]', '["新春燕子還来至，一雙飞。","壘巢泥溼时时墜，涴人衣。","後园裏看百花發，香风拂，繡戶金扉。","月照紗窗，恨依依。"]', '诗', 'shi', '', NULL, '紗窗恨 一 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b46f1171-6084-4779-b5ac-b4ff94cb868f', '紗窗恨 二', '紗窗恨 二', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["雙雙蝶翅塗鉛粉，咂花心。","綺窗繡戶飛來穩，畫堂陰。","二三月，愛隨風絮，伴落花，來拂衣襟。","更剪輕羅片，傅黃金。"]', '["雙雙蝶翅塗鉛粉，咂花心。","綺窗繡戶飞来穩，畫堂陰。","二三月，愛隨风絮，伴落花，来拂衣襟。","更剪轻羅片，傅黄金。"]', '诗', 'shi', '', NULL, '紗窗恨 二 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8da3b86d-fc0d-433a-92ef-3563755e008a', '戀情深 一', '戀情深 一', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["滴滴銅壺寒漏咽，醉紅樓月。","宴餘香殿會鴛衾，蕩春心。","真珠簾下曉光侵，鶯語隔瓊林。","寶帳欲開慵起，戀情深。"]', '["滴滴銅壺寒漏咽，醉紅楼月。","宴餘香殿會鴛衾，蕩春心。","真珠簾下晓光侵，鶯語隔瓊林。","寶帳欲开慵起，戀情深。"]', '诗', 'shi', '', NULL, '戀情深 一 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d55ba2-3ef9-43e6-a641-5833e9e36d25', '戀情深 二', '戀情深 二', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["玉殿春濃花爛熳，簇神仙伴。","羅帬窣地縷黃金，奏清音。","酒闌歌罷兩沈沈，一笑動君心。","永願作鴛鴦伴，戀情深。"]', '["玉殿春濃花爛熳，簇神仙伴。","羅帬窣地縷黄金，奏清音。","酒闌歌罷兩沈沈，一笑动君心。","永願作鴛鴦伴，戀情深。"]', '诗', 'shi', '', NULL, '戀情深 二 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2751a3d4-960b-441b-aab4-3ec968b7ab20', '浣溪沙', '浣溪沙', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["七夕年年信不違，銀河清淺白雲微，蟾光鵲影伯勞飛。","每恨蟪蛄憐婺女，幾回嬌妒下鴛機，今宵嘉會兩依依。"]', '["七夕年年信不違，銀河清淺白云微，蟾光鵲影伯勞飞。","每恨蟪蛄怜婺女，幾回嬌妒下鴛機，今宵嘉會兩依依。"]', '诗', 'shi', '', NULL, '浣溪沙 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34c36951-16be-4bc2-9561-21dec19872aa', '攤破浣溪沙', '攤破浣溪沙', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["春水輕波浸綠苔，枇杷洲上紫檀開。","晴日眠沙鸂鶒穩，暖相偎。","羅韈生塵遊女過，有人逢著弄珠回。","蘭麝飄香初解佩，忘歸來。"]', '["春水轻波浸綠苔，枇杷洲上紫檀开。","晴日眠沙鸂鶒穩，暖相偎。","羅韈生塵游女過，有人逢著弄珠回。","蘭麝飄香初解佩，忘归来。"]', '诗', 'shi', '', NULL, '攤破浣溪沙 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('969947f5-257e-43e2-b9ff-e0809b414652', '贊浦子', '贊浦子', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["錦帳添香睡，金爐換夕薰。","嬾結芙蓉帶，慵拖翡翠帬。","正是柳夭桃媚，那堪暮雨朝雲。","宋玉高唐意，裁瓊欲贈君。"]', '["錦帳添香睡，金爐換夕薰。","嬾結芙蓉带，慵拖翡翠帬。","正是柳夭桃媚，那堪暮雨朝云。","宋玉高唐意，裁瓊欲贈君。"]', '诗', 'shi', '', NULL, '贊浦子 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe97cb2b-f02f-4131-b12f-a2a645811cab', '巫山一段雲 一', '巫山一段云 一', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["雨霽巫山上，雲輕映碧天。","遠風吹散又相連，十二晚峰前。","暗濕啼猨樹，高籠過客船。","朝朝暮暮楚江邊，幾度降神仙。"]', '["雨霽巫山上，云轻映碧天。","远风吹散又相連，十二晚峰前。","暗濕啼猨樹，高籠過客船。","朝朝暮暮楚江邊，幾度降神仙。"]', '诗', 'shi', '', NULL, '巫山一段雲 一 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94130927-4287-4310-b913-830f44ee9919', '巫山一段雲 二', '巫山一段云 二', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["貌掩巫山色，才過濯錦波。","阿誰提筆上銀河，月裏寫嫦娥。","薄薄施鉛粉，盈盈挂綺羅。","菖蒲花役夢魂多，年代屬元和。"]', '["貌掩巫山色，才過濯錦波。","阿誰提笔上銀河，月裏寫嫦娥。","薄薄施鉛粉，盈盈挂綺羅。","菖蒲花役梦魂多，年代屬元和。"]', '诗', 'shi', '', NULL, '巫山一段雲 二 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7ecd0cd-2eed-4bf2-9d35-0b195786cf4d', '柳含煙 一', '柳含煙 一', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["隋堤柳，汴河旁。","夾岸綠陰千里，龍舟鳳舸木蘭香。","錦帆張。","因夢江南春景好，一路流蘇羽葆。","笙歌未盡起橫流，鎖春愁。"]', '["隋堤柳，汴河旁。","夾岸綠陰千里，龙舟鳳舸木蘭香。","錦帆張。","因梦江南春景好，一路流蘇羽葆。","笙歌未尽起橫流，鎖春愁。"]', '诗', 'shi', '', NULL, '柳含煙 一 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf4b0bfc-db3b-4414-86b5-5c6336dc6bfd', '柳含煙 二', '柳含煙 二', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["河橋柳，占芳春。","映水含煙拂路，幾回攀折贈行人。","暗傷神。","樂府吹爲橫笛曲，能使離腸斷續。","不如移植在金門，近天恩。"]', '["河橋柳，占芳春。","映水含煙拂路，幾回攀折贈行人。","暗傷神。","乐府吹爲橫笛曲，能使離腸斷續。","不如移植在金门，近天恩。"]', '诗', 'shi', '', NULL, '柳含煙 二 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97e6cd60-58d6-4103-8e43-2983b9420e16', '柳含煙 三', '柳含煙 三', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["章臺柳，近垂旒。","低拂往來冠蓋，朦朧春色滿皇州。","瑞煙浮。","直與路邊江畔別，免被離人攀折。","最憐京兆畫蛾眉，葉纖時。"]', '["章台柳，近垂旒。","低拂往来冠蓋，朦朧春色满皇州。","瑞煙浮。","直與路邊江畔別，免被離人攀折。","最怜京兆畫蛾眉，葉纖时。"]', '诗', 'shi', '', NULL, '柳含煙 三 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42ce5af4-ec0e-4aa8-b12c-105f59f30bb9', '柳含煙 四', '柳含煙 四', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["御溝柳，占春多。","半出宮牆婀娜，有時倒景醮輕羅。","麴塵波。","昨日金鑾巡上苑，風亞舞腰纖輭。","栽培得地近皇宮，瑞煙濃。"]', '["御溝柳，占春多。","半出宮牆婀娜，有时倒景醮轻羅。","麴塵波。","昨日金鑾巡上苑，风亞舞腰纖輭。","栽培得地近皇宮，瑞煙濃。"]', '诗', 'shi', '', NULL, '柳含煙 四 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fc7d738-46c7-4859-b6a9-ec689b4435ea', '更漏子', '更漏子', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["春夜闌，春恨切，花外子規啼月。","人不見，夢難憑，紅紗一點燈。","偏怨別，是芳節，庭下丁香千結。","宵霧散，曉霞暉，梁間雙燕飛。"]', '["春夜闌，春恨切，花外子規啼月。","人不见，梦难憑，紅紗一点灯。","偏怨別，是芳節，庭下丁香千結。","宵霧散，晓霞暉，梁间雙燕飞。"]', '诗', 'shi', '', NULL, '更漏子 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45ba5f8f-a727-4a3f-8d99-93b6b358f0c8', '喜遷鶯', '喜遷鶯', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["芳春景，曖晴煙。","喬木見鶯遷，傳枝偎葉語關關，飛過綺叢間。","錦翼鮮，金毳輭。","百轉千嬌相喚，碧紗窗曉怕聞聲，驚破鴛鴦暖。"]', '["芳春景，曖晴煙。","喬木见鶯遷，傳枝偎葉語关关，飞過綺叢间。","錦翼鲜，金毳輭。","百轉千嬌相喚，碧紗窗晓怕闻声，驚破鴛鴦暖。"]', '诗', 'shi', '', NULL, '喜遷鶯 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79301f14-2794-4905-aaae-f2197be7fa69', '應天長', '應天长', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["平江波暖鴛鴦語，兩兩釣船歸極浦。","蘆洲一夜風和雨，飛起淺沙翹雪鷺。","漁燈明遠渚，蘭櫂今宵何處。","羅袂從風輕舉，愁殺采蓮女。"]', '["平江波暖鴛鴦語，兩兩釣船归極浦。","蘆洲一夜风和雨，飞起淺沙翹雪鷺。","漁灯明远渚，蘭櫂今宵何处。","羅袂從风轻舉，愁殺采蓮女。"]', '诗', 'shi', '', NULL, '應天長 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79c0ac1e-aa0f-48ec-981f-47eca5978fc5', '月宮春', '月宮春', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["水晶宮裏桂花開，神仙探幾回。","紅芳金蘂繡重臺，低傾瑪瑙杯。","玉兔銀蟾爭守護，姮娥姹女戲相偎。","遙聽鈞天九奏，玉皇親看來。"]', '["水晶宮裏桂花开，神仙探幾回。","紅芳金蘂繡重台，低傾瑪瑙杯。","玉兔銀蟾爭守護，姮娥姹女戲相偎。","遙听鈞天九奏，玉皇親看来。"]', '诗', 'shi', '', NULL, '月宮春 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('901ead4c-b1c3-449c-913a-a238f97978fe', '虞美人 一', '虞美人 一', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["鴛鴦對浴銀塘暖，水面蒲梢短。","垂楊低拂麴塵波，蛛絲結網露珠多，滴圓荷。","遙思桃葉吳江碧，便是天河隔。","錦鱗紅鬣影沈沈，想思空有夢相尋，意難任。"]', '["鴛鴦对浴銀塘暖，水面蒲梢短。","垂楊低拂麴塵波，蛛絲結網露珠多，滴圓荷。","遙思桃葉吳江碧，便是天河隔。","錦鱗紅鬣影沈沈，想思空有梦相尋，意难任。"]', '诗', 'shi', '', NULL, '虞美人 一 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('649ce5d7-4e66-4c97-9679-ceafd5eda125', '虞美人 二', '虞美人 二', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["寶檀金縷鴛鴦枕，綬帶盤宮錦。","夕陽低映小窗明，南園綠樹語鶯鶯，夢難成。","玉爐香煖頻添炷，滿地飄輕絮。","珠簾不卷度沈煙，庭前閑立畫鞦韆，豔陽天。"]', '["寶檀金縷鴛鴦枕，綬带盤宮錦。","夕陽低映小窗明，南园綠樹語鶯鶯，梦难成。","玉爐香煖頻添炷，满地飄轻絮。","珠簾不卷度沈煙，庭前闲立畫鞦韆，豔陽天。"]', '诗', 'shi', '', NULL, '虞美人 二 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f263c2d1-2f56-49da-825a-2c9d6e4c52b6', '臨江仙', '臨江仙', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["暮蟬聲盡落斜陽，銀蟾影挂瀟湘。","黃陵廟側水茫茫，楚山紅樹，煙雨隔高唐。","岸泊漁燈風颭碎，白蘋遠散濃香。","靈娥鼓瑟韻清商，朱弦淒切，雲散碧天長。"]', '["暮蟬声尽落斜陽，銀蟾影挂瀟湘。","黄陵廟側水茫茫，楚山紅樹，煙雨隔高唐。","岸泊漁灯风颭碎，白蘋远散濃香。","靈娥鼓瑟韻清商，朱弦淒切，云散碧天长。"]', '诗', 'shi', '', NULL, '臨江仙 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('512921f2-22f5-4d35-ba7e-7844b6036b7b', '接賢賓', '接賢賓', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["香韉鏤襜五色驄，值春景初融。","流珠噴沫躞蹀，汗血流紅。","少年公子能乘馭，金鑣玉轡瓏璁。","爲惜珊瑚鞭不下，驕生百步千蹤。","信穿花，從拂柳，向九陌追風。"]', '["香韉鏤襜五色驄，值春景初融。","流珠噴沫躞蹀，汗血流紅。","少年公子能乘馭，金鑣玉轡瓏璁。","爲惜珊瑚鞭不下，驕生百步千蹤。","信穿花，從拂柳，向九陌追风。"]', '诗', 'shi', '', NULL, '接賢賓 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5c48f52-f0fc-4481-9e89-a924da744f4b', '贊成功', '贊成功', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["海棠未坼，萬點深紅，香包緘結一重重。","似含羞態，邀勒春風，蜂來蝶去，任遶芳叢。","昨夜微雨，飄灑庭中，忽聞聲滴井邊桐。","美人驚起，坐聽晨鐘，快教折取，戴玉瓏璁。"]', '["海棠未坼，万点深紅，香包緘結一重重。","似含羞態，邀勒春风，蜂来蝶去，任遶芳叢。","昨夜微雨，飄灑庭中，忽闻声滴井邊桐。","美人驚起，坐听晨鐘，快教折取，戴玉瓏璁。"]', '诗', 'shi', '', NULL, '贊成功 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d8c7eeb-c699-42a1-9ca3-b33d199727da', '甘州遍 一', '甘州遍 一', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["春光好，公子愛閑遊，足風流。","金鞍白馬，雕弓寶劒，紅纓錦襜出長楸。","花蔽膝，玉銜頭。","尋芳逐勝歡宴，絲竹不曾休。","美人唱，揭調是甘州。","醉紅樓，堯年舜日，樂聖永無憂。"]', '["春光好，公子愛闲游，足风流。","金鞍白马，雕弓寶劒，紅纓錦襜出长楸。","花蔽膝，玉銜头。","尋芳逐勝歡宴，絲竹不曾休。","美人唱，揭調是甘州。","醉紅楼，堯年舜日，乐聖永無憂。"]', '诗', 'shi', '', NULL, '甘州遍 一 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('284c4514-9fdc-4384-8fe7-7bab47101ae1', '甘州遍 二', '甘州遍 二', 'a6b2b702-36da-4fef-85e7-f04dd02f7f12', '唐', '["秋風緊，平磧雁行低，陣雲齊。","蕭蕭颯颯，邊聲四起，愁聞戍角與征鼙。","青塚北，黑山西。","沙飛聚散無定，往往路人迷。","鐵衣冷，戰馬血霑蹄。","破蕃奚，鳳皇詔下，步步躡丹梯。"]', '["秋风緊，平磧雁行低，陣云齊。","蕭蕭颯颯，邊声四起，愁闻戍角與征鼙。","青塚北，黑山西。","沙飞聚散無定，往往路人迷。","鐵衣冷，戰马血霑蹄。","破蕃奚，鳳皇詔下，步步躡丹梯。"]', '诗', 'shi', '', NULL, '甘州遍 二 毛文錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a76b4d1f-ef7f-4292-9618-7524558e218f', '漁父', '漁父', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["白芷汀寒立鷺鷥，蘋風輕翦浪花時。","煙冪冪，日遲遲，香引芙蓉惹釣絲。"]', '["白芷汀寒立鷺鷥，蘋风轻翦浪花时。","煙冪冪，日遲遲，香引芙蓉惹釣絲。"]', '诗', 'shi', '', NULL, '漁父 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dff7809-ba84-4a19-aec5-09732afa609e', '天仙子 一', '天仙子 一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["柳色披衫金縷鳳，纖手輕拈紅豆弄。","翠蛾雙斂正含情，桃花洞，瑤臺夢，一片春愁誰與共。"]', '["柳色披衫金縷鳳，纖手轻拈紅豆弄。","翠蛾雙斂正含情，桃花洞，瑤台梦，一片春愁誰與共。"]', '诗', 'shi', '', NULL, '天仙子 一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a2b41e5-416e-4f61-8643-73d38785b06e', '天仙子 二', '天仙子 二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["洞口春紅飛䔩䔩，仙子含愁眉黛綠。","阮郎何事不歸來，嬾燒金，慵篆玉，流水桃花空斷續。"]', '["洞口春紅飞䔩䔩，仙子含愁眉黛綠。","阮郎何事不归来，嬾燒金，慵篆玉，流水桃花空斷續。"]', '诗', 'shi', '', NULL, '天仙子 二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6929f5f-002f-4ef5-83e8-541abd39c916', '江城子 一', '江城子 一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["初夜含嬌入洞房，理殘妝，柳眉長。","翡翠屏中，親爇玉爐香。","整頓金鈿呼小玉，排紅燭，待潘郎。"]', '["初夜含嬌入洞房，理殘妝，柳眉长。","翡翠屏中，親爇玉爐香。","整頓金鈿呼小玉，排紅燭，待潘郎。"]', '诗', 'shi', '', NULL, '江城子 一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43378641-1a09-4f04-a37a-68d0970b9be7', '江城子 二', '江城子 二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["竹裏風生月上門，理秦箏，對雲屏。","輕撥朱弦，恐亂馬嘶聲。","含恨含嬌獨自語，今夜約，太遲生。"]', '["竹裏风生月上门，理秦箏，对云屏。","轻撥朱弦，恐亂马嘶声。","含恨含嬌独自語，今夜約，太遲生。"]', '诗', 'shi', '', NULL, '江城子 二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('624ca79b-6004-4e4d-b70a-771d4e6acc72', '江城子 三', '江城子 三', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["斗轉星移玉漏頻，已三更，對棲鶯。","歷歷花間，似有馬蹄聲。","含笑整衣開繡戶，斜斂手，下階迎。"]', '["斗轉星移玉漏頻，已三更，对棲鶯。","歷歷花间，似有马蹄声。","含笑整衣开繡戶，斜斂手，下階迎。"]', '诗', 'shi', '', NULL, '江城子 三 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd00244e-0599-4466-af79-adff05968464', '江城子 四', '江城子 四', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["迎得郎來入繡闈，語相思，連理枝。","鬢亂釵垂，梳墮印山眉。","婭姹含情嬌不語，纖玉手，撫郎衣。"]', '["迎得郎来入繡闈，語相思，連理枝。","鬢亂釵垂，梳墮印山眉。","婭姹含情嬌不語，纖玉手，撫郎衣。"]', '诗', 'shi', '', NULL, '江城子 四 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62e05466-f3a4-4c8d-9e86-2e3dedc34e48', '江城子 五', '江城子 五', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["帳裏鴛鴦交頸情，恨雞聲，天已明。","愁見街前，還是說歸程。","臨上馬時期後會，待梅綻，月初生。"]', '["帳裏鴛鴦交頸情，恨雞声，天已明。","愁见街前，還是说归程。","臨上马时期後會，待梅綻，月初生。"]', '诗', 'shi', '', NULL, '江城子 五 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d70ffe5-4958-4c6e-a650-8e713d28bfcd', '何滿子 一', '何满子 一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["正是破瓜年幾，含情慣得人饒。","桃李精神鸚鵡舌，可堪虛度良宵。","却愛藍羅帬子，羨他長束纖腰。"]', '["正是破瓜年幾，含情慣得人饒。","桃李精神鸚鵡舌，可堪虛度良宵。","却愛藍羅帬子，羨他长束纖腰。"]', '诗', 'shi', '', NULL, '何滿子 一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92caaad4-0f16-4570-8c22-20f88c26f75a', '何滿子 二', '何满子 二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["寫得魚牋無限，其如花鎖春暉。","目斷巫山雲雨，空教殘夢依依。","却愛熏香小鴨，羨他長在屏帷。"]', '["寫得鱼牋無限，其如花鎖春暉。","目斷巫山云雨，空教殘梦依依。","却愛熏香小鴨，羨他长在屏帷。"]', '诗', 'shi', '', NULL, '何滿子 二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab08b410-e465-4000-b0d3-125df9cee911', '望梅花', '望梅花', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["春草全無消息，臘雪猶餘蹤跡。","越嶺寒枝香自折，冷豔奇芳堪惜。","何事壽陽無處覓，吹入誰家橫笛。"]', '["春草全無消息，臘雪猶餘蹤跡。","越嶺寒枝香自折，冷豔奇芳堪惜。","何事壽陽無处覓，吹入誰家橫笛。"]', '诗', 'shi', '', NULL, '望梅花 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eea06d1f-a4b1-493f-a3b2-94fd24308883', '薄命女', '薄命女', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["天欲曉，宮漏穿花聲繚繞。","窗裏星光少。","冷露寒侵帳額，殘月光沈樹杪。","夢斷錦帷空悄悄，彊起愁眉小。"]', '["天欲晓，宮漏穿花声繚繞。","窗裏星光少。","冷露寒侵帳額，殘月光沈樹杪。","梦斷錦帷空悄悄，彊起愁眉小。"]', '诗', 'shi', '', NULL, '薄命女 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84e8ed71-3da9-4874-bfce-c1744891a7bf', '春光好 一', '春光好 一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["紗窗暖，畫屏閑，嚲雲鬟。","睡起四肢無力，半春[間]。","玉指翦裁羅勝，金盤點綴酥山。","窺宋深心無限事，小眉彎。"]', '["紗窗暖，畫屏闲，嚲云鬟。","睡起四肢無力，半春[间]。","玉指翦裁羅勝，金盤点綴酥山。","窺宋深心無限事，小眉彎。"]', '诗', 'shi', '', NULL, '春光好 一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee21d5e4-ed5b-40b3-91e5-357a82ac0e8b', '春光好 二', '春光好 二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["蘋葉輭，杏花明，畫船輕。","雙浴鴛鴦出綠汀，櫂歌聲。","春水無風無浪，春天半雨半晴。","紅粉相隨南浦晚，幾含情。"]', '["蘋葉輭，杏花明，畫船轻。","雙浴鴛鴦出綠汀，櫂歌声。","春水無风無浪，春天半雨半晴。","紅粉相隨南浦晚，幾含情。"]', '诗', 'shi', '', NULL, '春光好 二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5ed0458-7ef4-43e8-8a71-18b0467e5e3c', '采桑子', '采桑子', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["蝤蠐領上訶梨子，繡帶雙垂。","椒戶閑時，競學摴蒲賭荔支。","叢頭鞋子紅編細，帬窣金絲。","無事嚬眉，春思翻教阿母疑。"]', '["蝤蠐領上訶梨子，繡带雙垂。","椒戶闲时，競学摴蒲賭荔支。","叢头鞋子紅編細，帬窣金絲。","無事嚬眉，春思翻教阿母疑。"]', '诗', 'shi', '', NULL, '采桑子 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdda441f-5b0d-4c10-ac51-47c64c5dd054', '菩薩蠻', '菩薩蠻', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["越梅半拆輕寒裏，冰清澹薄籠藍水。","暖覺杏梢紅，遊絲狂惹風。","閑階莎徑碧，遠夢猶堪惜。","離恨又迎春，相思難重陳。"]', '["越梅半拆轻寒裏，冰清澹薄籠藍水。","暖覺杏梢紅，游絲狂惹风。","闲階莎徑碧，远梦猶堪惜。","離恨又迎春，相思难重陳。"]', '诗', 'shi', '', NULL, '菩薩蠻 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e962606-ad47-4a2e-9add-4ab9fa17ccc6', '喜遷鶯', '喜遷鶯', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["曉月墜，宿雲披，銀燭錦屏帷。","建章鐘動玉繩低，宮漏出花遲。","春態淺，來雙燕，紅日漸長一線。","嚴妝欲罷轉黃鸝，飛上萬年枝。"]', '["晓月墜，宿云披，銀燭錦屏帷。","建章鐘动玉繩低，宮漏出花遲。","春態淺，来雙燕，紅日漸长一線。","嚴妝欲罷轉黄鸝，飞上万年枝。"]', '诗', 'shi', '', NULL, '喜遷鶯 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68375bc2-e60f-4100-a9a6-8f6821db9166', '山花子 一', '山花子 一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["鶯錦蟬縠馥麝臍，輕裾花草曉煙迷。","鸂鶒戰金紅掌墜，翠雲低。","星靨笑偎霞臉畔，蹙金開襜襯銀泥。","春思半和芳草嫩，碧萋萋。"]', '["鶯錦蟬縠馥麝臍，轻裾花草晓煙迷。","鸂鶒戰金紅掌墜，翠云低。","星靨笑偎霞臉畔，蹙金开襜襯銀泥。","春思半和芳草嫩，碧萋萋。"]', '诗', 'shi', '', NULL, '山花子 一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9a9c780-c60a-437b-a389-ad20caa5bbf6', '山花子 二', '山花子 二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["銀字笙寒調正長，水文簟冷畫屏涼。","玉腕重，金扼臂，淡梳妝。","幾度試香纖手暖，一回嘗酒絳脣光。","佯弄紅絲繩拂子，打檀郎。"]', '["銀字笙寒調正长，水文簟冷畫屏涼。","玉腕重，金扼臂，淡梳妝。","幾度試香纖手暖，一回嘗酒絳脣光。","佯弄紅絲繩拂子，打檀郎。"]', '诗', 'shi', '', NULL, '山花子 二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a28e6364-2ce9-49ff-83a8-32d9b8a91a18', '臨江仙 一', '臨江仙 一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["海棠香老春江晚，小樓霧縠空濛。","翠鬟初出繡簾中，麝煙鸞佩惹蘋風。","碾玉釵搖鸂鶒戰，雪肌雲鬢將融。","含情遙指碧波東，越王臺殿蓼花紅。"]', '["海棠香老春江晚，小楼霧縠空濛。","翠鬟初出繡簾中，麝煙鸾佩惹蘋风。","碾玉釵搖鸂鶒戰，雪肌云鬢將融。","含情遙指碧波东，越王台殿蓼花紅。"]', '诗', 'shi', '', NULL, '臨江仙 一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d49c5ec6-48dc-4cca-a3c0-9f8258f70730', '臨江仙 二', '臨江仙 二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["披袍窣地紅宮錦，鶯語時轉輕音。","碧羅冠子穩犀簪，鳳凰雙颭步搖金。","肌骨細勻紅玉輭，臉波微送春心。","嬌羞不肯入鴛衾，蘭膏光裏兩情深。"]', '["披袍窣地紅宮錦，鶯語时轉轻音。","碧羅冠子穩犀簪，鳳凰雙颭步搖金。","肌骨細勻紅玉輭，臉波微送春心。","嬌羞不肯入鴛衾，蘭膏光裏兩情深。"]', '诗', 'shi', '', NULL, '臨江仙 二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52995028-b821-402a-adaf-8b1b3ce1ef94', '小重山 一', '小重山 一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["春入神京萬木芳，禁林鶯語滑，蝶飛狂。","曉花擎露妒啼妝，紅日永，風和百花香。","煙鎖柳絲長，御溝澄碧水，轉池塘。","時時微雨洗風光，天衢遠，到處引笙篁。"]', '["春入神京万木芳，禁林鶯語滑，蝶飞狂。","晓花擎露妒啼妝，紅日永，风和百花香。","煙鎖柳絲长，御溝澄碧水，轉池塘。","时时微雨洗风光，天衢远，到处引笙篁。"]', '诗', 'shi', '', NULL, '小重山 一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a02d6854-dca7-416b-af5d-ddd4630a2883', '小重山 二', '小重山 二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["正是神京爛熳時，羣仙初折得，郄詵枝。","烏犀白紵最相宜，精神出，御陌袖鞭垂。","柳色展愁眉，管弦分響亮，探花期。","光陰占斷曲江池，新牓上，名姓徹丹墀。"]', '["正是神京爛熳时，羣仙初折得，郄詵枝。","烏犀白紵最相宜，精神出，御陌袖鞭垂。","柳色展愁眉，管弦分响亮，探花期。","光陰占斷曲江池，新牓上，名姓徹丹墀。"]', '诗', 'shi', '', NULL, '小重山 二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c341415-124a-473a-bf08-6e4e871db200', '麥秀兩岐', '麦秀兩岐', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["涼簟鋪斑竹，鴛枕竝紅玉。","臉蓮紅，眉柳綠。","胸雪宜新浴，淡黃衫子裁春縠，異香芬馥。","羞道交回燭，未慣雙雙宿。","樹連枝，魚比目。","掌上腰如束，嬌嬈不爭人拳跼，黛眉微蹙。"]', '["涼簟鋪斑竹，鴛枕竝紅玉。","臉蓮紅，眉柳綠。","胸雪宜新浴，淡黄衫子裁春縠，異香芬馥。","羞道交回燭，未慣雙雙宿。","樹連枝，鱼比目。","掌上腰如束，嬌嬈不爭人拳跼，黛眉微蹙。"]', '诗', 'shi', '', NULL, '麥秀兩岐 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8d90016-b70a-4791-81b0-2b6528d52cb9', '生查子 一', '生查子 一', 'fe9677ec-c0d1-4155-8222-fdfeaa096aba', '唐', '["春山煙欲收，天澹星稀小。","殘月臉邊明，別淚臨清曉。","語已多，情未了，回首猶重道。","記得綠羅帬，處處憐芳草。"]', '["春山煙欲收，天澹星稀小。","殘月臉邊明，別泪臨清晓。","語已多，情未了，回首猶重道。","記得綠羅帬，处处怜芳草。"]', '诗', 'shi', '', NULL, '生查子 一 牛希濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e23e028c-9a1b-4fcc-9c3f-fa806f7e87f3', '生查子 二', '生查子 二', 'fe9677ec-c0d1-4155-8222-fdfeaa096aba', '唐', '["新月曲如眉，未有團圞意。","紅豆不堪看，滿眼相思淚。","終日劈桃穰，人在心兒裏。","兩朵隔牆花，早晚成連理。"]', '["新月曲如眉，未有團圞意。","紅豆不堪看，满眼相思泪。","終日劈桃穰，人在心兒裏。","兩朵隔牆花，早晚成連理。"]', '诗', 'shi', '', NULL, '生查子 二 牛希濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9e5a6da-df41-48d4-9225-2c3720f15181', '中興樂', '中兴乐', 'fe9677ec-c0d1-4155-8222-fdfeaa096aba', '唐', '["池塘暖碧浸晴暉，濛濛柳絮輕飛。","紅蘂凋來，醉夢還稀。","春雲空有雁歸，珠簾垂。","東風寂寞，恨郎拋擲，淚濕羅衣。"]', '["池塘暖碧浸晴暉，濛濛柳絮轻飞。","紅蘂凋来，醉梦還稀。","春云空有雁归，珠簾垂。","东风寂寞，恨郎拋擲，泪濕羅衣。"]', '诗', 'shi', '', NULL, '中興樂 牛希濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e31ea600-61d9-48b9-9b23-d1b3b0bf5447', '酒泉子', '酒泉子', 'fe9677ec-c0d1-4155-8222-fdfeaa096aba', '唐', '["枕轉簟涼，清曉遠鐘殘夢。","月光斜，簾影動，舊爐香。","夢中說盡相思事，纖手勻雙淚。","去年書，今日意，斷人腸。"]', '["枕轉簟涼，清晓远鐘殘梦。","月光斜，簾影动，旧爐香。","梦中说尽相思事，纖手勻雙泪。","去年书，今日意，斷人腸。"]', '诗', 'shi', '', NULL, '酒泉子 牛希濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('594587c3-2101-43ef-baa4-9e9e048fbb11', '謁金門', '謁金门', 'fe9677ec-c0d1-4155-8222-fdfeaa096aba', '唐', '["秋已暮，重疊關山岐路。","嘶馬搖鞭何處去，曉禽霜滿樹。","夢斷禁城鐘鼓，淚滴枕檀無數。","一點凝紅和薄霧，翠蛾愁不語。"]', '["秋已暮，重叠关山岐路。","嘶马搖鞭何处去，晓禽霜满樹。","梦斷禁城鐘鼓，泪滴枕檀無數。","一点凝紅和薄霧，翠蛾愁不語。"]', '诗', 'shi', '', NULL, '謁金門 牛希濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13589363-8328-469b-a799-ba5250baf1f1', '臨江仙 一', '臨江仙 一', 'fe9677ec-c0d1-4155-8222-fdfeaa096aba', '唐', '["峭碧參差十二峰，冷煙寒樹重重。","瑤姬宮殿是仙蹤。","金爐珠帳，香靄晝偏濃。","一自楚王驚夢斷，人間無路相逢。","至今雲雨帶愁容。","月斜江上，征櫂動晨鐘。"]', '["峭碧參差十二峰，冷煙寒樹重重。","瑤姬宮殿是仙蹤。","金爐珠帳，香靄晝偏濃。","一自楚王驚梦斷，人间無路相逢。","至今云雨带愁容。","月斜江上，征櫂动晨鐘。"]', '诗', 'shi', '', NULL, '臨江仙 一 牛希濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b76cf17-b038-455e-a931-bd668fef471f', '臨江仙 二', '臨江仙 二', 'fe9677ec-c0d1-4155-8222-fdfeaa096aba', '唐', '["謝家仙觀寄雲岑，嵒蘿拂地成陰。","洞房不閉白雲深。","當時丹竈，一粒化黃金。","石壁霞衣猶半挂，松風長似鳴琴。","時聞唳鶴起前林。"]', '["謝家仙观寄云岑，嵒蘿拂地成陰。","洞房不閉白云深。","當时丹竈，一粒化黄金。","石壁霞衣猶半挂，松风长似鳴琴。","时闻唳鹤起前林。"]', '诗', 'shi', '', NULL, '臨江仙 二 牛希濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1267ce90-a270-493f-9b56-a6a340b935a8', '臨江仙 三', '臨江仙 三', 'fe9677ec-c0d1-4155-8222-fdfeaa096aba', '唐', '["渭闕宮城秦樹凋，玉樓獨上無憀。","含情不語自吹簫。","調清和恨，天路逐風飄。","何事乘龍人忽降，似知深意相招。","三清攜手路非遙。","世間屏障，彩筆畫嬌饒。"]', '["渭闕宮城秦樹凋，玉楼独上無憀。","含情不語自吹簫。","調清和恨，天路逐风飄。","何事乘龙人忽降，似知深意相招。","三清携手路非遙。","世间屏障，彩笔畫嬌饒。"]', '诗', 'shi', '', NULL, '臨江仙 三 牛希濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('421ca5c8-1abc-461b-b01a-fe0d06cef23b', '臨江仙 四', '臨江仙 四', 'fe9677ec-c0d1-4155-8222-fdfeaa096aba', '唐', '["江繞黃陵春廟閑，嬌鶯獨語關關。","滿庭重疊綠苔斑。","陰雲無事，四散自歸山。","簫鼓聲稀香燼冷，月娥斂盡彎環。","風流皆道勝人間。","須知狂客，判死爲紅顏。"]', '["江繞黄陵春廟闲，嬌鶯独語关关。","满庭重叠綠苔斑。","陰云無事，四散自归山。","簫鼓声稀香燼冷，月娥斂尽彎环。","风流皆道勝人间。","須知狂客，判死爲紅顏。"]', '诗', 'shi', '', NULL, '臨江仙 四 牛希濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67e14c79-031e-4199-a2ac-6b5956cf2bfc', '臨江仙 五', '臨江仙 五', 'fe9677ec-c0d1-4155-8222-fdfeaa096aba', '唐', '["素洛春光瀲灩平，千重媚臉初生。","凌波羅韈勢輕輕。","煙籠日照，珠翠半分明。","風引寶衣疑欲舞，鸞回鳳翥堪驚。","也知心許恐無成。","陳王辭賦，千載有聲名。"]', '["素洛春光瀲灩平，千重媚臉初生。","凌波羅韈勢轻轻。","煙籠日照，珠翠半分明。","风引寶衣疑欲舞，鸾回鳳翥堪驚。","也知心許恐無成。","陳王辞賦，千載有声名。"]', '诗', 'shi', '', NULL, '臨江仙 五 牛希濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e404a94c-8a33-4c12-84a9-caded0197d9b', '臨江仙 六', '臨江仙 六', 'fe9677ec-c0d1-4155-8222-fdfeaa096aba', '唐', '["柳帶搖風漢水濱，平蕪兩岸爭勻。","鴛鴦對浴浪痕新。","弄珠遊女，微笑自含春。","輕步暗移蟬鬢動，羅帬風惹輕塵。","水精宮殿豈無因。","空勞纖手，解佩贈情人。"]', '["柳带搖风漢水濱，平蕪兩岸爭勻。","鴛鴦对浴浪痕新。","弄珠游女，微笑自含春。","轻步暗移蟬鬢动，羅帬风惹轻塵。","水精宮殿豈無因。","空勞纖手，解佩贈情人。"]', '诗', 'shi', '', NULL, '臨江仙 六 牛希濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('076480bc-f883-4161-93cd-c38b5583d723', '臨江仙 七', '臨江仙 七', 'fe9677ec-c0d1-4155-8222-fdfeaa096aba', '唐', '["洞庭波浪颭晴天，君山一點凝煙。","此中真境屬神仙。","玉樓珠殿，相映月輪邊。","萬里平湖秋色冷，星辰垂影參然。","橘林霜重更紅鮮。","羅浮山下，有路暗相連。"]', '["洞庭波浪颭晴天，君山一点凝煙。","此中真境屬神仙。","玉楼珠殿，相映月輪邊。","万里平湖秋色冷，星辰垂影參然。","橘林霜重更紅鲜。","羅浮山下，有路暗相連。"]', '诗', 'shi', '', NULL, '臨江仙 七 牛希濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcc0a539-f1a3-4ef2-9486-e89290b403fe', '相見歡', '相见歡', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["羅襦繡袂香紅，畫堂中。","細草平沙蕃馬，小屏風。","卷羅幕，凭妝閣，思無窮。","暮雨輕煙魂斷，隔簾櫳。"]', '["羅襦繡袂香紅，畫堂中。","細草平沙蕃马，小屏风。","卷羅幕，凭妝閣，思無窮。","暮雨轻煙魂斷，隔簾櫳。"]', '诗', 'shi', '', NULL, '相見歡 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dfc7812-6035-4f08-b7f0-cb0766dbf81e', '醉公子', '醉公子', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["慢綰青絲髮，光砑吳綾韈。","牀上小熏籠，韶州新退紅。","叵耐無端處，捻得從頭汙。","惱得眼慵開，問人閑事來。"]', '["慢綰青絲髮，光砑吳綾韈。","牀上小熏籠，韶州新退紅。","叵耐無端处，捻得從头汙。","惱得眼慵开，问人闲事来。"]', '诗', 'shi', '', NULL, '醉公子 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e761530-d6b4-4fe9-8a62-7bb08c1fa71d', '女冠子 一', '女冠子 一', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["求仙去也，翠鈿金箆盡捨，入嵒巒。","霧卷黃羅帔，雲雕白玉冠。","野煙溪洞冷，林月石橋寒。","靜夜松風下，禮天壇。"]', '["求仙去也，翠鈿金箆尽捨，入嵒巒。","霧卷黄羅帔，云雕白玉冠。","野煙溪洞冷，林月石橋寒。","静夜松风下，禮天壇。"]', '诗', 'shi', '', NULL, '女冠子 一 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5f87fbb-0585-4eff-b3b2-c945728d165b', '女冠子 二', '女冠子 二', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["雲羅霧縠，新授明威法籙，降真函。","髻綰青絲髮，冠抽碧玉篸。","往來雲過五，去住島經三。","正遇劉郎使，啓瑤緘。"]', '["云羅霧縠，新授明威法籙，降真函。","髻綰青絲髮，冠抽碧玉篸。","往来云過五，去住島經三。","正遇劉郎使，啓瑤緘。"]', '诗', 'shi', '', NULL, '女冠子 二 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca8bbf7b-047d-4871-8cca-025c0d278b50', '浣溪沙 一', '浣溪沙 一', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["紅蓼渡頭秋正雨，印沙鷗跡自成行，整鬟飄袖野風香。","不語含嚬深浦裏，幾回愁煞櫂船郎，燕歸帆盡水茫茫。"]', '["紅蓼渡头秋正雨，印沙鷗跡自成行，整鬟飄袖野风香。","不語含嚬深浦裏，幾回愁煞櫂船郎，燕归帆尽水茫茫。"]', '诗', 'shi', '', NULL, '浣溪沙 一 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bc749ab-ea09-45e7-b886-821be059e82f', '浣溪沙 二', '浣溪沙 二', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["鈿匣菱花錦帶垂，靜臨蘭檻卸頭時，約鬟低珥算歸期。","花茂草青湘渚闊，夢餘空有漏依依，二年終日損芳菲。"]', '["鈿匣菱花錦带垂，静臨蘭檻卸头时，約鬟低珥算归期。","花茂草青湘渚闊，梦餘空有漏依依，二年終日損芳菲。"]', '诗', 'shi', '', NULL, '浣溪沙 二 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb2eec04-7a68-486d-b59e-5943f7292793', '浣溪沙 三', '浣溪沙 三', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["粉上依稀有淚痕，郡庭花落欲黃昏，遠情深恨與誰論。","記得去年寒食日，延秋門外卓金輪，日斜人散暗銷魂。"]', '["粉上依稀有泪痕，郡庭花落欲黄昏，远情深恨與誰論。","記得去年寒食日，延秋门外卓金輪，日斜人散暗銷魂。"]', '诗', 'shi', '', NULL, '浣溪沙 三 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e86d8df-d39f-4bd2-9d63-58f31877ab6f', '浣溪沙 四', '浣溪沙 四', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["握手河橋柳似金，蜂鬚輕惹百花心，蕙風蘭思寄清琴。","意滿便同春水滿，情深還似酒杯深，楚煙湘月兩沈沈。"]', '["握手河橋柳似金，蜂鬚轻惹百花心，蕙风蘭思寄清琴。","意满便同春水满，情深還似酒杯深，楚煙湘月兩沈沈。"]', '诗', 'shi', '', NULL, '浣溪沙 四 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32c5b2a1-a1fa-47b3-808b-bfa415ef3979', '浣溪沙 五', '浣溪沙 五', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["簾外三間出寺牆，滿街垂柳綠陰長，嫩紅輕翠間濃妝。","瞥地見時猶可可，却來閑處暗思量，如今情事隔仙鄉。"]', '["簾外三间出寺牆，满街垂柳綠陰长，嫩紅轻翠间濃妝。","瞥地见时猶可可，却来闲处暗思量，如今情事隔仙乡。"]', '诗', 'shi', '', NULL, '浣溪沙 五 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fab31a88-a7d3-45c5-a597-34d42134c515', '浣溪沙 六', '浣溪沙 六', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["江館清秋纜客船，故人相送夜開筵，麝煙蘭燄簇花鈿。","正是斷魂迷楚雨，不堪離恨咽湘弦，月高霜白水連天。"]', '["江館清秋纜客船，故人相送夜开筵，麝煙蘭燄簇花鈿。","正是斷魂迷楚雨，不堪離恨咽湘弦，月高霜白水連天。"]', '诗', 'shi', '', NULL, '浣溪沙 六 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c21cfb3c-b2d5-4781-ac34-0a779955a4e8', '浣溪沙 七', '浣溪沙 七', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["傾國傾城恨有餘，幾多紅淚泣姑蘇，倚風凝睇雪肌膚。","吳主山河空落日，越王宮殿半平蕪，藕花菱蔓滿平湖。"]', '["傾国傾城恨有餘，幾多紅泪泣姑蘇，倚风凝睇雪肌膚。","吳主山河空落日，越王宮殿半平蕪，藕花菱蔓满平湖。"]', '诗', 'shi', '', NULL, '浣溪沙 七 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5c8662d-85ff-445e-a5bf-d1cc71fd855f', '浣溪沙 八', '浣溪沙 八', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["越女淘金春水上，步搖雲鬢佩鳴璫，渚風江草又清香。","不爲遠山凝翠黛，只應含恨向斜陽，碧桃花謝憶劉郎。"]', '["越女淘金春水上，步搖云鬢佩鳴璫，渚风江草又清香。","不爲远山凝翠黛，只應含恨向斜陽，碧桃花謝憶劉郎。"]', '诗', 'shi', '', NULL, '浣溪沙 八 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44f24073-d2c5-488f-a529-ba5978011574', '謁金門', '謁金门', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["春滿院，疊損羅衣金線。","睡覺水精簾未卷，簾前雙語燕。","斜掩金鋪一扇，滿地落花千片。","早是相思腸欲斷，忍教頻夢見。"]', '["春满院，叠損羅衣金線。","睡覺水精簾未卷，簾前雙語燕。","斜掩金鋪一扇，满地落花千片。","早是相思腸欲斷，忍教頻梦见。"]', '诗', 'shi', '', NULL, '謁金門 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('540ef26b-17d4-4863-aa24-2a86ef84abb3', '喜遷鶯 一', '喜遷鶯 一', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["殘蟾落，曉鐘鳴，羽化覺身輕。","乍無春睡有餘酲，杏苑雪初晴。","紫陌長，襟袖冷，不是人間風景。","回看塵土似前生，休羨谷中鸎。"]', '["殘蟾落，晓鐘鳴，羽化覺身轻。","乍無春睡有餘酲，杏苑雪初晴。","紫陌长，襟袖冷，不是人间风景。","回看塵土似前生，休羨谷中鸎。"]', '诗', 'shi', '', NULL, '喜遷鶯 一 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1f2599d-24b0-4835-8004-2cfa3af15afc', '喜遷鶯 二', '喜遷鶯 二', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["金門曉，玉京春，駿馬驟輕塵。","樺煙深處白衫新，認得化龍身。","九陌喧，千戶啓，滿袖桂香風細。","杏園歡宴曲江濱，自此占芳辰。"]', '["金门晓，玉京春，駿马驟轻塵。","樺煙深处白衫新，認得化龙身。","九陌喧，千戶啓，满袖桂香风細。","杏园歡宴曲江濱，自此占芳辰。"]', '诗', 'shi', '', NULL, '喜遷鶯 二 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b976215-2fc2-4a5e-b513-94b30f55fa8f', '喜遷鶯 三', '喜遷鶯 三', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["清明節，雨晴天，得意正當年。","馬驕泥輭錦連乾，香袖半籠鞭。","花色融，人競賞，盡是繡鞍朱鞅。","日斜無計更留連，歸路草和煙。"]', '["清明節，雨晴天，得意正當年。","马驕泥輭錦連乾，香袖半籠鞭。","花色融，人競賞，尽是繡鞍朱鞅。","日斜無計更留連，归路草和煙。"]', '诗', 'shi', '', NULL, '喜遷鶯 三 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ece4cd01-14fc-47d7-9c4b-064387e04548', '小重山 一', '小重山 一', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["春到長門春草青，玉階華露滴，月朧明。","東風吹斷紫簫聲，宮漏促，簾外曉啼鸎。","愁極夢難成，紅妝流宿淚，不勝情。","手挼裙帶遶花行，思君切，羅幌暗塵生。"]', '["春到长门春草青，玉階华露滴，月朧明。","东风吹斷紫簫声，宮漏促，簾外晓啼鸎。","愁極梦难成，紅妝流宿泪，不勝情。","手挼裙带遶花行，思君切，羅幌暗塵生。"]', '诗', 'shi', '', NULL, '小重山 一 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd69bddb-b408-403a-aae5-6f933b556eba', '小重山 二', '小重山 二', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["秋到長門秋草黃，畫梁雙燕去，出宮牆。","玉簫無復理霓裳，金蟬墜，鸞鏡掩休妝。","憶昔在昭陽，舞衣紅綬帶，繡鴛鴦。","至今猶惹御爐香，魂夢斷，愁聽漏更長。"]', '["秋到长门秋草黄，畫梁雙燕去，出宮牆。","玉簫無复理霓裳，金蟬墜，鸾镜掩休妝。","憶昔在昭陽，舞衣紅綬带，繡鴛鴦。","至今猶惹御爐香，魂梦斷，愁听漏更长。"]', '诗', 'shi', '', NULL, '小重山 二 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('621866df-16cc-4e00-9fc3-6e138972cd4d', '離別難', '離別难', '862a1d64-7dd8-47a3-af21-84b7bf81cadd', '唐', '["寶馬曉鞴雕鞍，羅幃乍別情難。","那堪春景媚，送君千萬里。","半妝珠翠落，露華寒。","紅蠟燭，青絲曲，偏能鉤引淚闌干。","良夜促，香塵綠，魂欲迷，檀眉半歛愁低。","未別心先咽，欲語情難說。","出芳草，路東西，搖袖立。","春風急，櫻花楊柳雨淒淒。"]', '["寶马晓鞴雕鞍，羅幃乍別情难。","那堪春景媚，送君千万里。","半妝珠翠落，露华寒。","紅蠟燭，青絲曲，偏能鉤引泪闌干。","良夜促，香塵綠，魂欲迷，檀眉半歛愁低。","未別心先咽，欲語情难说。","出芳草，路东西，搖袖立。","春风急，櫻花楊柳雨淒淒。"]', '诗', 'shi', '', NULL, '離別難 薛昭藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd776d2c-d60f-4d40-819f-0bf2305e889b', '荷葉杯 一', '荷葉杯 一', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["春盡小庭花落，寂寞，凭檻歛雙眉。","忍教成病憶佳期，知摩知，知摩知。"]', '["春尽小庭花落，寂寞，凭檻歛雙眉。","忍教成病憶佳期，知摩知，知摩知。"]', '诗', 'shi', '', NULL, '荷葉杯 一 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c99f8073-f953-4830-8b7c-4a376737b59c', '荷葉杯 二', '荷葉杯 二', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["歌發誰家筵上，寥亮，別恨正悠悠。","蘭釭背帳月當樓，愁摩愁，愁摩愁。"]', '["歌發誰家筵上，寥亮，別恨正悠悠。","蘭釭背帳月當楼，愁摩愁，愁摩愁。"]', '诗', 'shi', '', NULL, '荷葉杯 二 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1add64d4-d58f-4234-9237-eddb78f2c41b', '荷葉杯 三', '荷葉杯 三', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["弱柳好花盡拆，晴陌，陌上少年郎。","滿身蘭麝撲人香，狂摩狂，狂摩狂。"]', '["弱柳好花尽拆，晴陌，陌上少年郎。","满身蘭麝撲人香，狂摩狂，狂摩狂。"]', '诗', 'shi', '', NULL, '荷葉杯 三 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40f51c32-1ac1-4946-9379-5d597d22e641', '荷葉杯 四', '荷葉杯 四', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["記得那時相見，膽戰，鬢亂四肢柔。","泥人無語不擡頭，羞摩羞，羞摩羞。"]', '["記得那时相见，膽戰，鬢亂四肢柔。","泥人無語不擡头，羞摩羞，羞摩羞。"]', '诗', 'shi', '', NULL, '荷葉杯 四 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c3ae759-2e64-44eb-89be-c9b42e5ec753', '荷葉杯 五', '荷葉杯 五', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["夜久歌聲怨咽，殘月，菊冷露微微。","看看濕透縷金衣，歸摩歸，歸摩歸。"]', '["夜久歌声怨咽，殘月，菊冷露微微。","看看濕透縷金衣，归摩归，归摩归。"]', '诗', 'shi', '', NULL, '荷葉杯 五 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3431cd28-c1d0-4ea5-968c-a75a50d1fbb1', '荷葉杯 六', '荷葉杯 六', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["我憶君詩最苦，知否，字字盡關心。","紅牋寫寄表情深，吟摩吟，吟摩吟。"]', '["我憶君诗最苦，知否，字字尽关心。","紅牋寫寄表情深，吟摩吟，吟摩吟。"]', '诗', 'shi', '', NULL, '荷葉杯 六 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64d1a1fc-ca20-47d8-abc5-818b233bee5f', '荷葉杯 七', '荷葉杯 七', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["金鴨香濃鴛被，枕膩，小髻簇花鈿。","腰如細柳臉如蓮，憐摩憐，憐摩憐。"]', '["金鴨香濃鴛被，枕膩，小髻簇花鈿。","腰如細柳臉如蓮，怜摩怜，怜摩怜。"]', '诗', 'shi', '', NULL, '荷葉杯 七 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('802f822e-0cd2-4b90-b26a-2130afb13fcb', '荷葉杯 八', '荷葉杯 八', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["曲砌蝶飛煙暖，春半，花發柳垂條。","花如雙臉柳如腰，嬌摩嬌，嬌摩嬌。"]', '["曲砌蝶飞煙暖，春半，花發柳垂條。","花如雙臉柳如腰，嬌摩嬌，嬌摩嬌。"]', '诗', 'shi', '', NULL, '荷葉杯 八 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df3d76ce-a335-4aa0-9519-2b248388d447', '荷葉杯 九', '荷葉杯 九', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["一去又乖期信，春盡，滿院長莓苔。","手挼裙帶獨裴回，來摩來，來摩來。"]', '["一去又乖期信，春尽，满院长莓苔。","手挼裙带独裴回，来摩来，来摩来。"]', '诗', 'shi', '', NULL, '荷葉杯 九 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36a4ffca-0fe5-49cc-86af-37546d863eb3', '甘州子 一', '甘州子 一', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["一爐龍麝錦帷傍，屏掩映，燭熒煌。","禁樓刁斗喜初長，羅薦繡鴛鴦。","山枕上，私語口脂香。"]', '["一爐龙麝錦帷傍，屏掩映，燭熒煌。","禁楼刁斗喜初长，羅薦繡鴛鴦。","山枕上，私語口脂香。"]', '诗', 'shi', '', NULL, '甘州子 一 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cac16ab8-5677-4025-8913-909c51a08233', '甘州子 二', '甘州子 二', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["每逢清夜與良晨，多悵望，足傷神。","雲迷水隔意中人，寂寞繡羅茵。","山枕上，幾點淚痕新。"]', '["每逢清夜與良晨，多悵望，足傷神。","云迷水隔意中人，寂寞繡羅茵。","山枕上，幾点泪痕新。"]', '诗', 'shi', '', NULL, '甘州子 二 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('870f9154-d5cf-4f4b-95e1-9ec1cd93c035', '甘州子 三', '甘州子 三', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["曾如劉阮訪仙蹤，深洞客，此時逢。","綺筵散後繡衾同，款曲見韶容。","山枕上，長是怯晨鐘。"]', '["曾如劉阮訪仙蹤，深洞客，此时逢。","綺筵散後繡衾同，款曲见韶容。","山枕上，长是怯晨鐘。"]', '诗', 'shi', '', NULL, '甘州子 三 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a1fa62b-3b65-44e6-a82a-f404ce3c71d7', '甘州子 四', '甘州子 四', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["露桃花裏小樓深，持玉盞，聽瑤琴。","醉歸青瑣入鴛衾，月色照衣襟。","山枕上，翠鈿鎮眉心。"]', '["露桃花裏小楼深，持玉盞，听瑤琴。","醉归青瑣入鴛衾，月色照衣襟。","山枕上，翠鈿鎮眉心。"]', '诗', 'shi', '', NULL, '甘州子 四 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9dda86c-9f52-41d5-b3c2-770b64504ec0', '甘州子 五', '甘州子 五', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["紅爐深夜醉調笙，敲拍處，玉纖輕。","小屏古畫岸低平，煙月滿閑庭。","山枕上，燈背臉波橫。"]', '["紅爐深夜醉調笙，敲拍处，玉纖轻。","小屏古畫岸低平，煙月满闲庭。","山枕上，灯背臉波橫。"]', '诗', 'shi', '', NULL, '甘州子 五 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('049cb1bf-f38e-43d3-9822-ba3ef690d210', '遐方怨', '遐方怨', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["簾影細，簟文平。","象紗籠玉指，縷金羅扇輕。","嫩紅雙臉似花明，兩條眉黛遠山橫。","鳳簫歇，鏡塵生。","遼塞音書絕，夢魂長暗驚。","玉郎經歲負娉婷，教人爭不恨無情。"]', '["簾影細，簟文平。","象紗籠玉指，縷金羅扇轻。","嫩紅雙臉似花明，兩條眉黛远山橫。","鳳簫歇，镜塵生。","遼塞音书絕，梦魂长暗驚。","玉郎經歲負娉婷，教人爭不恨無情。"]', '诗', 'shi', '', NULL, '遐方怨 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f5f3f92-b322-4196-834e-9a7e3ae52144', '訴衷情 一', '訴衷情 一', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["香滅簾垂春漏永，整鴛衾。","羅帶重，雙鳳，縷黃金。","窗外月光臨，沈沈。","斷腸無處尋，負春心。"]', '["香滅簾垂春漏永，整鴛衾。","羅带重，雙鳳，縷黄金。","窗外月光臨，沈沈。","斷腸無处尋，負春心。"]', '诗', 'shi', '', NULL, '訴衷情 一 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72a704aa-0451-4ec5-99f3-9f7947e78348', '訴衷情 二', '訴衷情 二', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["永夜拋人何處去，絕來音。","香閣掩，眉歛，月將沈。","爭忍不相尋，怨孤衾。","換我心，爲你心，始知相憶深。"]', '["永夜拋人何处去，絕来音。","香閣掩，眉歛，月將沈。","爭忍不相尋，怨孤衾。","換我心，爲你心，始知相憶深。"]', '诗', 'shi', '', NULL, '訴衷情 二 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc74db08-9576-4606-9792-ba41a18f5656', '楊柳枝', '楊柳枝', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["秋夜香閨思寂寥，漏迢迢。","鴛幃羅幌麝煙銷，燭光搖。","正憶玉郎遊蕩去，無尋處。","更聞簾外雨瀟瀟，滴芭蕉。"]', '["秋夜香閨思寂寥，漏迢迢。","鴛幃羅幌麝煙銷，燭光搖。","正憶玉郎游蕩去，無尋处。","更闻簾外雨瀟瀟，滴芭蕉。"]', '诗', 'shi', '', NULL, '楊柳枝 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff663360-0acf-43c4-aa4d-b8c76ad192f8', '醉公子 一', '醉公子 一', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["漠漠秋雲澹，紅藕香侵檻。","枕倚小山屏，金鋪向晚扃。","睡起橫波慢，獨望情何限。","衰柳數聲蟬，魂銷似去年。"]', '["漠漠秋云澹，紅藕香侵檻。","枕倚小山屏，金鋪向晚扃。","睡起橫波慢，独望情何限。","衰柳數声蟬，魂銷似去年。"]', '诗', 'shi', '', NULL, '醉公子 一 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e4696b9-336e-487b-90c3-794a5b394f48', '醉公子 二', '醉公子 二', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["岸柳垂金線，雨晴鸎百轉。","家住綠楊邊，往來多少年。","馬嘶芳草遠，高樓簾半卷。","歛袖翠蛾攢，相逢爾許難。"]', '["岸柳垂金線，雨晴鸎百轉。","家住綠楊邊，往来多少年。","马嘶芳草远，高楼簾半卷。","歛袖翠蛾攢，相逢爾許难。"]', '诗', 'shi', '', NULL, '醉公子 二 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('613e493c-3f2b-4d3b-89e1-d1405c0d668c', '酒泉子 一', '酒泉子 一', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["楊柳舞風，輕惹春煙殘雨。","杏花愁，鸎正語，畫樓東。","錦屏寂寞思無窮，還是不知消息。","鏡塵生，珠淚滴，損儀容。"]', '["楊柳舞风，轻惹春煙殘雨。","杏花愁，鸎正語，畫楼东。","錦屏寂寞思無窮，還是不知消息。","镜塵生，珠泪滴，損儀容。"]', '诗', 'shi', '', NULL, '酒泉子 一 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6ca68af-4fb5-46df-aa7b-6a2bfcbb0eed', '酒泉子 二', '酒泉子 二', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["羅帶縷金，蘭麝煙凝魂斷。","畫屏欹，雲鬢亂，恨難任。","幾回垂淚滴鴛衾，薄情何處去？","月臨窗，花滿樹，信沈沈。"]', '["羅带縷金，蘭麝煙凝魂斷。","畫屏欹，云鬢亂，恨难任。","幾回垂泪滴鴛衾，薄情何处去？","月臨窗，花满樹，信沈沈。"]', '诗', 'shi', '', NULL, '酒泉子 二 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c831077-1110-48a0-9a47-9a3ace3db7eb', '酒泉子 三', '酒泉子 三', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["小檻日斜，風度綠窗人悄悄，翠幃閑掩舞雙鸞，舊香寒。","別來情緒轉難判，韶顏看却老，依稀粉上有啼痕，暗銷魂。"]', '["小檻日斜，风度綠窗人悄悄，翠幃闲掩舞雙鸾，旧香寒。","別来情緒轉难判，韶顏看却老，依稀粉上有啼痕，暗銷魂。"]', '诗', 'shi', '', NULL, '酒泉子 三 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f1ba8f5-3d46-48a6-aeb5-2041526c8226', '酒泉子 四', '酒泉子 四', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["黛薄紅深，約掠綠鬟雲膩。","小鴛鴦，金翡翠，稱人心。","錦鱗無處傳幽意，海燕蘭堂春又去。","隔年書，千點淚，恨難任。"]', '["黛薄紅深，約掠綠鬟云膩。","小鴛鴦，金翡翠，稱人心。","錦鱗無处傳幽意，海燕蘭堂春又去。","隔年书，千点泪，恨难任。"]', '诗', 'shi', '', NULL, '酒泉子 四 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2b50c8c-4a3c-4558-83ac-45f9c02dfea8', '酒泉子 五', '酒泉子 五', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["掩却菱花，收拾翠鈿休上面，金蟲玉燕鎖香匳，恨厭厭。","雲鬟半墜嬾重篸，淚侵山枕濕，銀燈背帳夢方酣，鴈飛南。"]', '["掩却菱花，收拾翠鈿休上面，金蟲玉燕鎖香匳，恨厭厭。","云鬟半墜嬾重篸，泪侵山枕濕，銀灯背帳梦方酣，鴈飞南。"]', '诗', 'shi', '', NULL, '酒泉子 五 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d96547e-54d0-425c-ab06-828fb8c5d7c1', '酒泉子 六', '酒泉子 六', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["水碧風清，入檻細香紅藕膩，謝娘歛翠恨無涯，小屏斜。","堪憎蕩子不還家，謾留羅帶結，帳深枕膩炷沈煙，負當年。"]', '["水碧风清，入檻細香紅藕膩，謝娘歛翠恨無涯，小屏斜。","堪憎蕩子不還家，謾留羅带結，帳深枕膩炷沈煙，負當年。"]', '诗', 'shi', '', NULL, '酒泉子 六 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45729378-54a0-466a-ace5-32f10d80b6b4', '酒泉子 七', '酒泉子 七', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["黛怨紅羞，掩映畫堂春欲暮，殘花微雨隔青樓，思悠悠。","芳菲時節看將度，寂寞無人還獨語。","畫羅襦，香粉汙，不勝愁。"]', '["黛怨紅羞，掩映畫堂春欲暮，殘花微雨隔青楼，思悠悠。","芳菲时節看將度，寂寞無人還独語。","畫羅襦，香粉汙，不勝愁。"]', '诗', 'shi', '', NULL, '酒泉子 七 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c04d0a2-2e11-4502-9488-60801566f9e2', '浣溪沙 一', '浣溪沙 一', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["春色迷人恨正賒，可堪蕩子不還家，細風輕露著梨花。","簾外有情雙燕颺，檻前無力綠楊斜，小屏狂夢極天涯。"]', '["春色迷人恨正賒，可堪蕩子不還家，細风轻露著梨花。","簾外有情雙燕颺，檻前無力綠楊斜，小屏狂梦極天涯。"]', '诗', 'shi', '', NULL, '浣溪沙 一 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99835811-9071-4470-b901-4b134495a9ae', '浣溪沙 二', '浣溪沙 二', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["紅藕香寒翠渚平，月籠虛閣夜蛩清，塞鴻驚夢兩牽情。","寶帳玉爐殘麝冷，羅衣金縷暗塵生，小窗孤燭淚縱橫。"]', '["紅藕香寒翠渚平，月籠虛閣夜蛩清，塞鴻驚梦兩牽情。","寶帳玉爐殘麝冷，羅衣金縷暗塵生，小窗孤燭泪縱橫。"]', '诗', 'shi', '', NULL, '浣溪沙 二 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0521438c-f57a-46fe-a246-175006f5949f', '浣溪沙 三', '浣溪沙 三', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["荷芰風輕簾幕香，繡衣鸂鶒泳回塘，小屏閑掩舊瀟湘。","恨入空幃鸞影獨，淚凝雙臉渚蓮光，薄情年少悔思量。"]', '["荷芰风轻簾幕香，繡衣鸂鶒泳回塘，小屏闲掩旧瀟湘。","恨入空幃鸾影独，泪凝雙臉渚蓮光，薄情年少悔思量。"]', '诗', 'shi', '', NULL, '浣溪沙 三 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28919d53-623b-4b5f-b7cd-8e3472b25b3b', '浣溪沙 四', '浣溪沙 四', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["惆悵經年別謝娘，月窗花院好風光，此時相望最情傷。","青鳥不來傳錦字，瑤姬何處鎖蘭房，忍教魂夢兩茫茫。"]', '["惆悵經年別謝娘，月窗花院好风光，此时相望最情傷。","青鸟不来傳錦字，瑤姬何处鎖蘭房，忍教魂梦兩茫茫。"]', '诗', 'shi', '', NULL, '浣溪沙 四 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03b8f0fd-4940-4f6d-aea8-7a5793efecb8', '浣溪沙 五', '浣溪沙 五', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["庭菊飄黃玉露濃，冷莎偎砌隱鳴蛩，何期良夜得相逢。","背帳風搖紅蠟滴，惹香煖夢繡衾重，覺來枕上怯晨鐘。"]', '["庭菊飄黄玉露濃，冷莎偎砌隐鳴蛩，何期良夜得相逢。","背帳风搖紅蠟滴，惹香煖梦繡衾重，覺来枕上怯晨鐘。"]', '诗', 'shi', '', NULL, '浣溪沙 五 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5cb5a45-acbb-4294-ba9b-861e7cc19686', '浣溪沙 六', '浣溪沙 六', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["雲澹風高葉亂飛，小庭寒雨綠苔微，深閨人靜掩屏帷。","粉黛暗愁金帶枕，鴛鴦空繞畫羅衣，那堪孤負不思歸。"]', '["云澹风高葉亂飞，小庭寒雨綠苔微，深閨人静掩屏帷。","粉黛暗愁金带枕，鴛鴦空繞畫羅衣，那堪孤負不思归。"]', '诗', 'shi', '', NULL, '浣溪沙 六 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1873c0c1-faea-4424-b1c7-4ae7d795ee68', '浣溪沙 七', '浣溪沙 七', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["鴈響遙天玉漏清，小紗窗外月朧明，翠幃金鴨炷香平。","何處不歸音信斷，良宵空使夢魂驚，簟涼枕冷不勝情。"]', '["鴈响遙天玉漏清，小紗窗外月朧明，翠幃金鴨炷香平。","何处不归音信斷，良宵空使梦魂驚，簟涼枕冷不勝情。"]', '诗', 'shi', '', NULL, '浣溪沙 七 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d33243a-07c2-4629-ac0d-12d902e2d65b', '浣溪沙 八', '浣溪沙 八', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["露白蟾明又到秋，佳期幽會兩悠悠，夢牽情役幾時休。","記得泥人微歛黛，無言斜倚小書樓，暗思前事不勝愁。"]', '["露白蟾明又到秋，佳期幽會兩悠悠，梦牽情役幾时休。","記得泥人微歛黛，無言斜倚小书楼，暗思前事不勝愁。"]', '诗', 'shi', '', NULL, '浣溪沙 八 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76f19d19-5cd8-40b0-8365-2473346fc488', '更漏子', '更漏子', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["舊歡娛，新悵望，擁鼻含嚬樓上。","濃柳翠，晚霞微，江鷗接翼飛。","簾半卷，屏斜掩，遠岫參差迷眼。","歌滿耳，酒盈尊，前非不要論。"]', '["旧歡娛，新悵望，擁鼻含嚬楼上。","濃柳翠，晚霞微，江鷗接翼飞。","簾半卷，屏斜掩，远岫參差迷眼。","歌满耳，酒盈尊，前非不要論。"]', '诗', 'shi', '', NULL, '更漏子 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df8d896d-f1fa-41bd-86ff-bd9ed1bf2d92', '應天長', '應天长', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["瑟瑟羅裙金線縷，輕透鵝黃香畫袴。","垂交帶，盤鸚鵡，嫋嫋翠翹移玉步。","背人勻檀注，慢轉嬌波偷覷。","歛黛春情暗許，倚屏慵不語。"]', '["瑟瑟羅裙金線縷，轻透鵝黄香畫袴。","垂交带，盤鸚鵡，嫋嫋翠翹移玉步。","背人勻檀注，慢轉嬌波偷覷。","歛黛春情暗許，倚屏慵不語。"]', '诗', 'shi', '', NULL, '應天長 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a663e75-3efb-4699-87cc-0d8195888d63', '漁歌子', '漁歌子', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["曉風清，幽沼綠，倚闌凝望珍禽浴。","畫簾垂，翠屏曲，滿袖荷香馥郁。","好攄懷，堪寓目，身閑心靜平生足。","酒杯深，光影促，名利無心較逐。"]', '["晓风清，幽沼綠，倚闌凝望珍禽浴。","畫簾垂，翠屏曲，满袖荷香馥郁。","好攄懷，堪寓目，身闲心静平生足。","酒杯深，光影促，名利無心較逐。"]', '诗', 'shi', '', NULL, '漁歌子 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5ab8295-95f0-4c11-815f-85e362c91023', '河傳 一', '河傳 一', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["燕颺，晴景。","小窗屏暖，鴛鴦交頸。","菱花掩却翠鬟欹，慵整，海棠簾外影。","繡幃香斷金鸂鶒，無消息。","心事空相憶，倚東風。","春正濃，愁紅，淚痕衣上重。"]', '["燕颺，晴景。","小窗屏暖，鴛鴦交頸。","菱花掩却翠鬟欹，慵整，海棠簾外影。","繡幃香斷金鸂鶒，無消息。","心事空相憶，倚东风。","春正濃，愁紅，泪痕衣上重。"]', '诗', 'shi', '', NULL, '河傳 一 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d93f07d0-9d04-4b51-8897-d3c0c53598fa', '河傳 二', '河傳 二', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["曲檻，春晚。","碧流紋細，綠楊絲輭。","露華鮮，杏枝繁，鸎轉，野蕪平似翦。","直是人間到天上，堪遊賞。","醉眼疑屏障，對池塘。","惜韶光，斷腸，爲花須盡狂。"]', '["曲檻，春晚。","碧流紋細，綠楊絲輭。","露华鲜，杏枝繁，鸎轉，野蕪平似翦。","直是人间到天上，堪游賞。","醉眼疑屏障，对池塘。","惜韶光，斷腸，爲花須尽狂。"]', '诗', 'shi', '', NULL, '河傳 二 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b56f91d-cd8a-450d-bf8a-eba82df464c9', '河傳 三', '河傳 三', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["櫂舉，舟去。","波光渺渺，不知何處。","岸花汀草共依依，雨微，鷓鴣相逐飛。","天涯離恨江聲咽，啼猿切。","此意向誰說，倚蘭橈。","獨無憀，魂銷，小爐香欲焦。"]', '["櫂舉，舟去。","波光渺渺，不知何处。","岸花汀草共依依，雨微，鷓鴣相逐飞。","天涯離恨江声咽，啼猿切。","此意向誰说，倚蘭橈。","独無憀，魂銷，小爐香欲焦。"]', '诗', 'shi', '', NULL, '河傳 三 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fcfcb95-6258-4002-9dc3-74c0e99efb2c', '木蘭花 一', '木蘭花 一', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["月照玉樓春漏促，颯颯風搖庭砌竹。","夢驚鴛被覺來時，何處管弦聲斷續。","惆悵少年遊冶去，枕上兩蛾攢細綠。","曉鶯簾外語花枝，背帳猶殘紅蠟燭。"]', '["月照玉楼春漏促，颯颯风搖庭砌竹。","梦驚鴛被覺来时，何处管弦声斷續。","惆悵少年游冶去，枕上兩蛾攢細綠。","晓鶯簾外語花枝，背帳猶殘紅蠟燭。"]', '诗', 'shi', '', NULL, '木蘭花 一 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fddd4bd-ea76-4833-879a-a1e34866b050', '木蘭花 二', '木蘭花 二', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["柳映玉樓春日晚，雨細風輕煙草輭。","畫堂鸚鵡語雕籠，金粉小屏猶半掩。","香滅繡幃人寂寂，倚檻無言愁思遠。","恨郎何處縱疎狂，長使含啼眉不展。"]', '["柳映玉楼春日晚，雨細风轻煙草輭。","畫堂鸚鵡語雕籠，金粉小屏猶半掩。","香滅繡幃人寂寂，倚檻無言愁思远。","恨郎何处縱疎狂，长使含啼眉不展。"]', '诗', 'shi', '', NULL, '木蘭花 二 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61dbe539-7ecb-47bf-b5ff-405b3f234aa2', '木蘭花 三', '木蘭花 三', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["月皎露華窗影細，風送菊香黏繡袂。","博山爐冷水沈微，惆悵金閨終日閉。","嬾展羅衾垂玉筯，羞對菱花篸寶髻。","良宵好事枉教休，無計那他狂耍壻。"]', '["月皎露华窗影細，风送菊香黏繡袂。","博山爐冷水沈微，惆悵金閨終日閉。","嬾展羅衾垂玉筯，羞对菱花篸寶髻。","良宵好事枉教休，無計那他狂耍壻。"]', '诗', 'shi', '', NULL, '木蘭花 三 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a44c134-659e-4de2-a6f3-104a0df64693', '木蘭花 四', '木蘭花 四', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["拂水雙飛來去燕，曲檻小屏山六扇。","春愁凝思結眉心，綠綺嬾調紅錦薦。","話別情多聲欲戰，玉筯痕留紅粉面。","鎮長獨立到黃昏，却怕良宵頻夢見。"]', '["拂水雙飞来去燕，曲檻小屏山六扇。","春愁凝思結眉心，綠綺嬾調紅錦薦。","話別情多声欲戰，玉筯痕留紅粉面。","鎮长独立到黄昏，却怕良宵頻梦见。"]', '诗', 'shi', '', NULL, '木蘭花 四 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a4f0e21-34f5-4e8e-85aa-6010fa5b0ad9', '虞美人 一', '虞美人 一', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["曉鶯啼破相思夢，簾卷金泥鳳。","宿妝猶在酒初醒，翠翹慵整倚雲屏，轉娉婷。","香檀細畫侵桃臉，羅袂輕輕歛。","佳期堪恨再難尋，綠蕪滿院柳成陰，負春心。"]', '["晓鶯啼破相思梦，簾卷金泥鳳。","宿妝猶在酒初醒，翠翹慵整倚云屏，轉娉婷。","香檀細畫侵桃臉，羅袂轻轻歛。","佳期堪恨再难尋，綠蕪满院柳成陰，負春心。"]', '诗', 'shi', '', NULL, '虞美人 一 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7175e3f2-5b3c-4f18-b6a0-9f2f1dffafe4', '虞美人 二', '虞美人 二', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["觸簾風送景陽鐘，鴛被繡花重。","曉幃初卷冷煙濃，翠勻粉黛好儀容，思嬌慵。","起來無語理朝妝，寶匣鏡凝光。","綠荷相倚滿池塘，露清枕簟藕花香，恨悠揚。"]', '["觸簾风送景陽鐘，鴛被繡花重。","晓幃初卷冷煙濃，翠勻粉黛好儀容，思嬌慵。","起来無語理朝妝，寶匣镜凝光。","綠荷相倚满池塘，露清枕簟藕花香，恨悠揚。"]', '诗', 'shi', '', NULL, '虞美人 二 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('433d2d68-8d02-4fc5-a676-ba87f0e4c8c4', '虞美人 三', '虞美人 三', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["翠屏閑掩垂珠箔，絲雨籠池閣。","露黏紅藕咽清香，謝娘嬌極不成狂，罷朝妝。","小金鸂鶒沈煙細，膩枕堆雲髻。","淺眉微歛注檀輕，舊歡時有夢魂驚，悔多情。"]', '["翠屏闲掩垂珠箔，絲雨籠池閣。","露黏紅藕咽清香，謝娘嬌極不成狂，罷朝妝。","小金鸂鶒沈煙細，膩枕堆云髻。","淺眉微歛注檀轻，旧歡时有梦魂驚，悔多情。"]', '诗', 'shi', '', NULL, '虞美人 三 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7d4c10c-978d-4caf-8a52-bf48b0a87b9f', '虞美人 四', '虞美人 四', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["碧梧桐映紗窗晚，花謝鶯聲嬾。","小屏屈曲掩青山，翠幃香粉玉爐寒，兩蛾攢。","顛狂年少輕離別，孤負春時節。","畫羅紅袂有啼痕，魂銷無語倚閨門，欲黃昏。"]', '["碧梧桐映紗窗晚，花謝鶯声嬾。","小屏屈曲掩青山，翠幃香粉玉爐寒，兩蛾攢。","顛狂年少轻離別，孤負春时節。","畫羅紅袂有啼痕，魂銷無語倚閨门，欲黄昏。"]', '诗', 'shi', '', NULL, '虞美人 四 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9209b807-2c7a-4df3-ba38-51a4f66e506a', '虞美人 五', '虞美人 五', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["深閨春色勞思想，恨共春蕪長。","黃鸝嬌轉泥芳妍，杏枝如畫倚輕煙，鎖窗前。","凭闌愁立雙蛾細，柳影斜搖砌。","玉郎還是不還家，教人魂夢逐楊花，繞天涯。"]', '["深閨春色勞思想，恨共春蕪长。","黄鸝嬌轉泥芳妍，杏枝如畫倚轻煙，鎖窗前。","凭闌愁立雙蛾細，柳影斜搖砌。","玉郎還是不還家，教人魂梦逐楊花，繞天涯。"]', '诗', 'shi', '', NULL, '虞美人 五 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37479f94-c7da-46bd-af24-cfc94db6a2e4', '虞美人 六', '虞美人 六', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["少年豔質勝瓊英，早晚別三清。","蓮冠穩篸鈿箆橫，飄飄羅袖碧雲輕，畫難成。","遲遲少轉腰身嫋，翠靨眉心小。","醮壇風急杏枝香，此時恨不駕鸞皇，訪劉郎。"]', '["少年豔質勝瓊英，早晚別三清。","蓮冠穩篸鈿箆橫，飄飄羅袖碧云轻，畫难成。","遲遲少轉腰身嫋，翠靨眉心小。","醮壇风急杏枝香，此时恨不駕鸾皇，訪劉郎。"]', '诗', 'shi', '', NULL, '虞美人 六 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58152f9a-1a8c-487f-a1fb-2b7179e82604', '臨江仙 一', '臨江仙 一', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["碧染長空池似鏡，倚樓閑望凝情。","滿衣紅藕細香清。","象牀珍簟，山障掩，玉琴橫。","暗想昔時歡笑事，如今贏得愁生。","博山爐煖澹煙輕。","蟬吟人靜，殘日傍，小窗明。"]', '["碧染长空池似镜，倚楼闲望凝情。","满衣紅藕細香清。","象牀珍簟，山障掩，玉琴橫。","暗想昔时歡笑事，如今贏得愁生。","博山爐煖澹煙轻。","蟬吟人静，殘日傍，小窗明。"]', '诗', 'shi', '', NULL, '臨江仙 一 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f3340e4-e053-4ec3-8e3f-21e3adae893b', '臨江仙 二', '臨江仙 二', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["幽閨小檻春光晚，柳濃花澹鶯稀。","舊歡思想尚依依。","翠嚬紅歛，終日損芳菲。","何事狂夫音信斷，不如梁燕猶歸。","畫堂深處麝煙微。","屏虛枕冷，風細雨霏霏。"]', '["幽閨小檻春光晚，柳濃花澹鶯稀。","旧歡思想尚依依。","翠嚬紅歛，終日損芳菲。","何事狂夫音信斷，不如梁燕猶归。","畫堂深处麝煙微。","屏虛枕冷，风細雨霏霏。"]', '诗', 'shi', '', NULL, '臨江仙 二 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d9a9bf0-5df5-4f36-b20d-58fae6822d6b', '臨江仙 三', '臨江仙 三', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["月色穿簾風入竹，倚屏雙黛愁時。","砌花含露兩三枝。","如啼恨臉，魂斷損容儀。","香燼暗銷金鴨冷，可堪孤負前期。","繡襦不整鬢鬟攲。","幾多惆悵，情緒在天涯。"]', '["月色穿簾风入竹，倚屏雙黛愁时。","砌花含露兩三枝。","如啼恨臉，魂斷損容儀。","香燼暗銷金鴨冷，可堪孤負前期。","繡襦不整鬢鬟攲。","幾多惆悵，情緒在天涯。"]', '诗', 'shi', '', NULL, '臨江仙 三 顧敻 shi');
